     //-----------------------------------------------------------
     // synopsys translate_off
     initial begin
        wait(ARESETn==1'b0);
        wait(ARESETn==1'b1);
        repeat (2) @ (posedge ACLK);
        if ((1<<WIDTH_CID)<NUM_MASTER) begin
            $display("%m ERROR channel ID width (%2d) should be large enough to hold number %2d",
                        WIDTH_CID, NUM_MASTER);
        end
        if (M0_MID===M1_MID) begin
            $display("%m ERROR each master should have unique ID, but M0_MID:%d M1_MID:%d",
                      M0_MID, M1_MID);
        end
        if (M0_MID===M2_MID) begin
            $display("%m ERROR each master should have unique ID, but M0_MID:%d M2_MID:%d",
                      M0_MID, M2_MID);
        end
        if (M0_MID===M3_MID) begin
            $display("%m ERROR each master should have unique ID, but M0_MID:%d M3_MID:%d",
                      M0_MID, M3_MID);
        end
        if (M1_MID===M2_MID) begin
            $display("%m ERROR each master should have unique ID, but M1_MID:%d M2_MID:%d",
                      M1_MID, M2_MID);
        end
        if (M1_MID===M3_MID) begin
            $display("%m ERROR each master should have unique ID, but M1_MID:%d M3_MID:%d",
                      M1_MID, M3_MID);
        end
        if (M2_MID===M3_MID) begin
            $display("%m ERROR each master should have unique ID, but M2_MID:%d M3_MID:%d",
                      M2_MID, M3_MID);
        end
     end
     localparam ADDR_END0 = ADDR_BASE0 + (1<<ADDR_LENGTH0) - 1
              , ADDR_END1 = ADDR_BASE1 + (1<<ADDR_LENGTH1) - 1
              , ADDR_END2 = ADDR_BASE2 + (1<<ADDR_LENGTH2) - 1
              , ADDR_END3 = ADDR_BASE3 + (1<<ADDR_LENGTH3) - 1
              ;
     initial begin
         if ((SLAVE_EN0==1)&&(ADDR_BASE0[ADDR_LENGTH0-1:0]!=0)) $display("%m ERROR slave 0 starting address should be a multiple of size.");
         if ((SLAVE_EN1==1)&&(ADDR_BASE1[ADDR_LENGTH1-1:0]!=0)) $display("%m ERROR slave 1 starting address should be a multiple of size.");
         if ((SLAVE_EN2==1)&&(ADDR_BASE2[ADDR_LENGTH2-1:0]!=0)) $display("%m ERROR slave 2 starting address should be a multiple of size.");
         if ((SLAVE_EN3==1)&&(ADDR_BASE3[ADDR_LENGTH3-1:0]!=0)) $display("%m ERROR slave 3 starting address should be a multiple of size.");
         if ((ADDR_END0>=ADDR_BASE1)&&(ADDR_END0<=ADDR_END1)) $display("%m ERROR AXI address 0 and 1 overlapped 0x%08X:%08X:%08X", ADDR_END0, ADDR_BASE1, ADDR_END1);
         if ((ADDR_END0>=ADDR_BASE2)&&(ADDR_END0<=ADDR_END2)) $display("%m ERROR AXI address 0 and 2 overlapped 0x%08X:%08X:%08X", ADDR_END0, ADDR_BASE2, ADDR_END2);
         if ((ADDR_END0>=ADDR_BASE3)&&(ADDR_END0<=ADDR_END3)) $display("%m ERROR AXI address 0 and 3 overlapped 0x%08X:%08X:%08X", ADDR_END0, ADDR_BASE3, ADDR_END3);
         if ((ADDR_END1>=ADDR_BASE0)&&(ADDR_END1<=ADDR_END0)) $display("%m ERROR AXI address 1 and 0 overlapped 0x%08X:%08X:%08X", ADDR_END1, ADDR_BASE0, ADDR_END0);
         if ((ADDR_END1>=ADDR_BASE2)&&(ADDR_END1<=ADDR_END2)) $display("%m ERROR AXI address 1 and 2 overlapped 0x%08X:%08X:%08X", ADDR_END1, ADDR_BASE2, ADDR_END2);
         if ((ADDR_END1>=ADDR_BASE3)&&(ADDR_END1<=ADDR_END3)) $display("%m ERROR AXI address 1 and 3 overlapped 0x%08X:%08X:%08X", ADDR_END1, ADDR_BASE3, ADDR_END3);
         if ((ADDR_END2>=ADDR_BASE0)&&(ADDR_END2<=ADDR_END0)) $display("%m ERROR AXI address 2 and 0 overlapped 0x%08X:%08X:%08X", ADDR_END2, ADDR_BASE0, ADDR_END0);
         if ((ADDR_END2>=ADDR_BASE1)&&(ADDR_END2<=ADDR_END1)) $display("%m ERROR AXI address 2 and 1 overlapped 0x%08X:%08X:%08X", ADDR_END2, ADDR_BASE1, ADDR_END1);
         if ((ADDR_END2>=ADDR_BASE3)&&(ADDR_END2<=ADDR_END3)) $display("%m ERROR AXI address 2 and 3 overlapped 0x%08X:%08X:%08X", ADDR_END2, ADDR_BASE3, ADDR_END3);
         if ((ADDR_END3>=ADDR_BASE0)&&(ADDR_END3<=ADDR_END0)) $display("%m ERROR AXI address 3 and 0 overlapped 0x%08X:%08X:%08X", ADDR_END3, ADDR_BASE0, ADDR_END0);
         if ((ADDR_END3>=ADDR_BASE1)&&(ADDR_END3<=ADDR_END1)) $display("%m ERROR AXI address 3 and 1 overlapped 0x%08X:%08X:%08X", ADDR_END3, ADDR_BASE1, ADDR_END1);
         if ((ADDR_END3>=ADDR_BASE2)&&(ADDR_END3<=ADDR_END2)) $display("%m ERROR AXI address 3 and 2 overlapped 0x%08X:%08X:%08X", ADDR_END3, ADDR_BASE2, ADDR_END2);
     end
     // synopsys translate_on
     //-----------------------------------------------------------
endmodule

//---------------------------------------------------------------------------
// AXI Security Firewall Module
//---------------------------------------------------------------------------
module axi_firewall
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , WIDTH_ID   = 4)
(
      input  wire                    clk
    , input  wire                    rst_n
    // Security configuration
    , input  wire [NUM_MASTER-1:0]  master_secure
    , input  wire [NUM_SLAVE-1:0]   slave_secure
    , input  wire [NUM_SLAVE-1:0]   slave_nonsec_allowed
    // Master 0 interface
    , input  wire [WIDTH_ID-1:0]    m0_awid
    , input  wire [WIDTH_AD-1:0]    m0_awaddr
    , input  wire [7:0]              m0_awlen
    , input  wire [2:0]              m0_awprot
    , input  wire                   m0_awvalid
    , input  wire [WIDTH_ID-1:0]    m0_arid
    , input  wire [WIDTH_AD-1:0]    m0_araddr
    , input  wire [7:0]              m0_arlen
    , input  wire [2:0]              m0_arprot
    , input  wire                   m0_arvalid
    // Master 1 interface
    , input  wire [WIDTH_ID-1:0]    m1_awid
    , input  wire [WIDTH_AD-1:0]    m1_awaddr
    , input  wire [7:0]              m1_awlen
    , input  wire [2:0]              m1_awprot
    , input  wire                   m1_awvalid
    , input  wire [WIDTH_ID-1:0]    m1_arid
    , input  wire [WIDTH_AD-1:0]    m1_araddr
    , input  wire [7:0]              m1_arlen
    , input  wire [2:0]              m1_arprot
    , input  wire                   m1_arvalid
    // Master 2 interface
    , input  wire [WIDTH_ID-1:0]    m2_awid
    , input  wire [WIDTH_AD-1:0]    m2_awaddr
    , input  wire [7:0]              m2_awlen
    , input  wire [2:0]              m2_awprot
    , input  wire                   m2_awvalid
    , input  wire [WIDTH_ID-1:0]    m2_arid
    , input  wire [WIDTH_AD-1:0]    m2_araddr
    , input  wire [7:0]              m2_arlen
    , input  wire [2:0]              m2_arprot
    , input  wire                   m2_arvalid
    // Master 3 interface
    , input  wire [WIDTH_ID-1:0]    m3_awid
    , input  wire [WIDTH_AD-1:0]    m3_awaddr
    , input  wire [7:0]              m3_awlen
    , input  wire [2:0]              m3_awprot
    , input  wire                   m3_awvalid
    , input  wire [WIDTH_ID-1:0]    m3_arid
    , input  wire [WIDTH_AD-1:0]    m3_araddr
    , input  wire [7:0]              m3_arlen
    , input  wire [2:0]              m3_arprot
    , input  wire                   m3_arvalid
    , input  wire [1:0] m0_aw_slave_sel // 4 slaves
    , input  wire [1:0] m0_ar_slave_sel
    , input  wire [1:0] m1_aw_slave_sel // 4 slaves
    , input  wire [1:0] m1_ar_slave_sel
    , input  wire [1:0] m2_aw_slave_sel // 4 slaves
    , input  wire [1:0] m2_ar_slave_sel
    , input  wire [1:0] m3_aw_slave_sel // 4 slaves
    , input  wire [1:0] m3_ar_slave_sel
    // Security violation outputs
    , output reg  [NUM_MASTER-1:0]  aw_violation
    , output reg  [NUM_MASTER-1:0]  ar_violation
    , output reg  [NUM_MASTER-1:0]  aw_block
    , output reg  [NUM_MASTER-1:0]  ar_block
    , output reg                    security_alert
    // Master 0 error responses
    , output reg  [WIDTH_ID-1:0]    m0_bid_err
    , output reg  [1:0]              m0_bresp_err
    , output reg                    m0_bvalid_err
    , input  wire                   m0_bready
    , output reg  [WIDTH_ID-1:0]    m0_rid_err
    , output reg  [WIDTH_DA-1:0]    m0_rdata_err
    , output reg  [1:0]              m0_rresp_err
    , output reg                    m0_rlast_err
    , output reg                    m0_rvalid_err
    , input  wire                   m0_rready
    // Master 1 error responses
    , output reg  [WIDTH_ID-1:0]    m1_bid_err
    , output reg  [1:0]              m1_bresp_err
    , output reg                    m1_bvalid_err
    , input  wire                   m1_bready
    , output reg  [WIDTH_ID-1:0]    m1_rid_err
    , output reg  [WIDTH_DA-1:0]    m1_rdata_err
    , output reg  [1:0]              m1_rresp_err
    , output reg                    m1_rlast_err
    , output reg                    m1_rvalid_err
    , input  wire                   m1_rready
    // Master 2 error responses
    , output reg  [WIDTH_ID-1:0]    m2_bid_err
    , output reg  [1:0]              m2_bresp_err
    , output reg                    m2_bvalid_err
    , input  wire                   m2_bready
    , output reg  [WIDTH_ID-1:0]    m2_rid_err
    , output reg  [WIDTH_DA-1:0]    m2_rdata_err
    , output reg  [1:0]              m2_rresp_err
    , output reg                    m2_rlast_err
    , output reg                    m2_rvalid_err
    , input  wire                   m2_rready
    // Master 3 error responses
    , output reg  [WIDTH_ID-1:0]    m3_bid_err
    , output reg  [1:0]              m3_bresp_err
    , output reg                    m3_bvalid_err
    , input  wire                   m3_bready
    , output reg  [WIDTH_ID-1:0]    m3_rid_err
    , output reg  [WIDTH_DA-1:0]    m3_rdata_err
    , output reg  [1:0]              m3_rresp_err
    , output reg                    m3_rlast_err
    , output reg                    m3_rvalid_err
    , input  wire                   m3_rready
);

    // Violation tracking
    reg [31:0] violation_count;
    reg [WIDTH_ID-1:0] last_violation_id;
    reg [WIDTH_AD-1:0] last_violation_addr;
    reg last_violation_is_write;

    // Security checking logic
    always @(*) begin
        aw_violation = 0;
        ar_violation = 0;
        aw_block = 0;
        ar_block = 0;
        
        // Master 0 security check
        if (m0_awvalid) begin
            // Check if non-secure access to secure slave
            if (!master_secure[0] && slave_secure[m0_aw_slave_sel] && 
                !slave_nonsec_allowed[m0_aw_slave_sel]) begin
                aw_violation[0] = 1'b1;
                aw_block[0] = 1'b1;
            end
            // Check AxPROT[1] for secure/non-secure transaction
            if (m0_awprot[1] && slave_secure[m0_aw_slave_sel] && 
                !slave_nonsec_allowed[m0_aw_slave_sel]) begin
                aw_violation[0] = 1'b1;
                aw_block[0] = 1'b1;
            end
        end
        if (m0_arvalid) begin
            // Check if non-secure access to secure slave
            if (!master_secure[0] && slave_secure[m0_ar_slave_sel] && 
                !slave_nonsec_allowed[m0_ar_slave_sel]) begin
                ar_violation[0] = 1'b1;
                ar_block[0] = 1'b1;
            end
            // Check AxPROT[1] for secure/non-secure transaction
            if (m0_arprot[1] && slave_secure[m0_ar_slave_sel] && 
                !slave_nonsec_allowed[m0_ar_slave_sel]) begin
                ar_violation[0] = 1'b1;
                ar_block[0] = 1'b1;
            end
        end
        // Master 1 security check
        if (m1_awvalid) begin
            // Check if non-secure access to secure slave
            if (!master_secure[1] && slave_secure[m1_aw_slave_sel] && 
                !slave_nonsec_allowed[m1_aw_slave_sel]) begin
                aw_violation[1] = 1'b1;
                aw_block[1] = 1'b1;
            end
            // Check AxPROT[1] for secure/non-secure transaction
            if (m1_awprot[1] && slave_secure[m1_aw_slave_sel] && 
                !slave_nonsec_allowed[m1_aw_slave_sel]) begin
                aw_violation[1] = 1'b1;
                aw_block[1] = 1'b1;
            end
        end
        if (m1_arvalid) begin
            // Check if non-secure access to secure slave
            if (!master_secure[1] && slave_secure[m1_ar_slave_sel] && 
                !slave_nonsec_allowed[m1_ar_slave_sel]) begin
                ar_violation[1] = 1'b1;
                ar_block[1] = 1'b1;
            end
            // Check AxPROT[1] for secure/non-secure transaction
            if (m1_arprot[1] && slave_secure[m1_ar_slave_sel] && 
                !slave_nonsec_allowed[m1_ar_slave_sel]) begin
                ar_violation[1] = 1'b1;
                ar_block[1] = 1'b1;
            end
        end
        // Master 2 security check
        if (m2_awvalid) begin
            // Check if non-secure access to secure slave
            if (!master_secure[2] && slave_secure[m2_aw_slave_sel] && 
                !slave_nonsec_allowed[m2_aw_slave_sel]) begin
                aw_violation[2] = 1'b1;
                aw_block[2] = 1'b1;
            end
            // Check AxPROT[1] for secure/non-secure transaction
            if (m2_awprot[1] && slave_secure[m2_aw_slave_sel] && 
                !slave_nonsec_allowed[m2_aw_slave_sel]) begin
                aw_violation[2] = 1'b1;
                aw_block[2] = 1'b1;
            end
        end
        if (m2_arvalid) begin
            // Check if non-secure access to secure slave
            if (!master_secure[2] && slave_secure[m2_ar_slave_sel] && 
                !slave_nonsec_allowed[m2_ar_slave_sel]) begin
                ar_violation[2] = 1'b1;
                ar_block[2] = 1'b1;
            end
            // Check AxPROT[1] for secure/non-secure transaction
            if (m2_arprot[1] && slave_secure[m2_ar_slave_sel] && 
                !slave_nonsec_allowed[m2_ar_slave_sel]) begin
                ar_violation[2] = 1'b1;
                ar_block[2] = 1'b1;
            end
        end
        // Master 3 security check
        if (m3_awvalid) begin
            // Check if non-secure access to secure slave
            if (!master_secure[3] && slave_secure[m3_aw_slave_sel] && 
                !slave_nonsec_allowed[m3_aw_slave_sel]) begin
                aw_violation[3] = 1'b1;
                aw_block[3] = 1'b1;
            end
            // Check AxPROT[1] for secure/non-secure transaction
            if (m3_awprot[1] && slave_secure[m3_aw_slave_sel] && 
                !slave_nonsec_allowed[m3_aw_slave_sel]) begin
                aw_violation[3] = 1'b1;
                aw_block[3] = 1'b1;
            end
        end
        if (m3_arvalid) begin
            // Check if non-secure access to secure slave
            if (!master_secure[3] && slave_secure[m3_ar_slave_sel] && 
                !slave_nonsec_allowed[m3_ar_slave_sel]) begin
                ar_violation[3] = 1'b1;
                ar_block[3] = 1'b1;
            end
            // Check AxPROT[1] for secure/non-secure transaction
            if (m3_arprot[1] && slave_secure[m3_ar_slave_sel] && 
                !slave_nonsec_allowed[m3_ar_slave_sel]) begin
                ar_violation[3] = 1'b1;
                ar_block[3] = 1'b1;
            end
        end
        
        // Global security alert
        security_alert = |aw_violation | |ar_violation;
    end

    // Violation logging
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            violation_count <= 32'd0;
            last_violation_addr <= 0;
            last_violation_is_write <= 0;
        end else begin
            if (|aw_violation) begin
                violation_count <= violation_count + 1;
                if (aw_violation[0]) begin
                    last_violation_addr <= m0_awaddr;
                    last_violation_is_write <= 1'b1;
                end
                if (aw_violation[1]) begin
                    last_violation_addr <= m1_awaddr;
                    last_violation_is_write <= 1'b1;
                end
                if (aw_violation[2]) begin
                    last_violation_addr <= m2_awaddr;
                    last_violation_is_write <= 1'b1;
                end
                if (aw_violation[3]) begin
                    last_violation_addr <= m3_awaddr;
                    last_violation_is_write <= 1'b1;
                end
            end
            if (|ar_violation) begin
                violation_count <= violation_count + 1;
                if (ar_violation[0]) begin
                    last_violation_addr <= m0_araddr;
                    last_violation_is_write <= 1'b0;
                end
                if (ar_violation[1]) begin
                    last_violation_addr <= m1_araddr;
                    last_violation_is_write <= 1'b0;
                end
                if (ar_violation[2]) begin
                    last_violation_addr <= m2_araddr;
                    last_violation_is_write <= 1'b0;
                end
                if (ar_violation[3]) begin
                    last_violation_addr <= m3_araddr;
                    last_violation_is_write <= 1'b0;
                end
            end
        end
    end

    // Secure memory region definitions
    localparam SECURE_REGION_START = 32'h8000_0000;
    localparam SECURE_REGION_END   = 32'h9000_0000;

    // Region-based security checks
    reg [NUM_MASTER-1:0] aw_in_secure_region;
    reg [NUM_MASTER-1:0] ar_in_secure_region;

    always @(*) begin
        aw_in_secure_region[0] = (m0_awaddr >= SECURE_REGION_START) && 
                                  (m0_awaddr < SECURE_REGION_END);
        ar_in_secure_region[0] = (m0_araddr >= SECURE_REGION_START) && 
                                  (m0_araddr < SECURE_REGION_END);
        aw_in_secure_region[1] = (m1_awaddr >= SECURE_REGION_START) && 
                                  (m1_awaddr < SECURE_REGION_END);
        ar_in_secure_region[1] = (m1_araddr >= SECURE_REGION_START) && 
                                  (m1_araddr < SECURE_REGION_END);
        aw_in_secure_region[2] = (m2_awaddr >= SECURE_REGION_START) && 
                                  (m2_awaddr < SECURE_REGION_END);
        ar_in_secure_region[2] = (m2_araddr >= SECURE_REGION_START) && 
                                  (m2_araddr < SECURE_REGION_END);
        aw_in_secure_region[3] = (m3_awaddr >= SECURE_REGION_START) && 
                                  (m3_awaddr < SECURE_REGION_END);
        ar_in_secure_region[3] = (m3_araddr >= SECURE_REGION_START) && 
                                  (m3_araddr < SECURE_REGION_END);
    end

    // Error response generation for blocked transactions
    // BRESP = 2'b10 (SLVERR), RRESP = 2'b10 (SLVERR)
    // Master 0 error response generation
    reg m0_aw_blocked;
    reg [WIDTH_ID-1:0] m0_awid_blocked;
    reg [7:0] m0_awlen_blocked;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            m0_aw_blocked <= 1'b0;
            m0_awid_blocked <= 0;
            m0_awlen_blocked <= 0;
            m0_bvalid_err <= 1'b0;
            m0_bid_err <= 0;
            m0_bresp_err <= 2'b00;
        end else begin
            // Capture blocked write transaction
            if (aw_block[0] && m0_awvalid) begin
                m0_aw_blocked <= 1'b1;
                m0_awid_blocked <= m0_awid;
                m0_awlen_blocked <= m0_awlen;
            end
            
            // Generate BRESP error
            if (m0_aw_blocked && !m0_bvalid_err) begin
                m0_bvalid_err <= 1'b1;
                m0_bid_err <= m0_awid_blocked;
                m0_bresp_err <= 2'b10; // SLVERR
            end else if (m0_bvalid_err && m0_bready) begin
                m0_bvalid_err <= 1'b0;
                m0_aw_blocked <= 1'b0;
            end
        end
    end

    reg m0_ar_blocked;
    reg [WIDTH_ID-1:0] m0_arid_blocked;
    reg [7:0] m0_arlen_blocked;
    reg [7:0] m0_rbeat_cnt;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            m0_ar_blocked <= 1'b0;
            m0_arid_blocked <= 0;
            m0_arlen_blocked <= 0;
            m0_rvalid_err <= 1'b0;
            m0_rid_err <= 0;
            m0_rdata_err <= 0;
            m0_rresp_err <= 2'b00;
            m0_rlast_err <= 1'b0;
            m0_rbeat_cnt <= 0;
        end else begin
            // Capture blocked read transaction
            if (ar_block[0] && m0_arvalid) begin
                m0_ar_blocked <= 1'b1;
                m0_arid_blocked <= m0_arid;
                m0_arlen_blocked <= m0_arlen;
                m0_rbeat_cnt <= 0;
            end
            
            // Generate RRESP error for all beats
            if (m0_ar_blocked && !m0_rvalid_err) begin
                m0_rvalid_err <= 1'b1;
                m0_rid_err <= m0_arid_blocked;
                m0_rdata_err <= {WIDTH_DA{1'b0}}; // Return zeros
                m0_rresp_err <= 2'b10; // SLVERR
                m0_rlast_err <= (m0_rbeat_cnt == m0_arlen_blocked);
            end else if (m0_rvalid_err && m0_rready) begin
                if (m0_rlast_err) begin
                    m0_rvalid_err <= 1'b0;
                    m0_ar_blocked <= 1'b0;
                    m0_rlast_err <= 1'b0;
                end else begin
                    m0_rbeat_cnt <= m0_rbeat_cnt + 1;
                    m0_rlast_err <= (m0_rbeat_cnt + 1 == m0_arlen_blocked);
                end
            end
        end
    end

    // Master 1 error response generation
    reg m1_aw_blocked;
    reg [WIDTH_ID-1:0] m1_awid_blocked;
    reg [7:0] m1_awlen_blocked;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            m1_aw_blocked <= 1'b0;
            m1_awid_blocked <= 0;
            m1_awlen_blocked <= 0;
            m1_bvalid_err <= 1'b0;
            m1_bid_err <= 0;
            m1_bresp_err <= 2'b00;
        end else begin
            // Capture blocked write transaction
            if (aw_block[1] && m1_awvalid) begin
                m1_aw_blocked <= 1'b1;
                m1_awid_blocked <= m1_awid;
                m1_awlen_blocked <= m1_awlen;
            end
            
            // Generate BRESP error
            if (m1_aw_blocked && !m1_bvalid_err) begin
                m1_bvalid_err <= 1'b1;
                m1_bid_err <= m1_awid_blocked;
                m1_bresp_err <= 2'b10; // SLVERR
            end else if (m1_bvalid_err && m1_bready) begin
                m1_bvalid_err <= 1'b0;
                m1_aw_blocked <= 1'b0;
            end
        end
    end

    reg m1_ar_blocked;
    reg [WIDTH_ID-1:0] m1_arid_blocked;
    reg [7:0] m1_arlen_blocked;
    reg [7:0] m1_rbeat_cnt;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            m1_ar_blocked <= 1'b0;
            m1_arid_blocked <= 0;
            m1_arlen_blocked <= 0;
            m1_rvalid_err <= 1'b0;
            m1_rid_err <= 0;
            m1_rdata_err <= 0;
            m1_rresp_err <= 2'b00;
            m1_rlast_err <= 1'b0;
            m1_rbeat_cnt <= 0;
        end else begin
            // Capture blocked read transaction
            if (ar_block[1] && m1_arvalid) begin
                m1_ar_blocked <= 1'b1;
                m1_arid_blocked <= m1_arid;
                m1_arlen_blocked <= m1_arlen;
                m1_rbeat_cnt <= 0;
            end
            
            // Generate RRESP error for all beats
            if (m1_ar_blocked && !m1_rvalid_err) begin
                m1_rvalid_err <= 1'b1;
                m1_rid_err <= m1_arid_blocked;
                m1_rdata_err <= {WIDTH_DA{1'b0}}; // Return zeros
                m1_rresp_err <= 2'b10; // SLVERR
                m1_rlast_err <= (m1_rbeat_cnt == m1_arlen_blocked);
            end else if (m1_rvalid_err && m1_rready) begin
                if (m1_rlast_err) begin
                    m1_rvalid_err <= 1'b0;
                    m1_ar_blocked <= 1'b0;
                    m1_rlast_err <= 1'b0;
                end else begin
                    m1_rbeat_cnt <= m1_rbeat_cnt + 1;
                    m1_rlast_err <= (m1_rbeat_cnt + 1 == m1_arlen_blocked);
                end
            end
        end
    end

    // Master 2 error response generation
    reg m2_aw_blocked;
    reg [WIDTH_ID-1:0] m2_awid_blocked;
    reg [7:0] m2_awlen_blocked;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            m2_aw_blocked <= 1'b0;
            m2_awid_blocked <= 0;
            m2_awlen_blocked <= 0;
            m2_bvalid_err <= 1'b0;
            m2_bid_err <= 0;
            m2_bresp_err <= 2'b00;
        end else begin
            // Capture blocked write transaction
            if (aw_block[2] && m2_awvalid) begin
                m2_aw_blocked <= 1'b1;
                m2_awid_blocked <= m2_awid;
                m2_awlen_blocked <= m2_awlen;
            end
            
            // Generate BRESP error
            if (m2_aw_blocked && !m2_bvalid_err) begin
                m2_bvalid_err <= 1'b1;
                m2_bid_err <= m2_awid_blocked;
                m2_bresp_err <= 2'b10; // SLVERR
            end else if (m2_bvalid_err && m2_bready) begin
                m2_bvalid_err <= 1'b0;
                m2_aw_blocked <= 1'b0;
            end
        end
    end

    reg m2_ar_blocked;
    reg [WIDTH_ID-1:0] m2_arid_blocked;
    reg [7:0] m2_arlen_blocked;
    reg [7:0] m2_rbeat_cnt;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            m2_ar_blocked <= 1'b0;
            m2_arid_blocked <= 0;
            m2_arlen_blocked <= 0;
            m2_rvalid_err <= 1'b0;
            m2_rid_err <= 0;
            m2_rdata_err <= 0;
            m2_rresp_err <= 2'b00;
            m2_rlast_err <= 1'b0;
            m2_rbeat_cnt <= 0;
        end else begin
            // Capture blocked read transaction
            if (ar_block[2] && m2_arvalid) begin
                m2_ar_blocked <= 1'b1;
                m2_arid_blocked <= m2_arid;
                m2_arlen_blocked <= m2_arlen;
                m2_rbeat_cnt <= 0;
            end
            
            // Generate RRESP error for all beats
            if (m2_ar_blocked && !m2_rvalid_err) begin
                m2_rvalid_err <= 1'b1;
                m2_rid_err <= m2_arid_blocked;
                m2_rdata_err <= {WIDTH_DA{1'b0}}; // Return zeros
                m2_rresp_err <= 2'b10; // SLVERR
                m2_rlast_err <= (m2_rbeat_cnt == m2_arlen_blocked);
            end else if (m2_rvalid_err && m2_rready) begin
                if (m2_rlast_err) begin
                    m2_rvalid_err <= 1'b0;
                    m2_ar_blocked <= 1'b0;
                    m2_rlast_err <= 1'b0;
                end else begin
                    m2_rbeat_cnt <= m2_rbeat_cnt + 1;
                    m2_rlast_err <= (m2_rbeat_cnt + 1 == m2_arlen_blocked);
                end
            end
        end
    end

    // Master 3 error response generation
    reg m3_aw_blocked;
    reg [WIDTH_ID-1:0] m3_awid_blocked;
    reg [7:0] m3_awlen_blocked;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            m3_aw_blocked <= 1'b0;
            m3_awid_blocked <= 0;
            m3_awlen_blocked <= 0;
            m3_bvalid_err <= 1'b0;
            m3_bid_err <= 0;
            m3_bresp_err <= 2'b00;
        end else begin
            // Capture blocked write transaction
            if (aw_block[3] && m3_awvalid) begin
                m3_aw_blocked <= 1'b1;
                m3_awid_blocked <= m3_awid;
                m3_awlen_blocked <= m3_awlen;
            end
            
            // Generate BRESP error
            if (m3_aw_blocked && !m3_bvalid_err) begin
                m3_bvalid_err <= 1'b1;
                m3_bid_err <= m3_awid_blocked;
                m3_bresp_err <= 2'b10; // SLVERR
            end else if (m3_bvalid_err && m3_bready) begin
                m3_bvalid_err <= 1'b0;
                m3_aw_blocked <= 1'b0;
            end
        end
    end

    reg m3_ar_blocked;
    reg [WIDTH_ID-1:0] m3_arid_blocked;
    reg [7:0] m3_arlen_blocked;
    reg [7:0] m3_rbeat_cnt;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            m3_ar_blocked <= 1'b0;
            m3_arid_blocked <= 0;
            m3_arlen_blocked <= 0;
            m3_rvalid_err <= 1'b0;
            m3_rid_err <= 0;
            m3_rdata_err <= 0;
            m3_rresp_err <= 2'b00;
            m3_rlast_err <= 1'b0;
            m3_rbeat_cnt <= 0;
        end else begin
            // Capture blocked read transaction
            if (ar_block[3] && m3_arvalid) begin
                m3_ar_blocked <= 1'b1;
                m3_arid_blocked <= m3_arid;
                m3_arlen_blocked <= m3_arlen;
                m3_rbeat_cnt <= 0;
            end
            
            // Generate RRESP error for all beats
            if (m3_ar_blocked && !m3_rvalid_err) begin
                m3_rvalid_err <= 1'b1;
                m3_rid_err <= m3_arid_blocked;
                m3_rdata_err <= {WIDTH_DA{1'b0}}; // Return zeros
                m3_rresp_err <= 2'b10; // SLVERR
                m3_rlast_err <= (m3_rbeat_cnt == m3_arlen_blocked);
            end else if (m3_rvalid_err && m3_rready) begin
                if (m3_rlast_err) begin
                    m3_rvalid_err <= 1'b0;
                    m3_ar_blocked <= 1'b0;
                    m3_rlast_err <= 1'b0;
                end else begin
                    m3_rbeat_cnt <= m3_rbeat_cnt + 1;
                    m3_rlast_err <= (m3_rbeat_cnt + 1 == m3_arlen_blocked);
                end
            end
        end
    end

endmodule

//---------------------------------------------------------------------------
// ACE-Lite Coherency Controller
// Manages master coherency states and transaction ordering
//---------------------------------------------------------------------------
module ace_lite_coherency_controller
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_ID   = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , COHERENCY_TABLE_DEPTH = 64)
(
      input  wire                       clk
    , input  wire                       rst_n
    // Master 0 coherency interface
    , input  wire [WIDTH_ID-1:0]       m0_awid
    , input  wire [WIDTH_AD-1:0]       m0_awaddr
    , input  wire [1:0]                m0_awdomain
    , input  wire [2:0]                m0_awsnoop
    , input  wire                      m0_awvalid
    , input  wire [WIDTH_ID-1:0]       m0_arid
    , input  wire [WIDTH_AD-1:0]       m0_araddr
    , input  wire [1:0]                m0_ardomain
    , input  wire [3:0]                m0_arsnoop
    , input  wire                      m0_arvalid
    , input  wire                      m0_bready
    , input  wire                      m0_rready
    // Master 1 coherency interface
    , input  wire [WIDTH_ID-1:0]       m1_awid
    , input  wire [WIDTH_AD-1:0]       m1_awaddr
    , input  wire [1:0]                m1_awdomain
    , input  wire [2:0]                m1_awsnoop
    , input  wire                      m1_awvalid
    , input  wire [WIDTH_ID-1:0]       m1_arid
    , input  wire [WIDTH_AD-1:0]       m1_araddr
    , input  wire [1:0]                m1_ardomain
    , input  wire [3:0]                m1_arsnoop
    , input  wire                      m1_arvalid
    , input  wire                      m1_bready
    , input  wire                      m1_rready
    // Master 2 coherency interface
    , input  wire [WIDTH_ID-1:0]       m2_awid
    , input  wire [WIDTH_AD-1:0]       m2_awaddr
    , input  wire [1:0]                m2_awdomain
    , input  wire [2:0]                m2_awsnoop
    , input  wire                      m2_awvalid
    , input  wire [WIDTH_ID-1:0]       m2_arid
    , input  wire [WIDTH_AD-1:0]       m2_araddr
    , input  wire [1:0]                m2_ardomain
    , input  wire [3:0]                m2_arsnoop
    , input  wire                      m2_arvalid
    , input  wire                      m2_bready
    , input  wire                      m2_rready
    // Master 3 coherency interface
    , input  wire [WIDTH_ID-1:0]       m3_awid
    , input  wire [WIDTH_AD-1:0]       m3_awaddr
    , input  wire [1:0]                m3_awdomain
    , input  wire [2:0]                m3_awsnoop
    , input  wire                      m3_awvalid
    , input  wire [WIDTH_ID-1:0]       m3_arid
    , input  wire [WIDTH_AD-1:0]       m3_araddr
    , input  wire [1:0]                m3_ardomain
    , input  wire [3:0]                m3_arsnoop
    , input  wire                      m3_arvalid
    , input  wire                      m3_bready
    , input  wire                      m3_rready
    // Coherency control outputs
    , output reg  [NUM_MASTER-1:0]       coherency_block
    , output reg  [NUM_MASTER-1:0]       coherency_violation
    , output reg                         coherency_active
    , output wire [NUM_MASTER-1:0]       transaction_valid
    , output wire [7:0]                  coherency_state [NUM_MASTER-1:0]
);

    // ACE-Lite coherency parameters
    localparam WIDTH_DOMAIN = 2;
    localparam WIDTH_SNOOP_AW = 3;
    localparam WIDTH_SNOOP_AR = 4;

    // Domain encodings (shareability)
    localparam [1:0] DOMAIN_NON_SHAREABLE = 2'b00;
    localparam [1:0] DOMAIN_INNER_SHAREABLE = 2'b01;
    localparam [1:0] DOMAIN_OUTER_SHAREABLE = 2'b10;
    localparam [1:0] DOMAIN_SYSTEM = 2'b11;

    // Write snoop encodings (ACE-Lite)
    localparam [2:0] AWSNOOP_WRITE_NO_SNOOP = 3'b000;
    localparam [2:0] AWSNOOP_WRITE_LINE_UNIQUE = 3'b001;
    localparam [2:0] AWSNOOP_WRITE_CLEAN = 3'b010;
    localparam [2:0] AWSNOOP_WRITE_BACK = 3'b011;
    localparam [2:0] AWSNOOP_EVICT = 3'b100;

    // Read snoop encodings (ACE-Lite)
    localparam [3:0] ARSNOOP_READ_NO_SNOOP = 4'b0000;
    localparam [3:0] ARSNOOP_READ_ONCE = 4'b0001;
    localparam [3:0] ARSNOOP_READ_SHARED = 4'b0001;
    localparam [3:0] ARSNOOP_READ_CLEAN = 4'b0010;
    localparam [3:0] ARSNOOP_READ_UNIQUE = 4'b0111;
    localparam [3:0] ARSNOOP_CLEAN_UNIQUE = 4'b1011;

    // Coherency state encodings per master
    localparam [7:0] COHERENT_IDLE = 8'h00;
    localparam [7:0] COHERENT_WRITE_PENDING = 8'h01;
    localparam [7:0] COHERENT_READ_PENDING = 8'h02;
    localparam [7:0] COHERENT_WRITE_ACTIVE = 8'h04;
    localparam [7:0] COHERENT_READ_ACTIVE = 8'h08;
    localparam [7:0] COHERENT_CACHE_MAINT = 8'h10;
    localparam [7:0] COHERENT_BARRIER_WAIT = 8'h20;
    localparam [7:0] COHERENT_VIOLATION = 8'hFF;

    // Coherency tracking table
    reg [WIDTH_AD-1:0] coherency_addr_table [0:COHERENCY_TABLE_DEPTH-1];
    reg [NUM_MASTER-1:0] coherency_master_table [0:COHERENCY_TABLE_DEPTH-1];
    reg [COHERENCY_TABLE_DEPTH-1:0] coherency_table_valid;
    reg [$clog2(COHERENCY_TABLE_DEPTH)-1:0] coherency_table_ptr;

    // Master coherency state tracking
    reg [7:0] master_coherency_state [NUM_MASTER-1:0];
    reg [WIDTH_AD-1:0] master_pending_addr [NUM_MASTER-1:0];
    reg [NUM_MASTER-1:0] master_coherent_transaction;

    // Master coherency state machines
    // Master 0 coherency state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            master_coherency_state[0] <= COHERENT_IDLE;
            master_pending_addr[0] <= 32'h0;
            master_coherent_transaction[0] <= 1'b0;
        end else begin
            case (master_coherency_state[0])
                COHERENT_IDLE: begin
                    if (m0_awvalid && (m0_awdomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[0] <= COHERENT_WRITE_PENDING;
                        master_pending_addr[0] <= m0_awaddr;
                        master_coherent_transaction[0] <= 1'b1;
                    end else if (m0_arvalid && (m0_ardomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[0] <= COHERENT_READ_PENDING;
                        master_pending_addr[0] <= m0_araddr;
                        master_coherent_transaction[0] <= 1'b1;
                    end
                end
                COHERENT_WRITE_PENDING: begin
                    // Check for coherency conflicts
                    if (coherency_conflict_detected(0, master_pending_addr[0])) begin
                        master_coherency_state[0] <= COHERENT_VIOLATION;
                    end else begin
                        master_coherency_state[0] <= COHERENT_WRITE_ACTIVE;
                    end
                end
                COHERENT_READ_PENDING: begin
                    // Check for coherency conflicts
                    if (coherency_conflict_detected(0, master_pending_addr[0])) begin
                        master_coherency_state[0] <= COHERENT_VIOLATION;
                    end else begin
                        master_coherency_state[0] <= COHERENT_READ_ACTIVE;
                    end
                end
                COHERENT_WRITE_ACTIVE: begin
                    if (m0_bready) begin
                        master_coherency_state[0] <= COHERENT_IDLE;
                        master_coherent_transaction[0] <= 1'b0;
                    end
                end
                COHERENT_READ_ACTIVE: begin
                    if (m0_rready) begin
                        master_coherency_state[0] <= COHERENT_IDLE;
                        master_coherent_transaction[0] <= 1'b0;
                    end
                end
                COHERENT_VIOLATION: begin
                    // Hold violation until reset
                    master_coherency_state[0] <= COHERENT_VIOLATION;
                end
                default: master_coherency_state[0] <= COHERENT_IDLE;
            endcase
        end
    end

    // Master 1 coherency state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            master_coherency_state[1] <= COHERENT_IDLE;
            master_pending_addr[1] <= 32'h0;
            master_coherent_transaction[1] <= 1'b0;
        end else begin
            case (master_coherency_state[1])
                COHERENT_IDLE: begin
                    if (m1_awvalid && (m1_awdomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[1] <= COHERENT_WRITE_PENDING;
                        master_pending_addr[1] <= m1_awaddr;
                        master_coherent_transaction[1] <= 1'b1;
                    end else if (m1_arvalid && (m1_ardomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[1] <= COHERENT_READ_PENDING;
                        master_pending_addr[1] <= m1_araddr;
                        master_coherent_transaction[1] <= 1'b1;
                    end
                end
                COHERENT_WRITE_PENDING: begin
                    // Check for coherency conflicts
                    if (coherency_conflict_detected(1, master_pending_addr[1])) begin
                        master_coherency_state[1] <= COHERENT_VIOLATION;
                    end else begin
                        master_coherency_state[1] <= COHERENT_WRITE_ACTIVE;
                    end
                end
                COHERENT_READ_PENDING: begin
                    // Check for coherency conflicts
                    if (coherency_conflict_detected(1, master_pending_addr[1])) begin
                        master_coherency_state[1] <= COHERENT_VIOLATION;
                    end else begin
                        master_coherency_state[1] <= COHERENT_READ_ACTIVE;
                    end
                end
                COHERENT_WRITE_ACTIVE: begin
                    if (m1_bready) begin
                        master_coherency_state[1] <= COHERENT_IDLE;
                        master_coherent_transaction[1] <= 1'b0;
                    end
                end
                COHERENT_READ_ACTIVE: begin
                    if (m1_rready) begin
                        master_coherency_state[1] <= COHERENT_IDLE;
                        master_coherent_transaction[1] <= 1'b0;
                    end
                end
                COHERENT_VIOLATION: begin
                    // Hold violation until reset
                    master_coherency_state[1] <= COHERENT_VIOLATION;
                end
                default: master_coherency_state[1] <= COHERENT_IDLE;
            endcase
        end
    end

    // Master 2 coherency state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            master_coherency_state[2] <= COHERENT_IDLE;
            master_pending_addr[2] <= 32'h0;
            master_coherent_transaction[2] <= 1'b0;
        end else begin
            case (master_coherency_state[2])
                COHERENT_IDLE: begin
                    if (m2_awvalid && (m2_awdomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[2] <= COHERENT_WRITE_PENDING;
                        master_pending_addr[2] <= m2_awaddr;
                        master_coherent_transaction[2] <= 1'b1;
                    end else if (m2_arvalid && (m2_ardomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[2] <= COHERENT_READ_PENDING;
                        master_pending_addr[2] <= m2_araddr;
                        master_coherent_transaction[2] <= 1'b1;
                    end
                end
                COHERENT_WRITE_PENDING: begin
                    // Check for coherency conflicts
                    if (coherency_conflict_detected(2, master_pending_addr[2])) begin
                        master_coherency_state[2] <= COHERENT_VIOLATION;
                    end else begin
                        master_coherency_state[2] <= COHERENT_WRITE_ACTIVE;
                    end
                end
                COHERENT_READ_PENDING: begin
                    // Check for coherency conflicts
                    if (coherency_conflict_detected(2, master_pending_addr[2])) begin
                        master_coherency_state[2] <= COHERENT_VIOLATION;
                    end else begin
                        master_coherency_state[2] <= COHERENT_READ_ACTIVE;
                    end
                end
                COHERENT_WRITE_ACTIVE: begin
                    if (m2_bready) begin
                        master_coherency_state[2] <= COHERENT_IDLE;
                        master_coherent_transaction[2] <= 1'b0;
                    end
                end
                COHERENT_READ_ACTIVE: begin
                    if (m2_rready) begin
                        master_coherency_state[2] <= COHERENT_IDLE;
                        master_coherent_transaction[2] <= 1'b0;
                    end
                end
                COHERENT_VIOLATION: begin
                    // Hold violation until reset
                    master_coherency_state[2] <= COHERENT_VIOLATION;
                end
                default: master_coherency_state[2] <= COHERENT_IDLE;
            endcase
        end
    end

    // Master 3 coherency state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            master_coherency_state[3] <= COHERENT_IDLE;
            master_pending_addr[3] <= 32'h0;
            master_coherent_transaction[3] <= 1'b0;
        end else begin
            case (master_coherency_state[3])
                COHERENT_IDLE: begin
                    if (m3_awvalid && (m3_awdomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[3] <= COHERENT_WRITE_PENDING;
                        master_pending_addr[3] <= m3_awaddr;
                        master_coherent_transaction[3] <= 1'b1;
                    end else if (m3_arvalid && (m3_ardomain != DOMAIN_NON_SHAREABLE)) begin
                        master_coherency_state[3] <= COHERENT_READ_PENDING;
                        master_pending_addr[3] <= m3_araddr;
                        master_coherent_transaction[3] <= 1'b1;
                    end
                end
                COHERENT_WRITE_PENDING: begin
                    // Check for coherency conflicts
                    if (coherency_conflict_detected(3, master_pending_addr[3])) begin
                        master_coherency_state[3] <= COHERENT_VIOLATION;
                    end else begin
                        master_coherency_state[3] <= COHERENT_WRITE_ACTIVE;
                    end
                end
                COHERENT_READ_PENDING: begin
                    // Check for coherency conflicts
                    if (coherency_conflict_detected(3, master_pending_addr[3])) begin
                        master_coherency_state[3] <= COHERENT_VIOLATION;
                    end else begin
                        master_coherency_state[3] <= COHERENT_READ_ACTIVE;
                    end
                end
                COHERENT_WRITE_ACTIVE: begin
                    if (m3_bready) begin
                        master_coherency_state[3] <= COHERENT_IDLE;
                        master_coherent_transaction[3] <= 1'b0;
                    end
                end
                COHERENT_READ_ACTIVE: begin
                    if (m3_rready) begin
                        master_coherency_state[3] <= COHERENT_IDLE;
                        master_coherent_transaction[3] <= 1'b0;
                    end
                end
                COHERENT_VIOLATION: begin
                    // Hold violation until reset
                    master_coherency_state[3] <= COHERENT_VIOLATION;
                end
                default: master_coherency_state[3] <= COHERENT_IDLE;
            endcase
        end
    end

    // Coherency conflict detection function
    function coherency_conflict_detected;
        input [7:0] master_id;
        input [WIDTH_AD-1:0] addr;
        integer j;
        begin
            coherency_conflict_detected = 1'b0;
            // Check coherency table for address conflicts
            for (j = 0; j < COHERENCY_TABLE_DEPTH; j = j + 1) begin
                if (coherency_table_valid[j] && 
                    (coherency_addr_table[j][WIDTH_AD-1:6] == addr[WIDTH_AD-1:6]) &&
                    (coherency_master_table[j][master_id] == 1'b0)) begin
                    coherency_conflict_detected = 1'b1;
                end
            end
        end
    endfunction

    // Output assignments
    assign coherency_state = master_coherency_state;
    assign transaction_valid = master_coherent_transaction;
    // Coherency violation detection
    always @(*) begin
        coherency_violation[0] = (master_coherency_state[0] == COHERENT_VIOLATION);
        coherency_block[0] = (master_coherency_state[0] == COHERENT_WRITE_PENDING) ||
                               (master_coherency_state[0] == COHERENT_READ_PENDING);
        coherency_violation[1] = (master_coherency_state[1] == COHERENT_VIOLATION);
        coherency_block[1] = (master_coherency_state[1] == COHERENT_WRITE_PENDING) ||
                               (master_coherency_state[1] == COHERENT_READ_PENDING);
        coherency_violation[2] = (master_coherency_state[2] == COHERENT_VIOLATION);
        coherency_block[2] = (master_coherency_state[2] == COHERENT_WRITE_PENDING) ||
                               (master_coherency_state[2] == COHERENT_READ_PENDING);
        coherency_violation[3] = (master_coherency_state[3] == COHERENT_VIOLATION);
        coherency_block[3] = (master_coherency_state[3] == COHERENT_WRITE_PENDING) ||
                               (master_coherency_state[3] == COHERENT_READ_PENDING);
        coherency_active = |master_coherent_transaction;
    end


    // Enhanced Snoop Request Distribution Logic
    // Manages coherency requests to all affected masters
    reg [NUM_MASTER-1:0] snoop_request_pending;
    reg [NUM_MASTER-1:0] snoop_response_received;
    reg [WIDTH_AD-1:0] current_snoop_addr;
    reg [2:0] current_snoop_type;
    reg snoop_broadcast_active;

    // Snoop Distribution State Machine
    localparam [2:0] SNOOP_IDLE        = 3'b000;
    localparam [2:0] SNOOP_REQUEST     = 3'b001;
    localparam [2:0] SNOOP_WAIT_RESP   = 3'b010;
    localparam [2:0] SNOOP_AGGREGATE   = 3'b011;
    localparam [2:0] SNOOP_COMPLETE    = 3'b100;
    localparam [2:0] SNOOP_ERROR       = 3'b101;

    reg [2:0] snoop_state;
    reg [15:0] snoop_timeout_counter;
    reg snoop_timeout_error;

    // Snoop Distribution and Response Aggregation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            snoop_state <= SNOOP_IDLE;
            snoop_request_pending <= {NUM_MASTER{1'b0}};
            snoop_response_received <= {NUM_MASTER{1'b0}};
            current_snoop_addr <= {WIDTH_AD{1'b0}};
            current_snoop_type <= 3'b000;
            snoop_broadcast_active <= 1'b0;
            snoop_timeout_counter <= 16'h0000;
            snoop_timeout_error <= 1'b0;
        end else begin
            case (snoop_state)
                SNOOP_IDLE: begin
                    snoop_timeout_counter <= 16'h0000;
                    snoop_timeout_error <= 1'b0;
                    
                    // Check for coherent transactions requiring snooping
                    if (m0_awvalid && (m0_awdomain != DOMAIN_NON_SHAREABLE) &&
                        (m0_awsnoop != AWSNOOP_WRITE_NO_SNOOP)) begin
                        // Coherent write requires snoop broadcast
                        snoop_state <= SNOOP_REQUEST;
                        current_snoop_addr <= m0_awaddr;
                        current_snoop_type <= m0_awsnoop;
                        snoop_broadcast_active <= 1'b1;
                        // Request snoops to all other masters
                        snoop_request_pending <= {NUM_MASTER{1'b1}} & ~(1 << 0);
                    end else if (m0_arvalid && (m0_ardomain != DOMAIN_NON_SHAREABLE) &&
                                (m0_arsnoop != ARSNOOP_READ_NO_SNOOP)) begin
                        // Coherent read may require snoop broadcast
                        snoop_state <= SNOOP_REQUEST;
                        current_snoop_addr <= m0_araddr;
                        current_snoop_type <= {1'b0, m0_arsnoop[1:0]};
                        snoop_broadcast_active <= 1'b1;
                        // Request snoops to relevant masters
                        snoop_request_pending <= {NUM_MASTER{1'b1}} & ~(1 << 0);
                    end else                     if (m1_awvalid && (m1_awdomain != DOMAIN_NON_SHAREABLE) &&
                        (m1_awsnoop != AWSNOOP_WRITE_NO_SNOOP)) begin
                        // Coherent write requires snoop broadcast
                        snoop_state <= SNOOP_REQUEST;
                        current_snoop_addr <= m1_awaddr;
                        current_snoop_type <= m1_awsnoop;
                        snoop_broadcast_active <= 1'b1;
                        // Request snoops to all other masters
                        snoop_request_pending <= {NUM_MASTER{1'b1}} & ~(1 << 1);
                    end else if (m1_arvalid && (m1_ardomain != DOMAIN_NON_SHAREABLE) &&
                                (m1_arsnoop != ARSNOOP_READ_NO_SNOOP)) begin
                        // Coherent read may require snoop broadcast
                        snoop_state <= SNOOP_REQUEST;
                        current_snoop_addr <= m1_araddr;
                        current_snoop_type <= {1'b0, m1_arsnoop[1:0]};
                        snoop_broadcast_active <= 1'b1;
                        // Request snoops to relevant masters
                        snoop_request_pending <= {NUM_MASTER{1'b1}} & ~(1 << 1);
                    end else                     if (m2_awvalid && (m2_awdomain != DOMAIN_NON_SHAREABLE) &&
                        (m2_awsnoop != AWSNOOP_WRITE_NO_SNOOP)) begin
                        // Coherent write requires snoop broadcast
                        snoop_state <= SNOOP_REQUEST;
                        current_snoop_addr <= m2_awaddr;
                        current_snoop_type <= m2_awsnoop;
                        snoop_broadcast_active <= 1'b1;
                        // Request snoops to all other masters
                        snoop_request_pending <= {NUM_MASTER{1'b1}} & ~(1 << 2);
                    end else if (m2_arvalid && (m2_ardomain != DOMAIN_NON_SHAREABLE) &&
                                (m2_arsnoop != ARSNOOP_READ_NO_SNOOP)) begin
                        // Coherent read may require snoop broadcast
                        snoop_state <= SNOOP_REQUEST;
                        current_snoop_addr <= m2_araddr;
                        current_snoop_type <= {1'b0, m2_arsnoop[1:0]};
                        snoop_broadcast_active <= 1'b1;
                        // Request snoops to relevant masters
                        snoop_request_pending <= {NUM_MASTER{1'b1}} & ~(1 << 2);
                    end else                     if (m3_awvalid && (m3_awdomain != DOMAIN_NON_SHAREABLE) &&
                        (m3_awsnoop != AWSNOOP_WRITE_NO_SNOOP)) begin
                        // Coherent write requires snoop broadcast
                        snoop_state <= SNOOP_REQUEST;
                        current_snoop_addr <= m3_awaddr;
                        current_snoop_type <= m3_awsnoop;
                        snoop_broadcast_active <= 1'b1;
                        // Request snoops to all other masters
                        snoop_request_pending <= {NUM_MASTER{1'b1}} & ~(1 << 3);
                    end else if (m3_arvalid && (m3_ardomain != DOMAIN_NON_SHAREABLE) &&
                                (m3_arsnoop != ARSNOOP_READ_NO_SNOOP)) begin
                        // Coherent read may require snoop broadcast
                        snoop_state <= SNOOP_REQUEST;
                        current_snoop_addr <= m3_araddr;
                        current_snoop_type <= {1'b0, m3_arsnoop[1:0]};
                        snoop_broadcast_active <= 1'b1;
                        // Request snoops to relevant masters
                        snoop_request_pending <= {NUM_MASTER{1'b1}} & ~(1 << 3);
                    end else begin
                        // No coherent transaction
                        snoop_broadcast_active <= 1'b0;
                    end
                end
                
                SNOOP_REQUEST: begin
                    // Initiate snoop requests to selected masters
                    snoop_state <= SNOOP_WAIT_RESP;
                    snoop_response_received <= {NUM_MASTER{1'b0}};
                    snoop_timeout_counter <= 16'h0001;
                end
                
                SNOOP_WAIT_RESP: begin
                    // Wait for all snoop responses with timeout
                    if ((snoop_response_received & snoop_request_pending) == snoop_request_pending) begin
                        // All responses received
                        snoop_state <= SNOOP_AGGREGATE;
                    end else if (snoop_timeout_counter > 16'hFF00) begin
                        // Timeout occurred
                        snoop_state <= SNOOP_ERROR;
                        snoop_timeout_error <= 1'b1;
                    end else begin
                        snoop_timeout_counter <= snoop_timeout_counter + 1;
                        
                        // Update response received flags (placeholder logic)
                        // In real implementation, this would be connected to actual snoop responses
                        if (snoop_request_pending[0] && /* snoop_response_valid[0] */ 1'b0) begin
                            snoop_response_received[0] <= 1'b1;
                        end
                        if (snoop_request_pending[1] && /* snoop_response_valid[1] */ 1'b0) begin
                            snoop_response_received[1] <= 1'b1;
                        end
                        if (snoop_request_pending[2] && /* snoop_response_valid[2] */ 1'b0) begin
                            snoop_response_received[2] <= 1'b1;
                        end
                        if (snoop_request_pending[3] && /* snoop_response_valid[3] */ 1'b0) begin
                            snoop_response_received[3] <= 1'b1;
                        end
                    end
                end
                
                SNOOP_AGGREGATE: begin
                    // Aggregate all snoop responses
                    // Determine final coherency action based on responses
                    snoop_state <= SNOOP_COMPLETE;
                end
                
                SNOOP_COMPLETE: begin
                    // Complete snoop operation
                    snoop_state <= SNOOP_IDLE;
                    snoop_broadcast_active <= 1'b0;
                    snoop_request_pending <= {NUM_MASTER{1'b0}};
                    snoop_response_received <= {NUM_MASTER{1'b0}};
                end
                
                SNOOP_ERROR: begin
                    // Handle snoop timeout error
                    snoop_state <= SNOOP_IDLE;
                    snoop_broadcast_active <= 1'b0;
                    snoop_request_pending <= {NUM_MASTER{1'b0}};
                    snoop_response_received <= {NUM_MASTER{1'b0}};
                end
                
                default: begin
                    snoop_state <= SNOOP_IDLE;
                end
            endcase
        end
    end

    // Deadlock Prevention Logic
    // Prevents circular waiting and ensures forward progress
    reg [NUM_MASTER-1:0] deadlock_detected;
    reg [NUM_MASTER-1:0] priority_boost;
    reg [15:0] stall_counter [NUM_MASTER-1:0];
    
    // Deadlock detection and prevention
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            deadlock_detected <= {NUM_MASTER{1'b0}};
            priority_boost <= {NUM_MASTER{1'b0}};
            stall_counter[0] <= 16'h0000;
            stall_counter[1] <= 16'h0000;
            stall_counter[2] <= 16'h0000;
            stall_counter[3] <= 16'h0000;
        end else begin
            // Master 0 deadlock detection
            if (master_coherency_state[0] == COHERENT_WRITE_PENDING ||
                master_coherency_state[0] == COHERENT_READ_PENDING) begin
                // Master is stalled, increment counter
                if (stall_counter[0] < 16'hFFFF) begin
                    stall_counter[0] <= stall_counter[0] + 1;
                end
                
                // Detect potential deadlock
                if (stall_counter[0] > 16'hF000) begin
                    deadlock_detected[0] <= 1'b1;
                    priority_boost[0] <= 1'b1;
                end
            end else begin
                // Master is not stalled, reset counters
                stall_counter[0] <= 16'h0000;
                deadlock_detected[0] <= 1'b0;
                priority_boost[0] <= 1'b0;
            end
            
            // Master 1 deadlock detection
            if (master_coherency_state[1] == COHERENT_WRITE_PENDING ||
                master_coherency_state[1] == COHERENT_READ_PENDING) begin
                // Master is stalled, increment counter
                if (stall_counter[1] < 16'hFFFF) begin
                    stall_counter[1] <= stall_counter[1] + 1;
                end
                
                // Detect potential deadlock
                if (stall_counter[1] > 16'hF000) begin
                    deadlock_detected[1] <= 1'b1;
                    priority_boost[1] <= 1'b1;
                end
            end else begin
                // Master is not stalled, reset counters
                stall_counter[1] <= 16'h0000;
                deadlock_detected[1] <= 1'b0;
                priority_boost[1] <= 1'b0;
            end
            
            // Master 2 deadlock detection
            if (master_coherency_state[2] == COHERENT_WRITE_PENDING ||
                master_coherency_state[2] == COHERENT_READ_PENDING) begin
                // Master is stalled, increment counter
                if (stall_counter[2] < 16'hFFFF) begin
                    stall_counter[2] <= stall_counter[2] + 1;
                end
                
                // Detect potential deadlock
                if (stall_counter[2] > 16'hF000) begin
                    deadlock_detected[2] <= 1'b1;
                    priority_boost[2] <= 1'b1;
                end
            end else begin
                // Master is not stalled, reset counters
                stall_counter[2] <= 16'h0000;
                deadlock_detected[2] <= 1'b0;
                priority_boost[2] <= 1'b0;
            end
            
            // Master 3 deadlock detection
            if (master_coherency_state[3] == COHERENT_WRITE_PENDING ||
                master_coherency_state[3] == COHERENT_READ_PENDING) begin
                // Master is stalled, increment counter
                if (stall_counter[3] < 16'hFFFF) begin
                    stall_counter[3] <= stall_counter[3] + 1;
                end
                
                // Detect potential deadlock
                if (stall_counter[3] > 16'hF000) begin
                    deadlock_detected[3] <= 1'b1;
                    priority_boost[3] <= 1'b1;
                end
            end else begin
                // Master is not stalled, reset counters
                stall_counter[3] <= 16'h0000;
                deadlock_detected[3] <= 1'b0;
                priority_boost[3] <= 1'b0;
            end
            
        end
    end

    // Advanced Response Aggregation Logic
    // Combines multiple snoop responses into final coherency decision
    reg [4:0] aggregated_response;
    reg response_data_required;
    reg response_cache_state_change;
    
    always @(*) begin
        // Default response values
        aggregated_response = 5'b00000; // CRRESP_DATATRANSFER
        response_data_required = 1'b0;
        response_cache_state_change = 1'b0;
        
        // Response aggregation logic based on snoop type
        case (current_snoop_type)
            3'b001: begin // ReadShared
                // Check if any master has dirty data to provide
                response_data_required = |snoop_response_received; // Simplified
                aggregated_response = 5'b00100; // CRRESP_OK_SHARED_CLEAN
            end
            
            3'b010: begin // ReadClean
                // Similar to ReadShared but may change cache states
                response_cache_state_change = |snoop_response_received;
                aggregated_response = 5'b00100; // CRRESP_OK_SHARED_CLEAN
            end
            
            3'b111: begin // ReadUnique (exclusive)
                // Invalidate all other copies
                response_cache_state_change = 1'b1;
                if (|snoop_response_received) begin
                    aggregated_response = 5'b00010; // CRRESP_OK_WAS_UNIQUE
                end else begin
                    aggregated_response = 5'b00000; // CRRESP_DATATRANSFER
                end
            end
            
            default: begin
                aggregated_response = 5'b00000; // CRRESP_DATATRANSFER
            end
        endcase
    end

    // Global Coherency Status Outputs
    // assign coherency_active = snoop_broadcast_active || (|master_coherent_transaction); // REMOVED to resolve conflict
    
    // Additional monitoring outputs
    reg global_coherency_error;
    always @(*) begin
        global_coherency_error = snoop_timeout_error || (|deadlock_detected) || (|coherency_violation);
    end

endmodule

//---------------------------------------------------------------------------
// ACE-Lite Snoop Filter
// Address-based coherency filtering and snoop request management
//---------------------------------------------------------------------------
module ace_lite_snoop_filter
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_ID   = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , SNOOP_FILTER_DEPTH = 128
              , CACHELINE_SIZE = 64 // Cache line size in bytes
              // Parameterized conflict counter width - scales with master count
              , CONFLICT_COUNT_WIDTH = (NUM_MASTER <= 2) ? 2 : (NUM_MASTER <= 8) ? 4 : (NUM_MASTER <= 16) ? 5 : (NUM_MASTER <= 32) ? 6 : 8)
(
      input  wire                       clk
    , input  wire                       rst_n
    // Master 0 snoop interface
    , input  wire [WIDTH_AD-1:0]       m0_awaddr
    , input  wire [1:0]                m0_awdomain
    , input  wire [2:0]                m0_awsnoop
    , input  wire                      m0_awvalid
    , input  wire                      m0_awready
    , input  wire [WIDTH_AD-1:0]       m0_araddr
    , input  wire [1:0]                m0_ardomain
    , input  wire [3:0]                m0_arsnoop
    , input  wire                      m0_arvalid
    , input  wire                      m0_arready
    // Master 1 snoop interface
    , input  wire [WIDTH_AD-1:0]       m1_awaddr
    , input  wire [1:0]                m1_awdomain
    , input  wire [2:0]                m1_awsnoop
    , input  wire                      m1_awvalid
    , input  wire                      m1_awready
    , input  wire [WIDTH_AD-1:0]       m1_araddr
    , input  wire [1:0]                m1_ardomain
    , input  wire [3:0]                m1_arsnoop
    , input  wire                      m1_arvalid
    , input  wire                      m1_arready
    // Master 2 snoop interface
    , input  wire [WIDTH_AD-1:0]       m2_awaddr
    , input  wire [1:0]                m2_awdomain
    , input  wire [2:0]                m2_awsnoop
    , input  wire                      m2_awvalid
    , input  wire                      m2_awready
    , input  wire [WIDTH_AD-1:0]       m2_araddr
    , input  wire [1:0]                m2_ardomain
    , input  wire [3:0]                m2_arsnoop
    , input  wire                      m2_arvalid
    , input  wire                      m2_arready
    // Master 3 snoop interface
    , input  wire [WIDTH_AD-1:0]       m3_awaddr
    , input  wire [1:0]                m3_awdomain
    , input  wire [2:0]                m3_awsnoop
    , input  wire                      m3_awvalid
    , input  wire                      m3_awready
    , input  wire [WIDTH_AD-1:0]       m3_araddr
    , input  wire [1:0]                m3_ardomain
    , input  wire [3:0]                m3_arsnoop
    , input  wire                      m3_arvalid
    , input  wire                      m3_arready
    // Snoop filter control
    , input  wire                       snoop_filter_enable
    , input  wire                       snoop_filter_bypass
    , input  wire [WIDTH_AD-1:0]        snoop_base_addr
    , input  wire [WIDTH_AD-1:0]        snoop_addr_mask
    // Snoop filter outputs
    , output wire [NUM_MASTER-1:0]       snoop_required
    , output wire [NUM_MASTER-1:0]       snoop_block
    , output reg  [WIDTH_AD-1:0]         snoop_target_addr
    , output reg  [NUM_MASTER-1:0]       snoop_target_masters
    , output wire [7:0]                  filter_hit_count
    , output wire [7:0]                  filter_miss_count
    
    // Enhanced write-invalidate protocol outputs
    , output reg  [NUM_MASTER-1:0]       invalidate_required
    , output reg  [WIDTH_AD-1:0]         invalidate_addr
    , output reg  [2:0]                  invalidate_type
    , output wire                        invalidate_valid
    , input  wire                        invalidate_ready
    
    // Snoop response aggregation inputs
    , input  wire [4:0]              m0_crresp
    , input  wire                    m0_crvalid
    , output wire                    m0_crready
    , input  wire [4:0]              m1_crresp
    , input  wire                    m1_crvalid
    , output wire                    m1_crready
    , input  wire [4:0]              m2_crresp
    , input  wire                    m2_crvalid
    , output wire                    m2_crready
    , input  wire [4:0]              m3_crresp
    , input  wire                    m3_crvalid
    , output wire                    m3_crready
    
    // Write conflict detection outputs
    , output reg  [NUM_MASTER-1:0]       conflict_detected
    , output reg  [WIDTH_AD-1:0]         conflict_addr
    , output wire [CONFLICT_COUNT_WIDTH-1:0] conflict_count
);

    // Snoop filter parameters
    localparam CACHELINE_OFFSET_BITS = $clog2(CACHELINE_SIZE);
    localparam TAG_BITS = WIDTH_AD - CACHELINE_OFFSET_BITS;
    localparam FILTER_INDEX_BITS = $clog2(SNOOP_FILTER_DEPTH);

    // Domain encodings
    localparam [1:0] DOMAIN_NON_SHAREABLE = 2'b00;
    localparam [1:0] DOMAIN_INNER_SHAREABLE = 2'b01;
    localparam [1:0] DOMAIN_OUTER_SHAREABLE = 2'b10;
    localparam [1:0] DOMAIN_SYSTEM = 2'b11;

    // Write snoop types requiring filtering
    localparam [2:0] AWSNOOP_WRITE_NO_SNOOP = 3'b000;
    localparam [2:0] AWSNOOP_WRITE_LINE_UNIQUE = 3'b001;
    localparam [2:0] AWSNOOP_WRITE_CLEAN = 3'b010;
    localparam [2:0] AWSNOOP_EVICT = 3'b100;

    // Read snoop types requiring filtering
    localparam [3:0] ARSNOOP_READ_NO_SNOOP = 4'b0000;
    localparam [3:0] ARSNOOP_READ_SHARED = 4'b0001;
    localparam [3:0] ARSNOOP_READ_CLEAN = 4'b0010;
    localparam [3:0] ARSNOOP_READ_UNIQUE = 4'b0111;
    localparam [3:0] ARSNOOP_CLEAN_UNIQUE = 4'b1011;

    // Snoop filter table - tracks coherent cache lines
    reg [TAG_BITS-1:0] filter_tag_table [0:SNOOP_FILTER_DEPTH-1];
    reg [NUM_MASTER-1:0] filter_master_table [0:SNOOP_FILTER_DEPTH-1]; // Masters with this line
    reg [1:0] filter_state_table [0:SNOOP_FILTER_DEPTH-1]; // Line state
    reg [SNOOP_FILTER_DEPTH-1:0] filter_valid;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] filter_lru_ptr;

    // Cache line state encodings
    localparam [1:0] LINE_INVALID = 2'b00;
    localparam [1:0] LINE_SHARED = 2'b01;
    localparam [1:0] LINE_UNIQUE = 2'b10;
    localparam [1:0] LINE_DIRTY = 2'b11;

    // Performance monitoring
    reg [7:0] hit_counter;
    reg [7:0] miss_counter;
    reg [CONFLICT_COUNT_WIDTH-1:0] conflict_counter;
    assign filter_hit_count = hit_counter;
    assign filter_miss_count = miss_counter;
    assign conflict_count = conflict_counter;

    // Write-Invalidate Protocol State Machine
    localparam [2:0] INVAL_IDLE = 3'b000;
    localparam [2:0] INVAL_DETECT = 3'b001;
    localparam [2:0] INVAL_BROADCAST = 3'b010;
    localparam [2:0] INVAL_WAIT_RESP = 3'b011;
    localparam [2:0] INVAL_COMPLETE = 3'b100;

    // Invalidation types
    localparam [2:0] INVAL_TYPE_WRITE = 3'b001;
    localparam [2:0] INVAL_TYPE_EVICT = 3'b010;
    localparam [2:0] INVAL_TYPE_CLEAN_INVALID = 3'b011;
    localparam [2:0] INVAL_TYPE_MAKE_INVALID = 3'b100;

    // Write-invalidate protocol registers
    reg [2:0] invalidate_state;
    reg [NUM_MASTER-1:0] invalidate_pending;
    reg [NUM_MASTER-1:0] invalidate_responses_rcvd;
    reg [TAG_BITS-1:0] current_invalidate_tag;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] current_invalidate_idx;
    reg invalidate_in_progress;

    // Write conflict detection registers
    reg [NUM_MASTER-1:0] write_conflict_mask;
    reg [WIDTH_AD-1:0] last_write_addr;
    reg conflict_detected_reg;

    // Snoop response aggregation
    assign m0_crready = (invalidate_state == INVAL_WAIT_RESP) && invalidate_pending[0];
    assign m1_crready = (invalidate_state == INVAL_WAIT_RESP) && invalidate_pending[1];
    assign m2_crready = (invalidate_state == INVAL_WAIT_RESP) && invalidate_pending[2];
    assign m3_crready = (invalidate_state == INVAL_WAIT_RESP) && invalidate_pending[3];

    // Invalidate valid output
    assign invalidate_valid = (invalidate_state == INVAL_BROADCAST) || (invalidate_state == INVAL_WAIT_RESP);

    // Address tag extraction
    function [TAG_BITS-1:0] extract_tag;
        input [WIDTH_AD-1:0] addr;
        begin
            extract_tag = addr[WIDTH_AD-1:CACHELINE_OFFSET_BITS];
        end
    endfunction

    // Snoop filter lookup function
    function [$clog2(SNOOP_FILTER_DEPTH)-1:0] filter_lookup;
        input [TAG_BITS-1:0] tag;
        integer k;
        begin
            filter_lookup = {$clog2(SNOOP_FILTER_DEPTH){1'b1}}; // Invalid index
            for (k = 0; k < SNOOP_FILTER_DEPTH; k = k + 1) begin
                if (filter_valid[k] && (filter_tag_table[k] == tag)) begin
                    filter_lookup = k;
                end
            end
        end
    endfunction

    // Master 0 snoop requirement logic
    wire [TAG_BITS-1:0] m0_aw_tag = extract_tag(m0_awaddr);
    wire [TAG_BITS-1:0] m0_ar_tag = extract_tag(m0_araddr);
    wire m0_aw_coherent = (m0_awdomain != DOMAIN_NON_SHAREABLE) && 
                           (m0_awsnoop != AWSNOOP_WRITE_NO_SNOOP);
    wire m0_ar_coherent = (m0_ardomain != DOMAIN_NON_SHAREABLE) && 
                           (m0_arsnoop != ARSNOOP_READ_NO_SNOOP);
    
    // Master 1 snoop requirement logic
    wire [TAG_BITS-1:0] m1_aw_tag = extract_tag(m1_awaddr);
    wire [TAG_BITS-1:0] m1_ar_tag = extract_tag(m1_araddr);
    wire m1_aw_coherent = (m1_awdomain != DOMAIN_NON_SHAREABLE) && 
                           (m1_awsnoop != AWSNOOP_WRITE_NO_SNOOP);
    wire m1_ar_coherent = (m1_ardomain != DOMAIN_NON_SHAREABLE) && 
                           (m1_arsnoop != ARSNOOP_READ_NO_SNOOP);
    
    // Master 2 snoop requirement logic
    wire [TAG_BITS-1:0] m2_aw_tag = extract_tag(m2_awaddr);
    wire [TAG_BITS-1:0] m2_ar_tag = extract_tag(m2_araddr);
    wire m2_aw_coherent = (m2_awdomain != DOMAIN_NON_SHAREABLE) && 
                           (m2_awsnoop != AWSNOOP_WRITE_NO_SNOOP);
    wire m2_ar_coherent = (m2_ardomain != DOMAIN_NON_SHAREABLE) && 
                           (m2_arsnoop != ARSNOOP_READ_NO_SNOOP);
    
    // Master 3 snoop requirement logic
    wire [TAG_BITS-1:0] m3_aw_tag = extract_tag(m3_awaddr);
    wire [TAG_BITS-1:0] m3_ar_tag = extract_tag(m3_araddr);
    wire m3_aw_coherent = (m3_awdomain != DOMAIN_NON_SHAREABLE) && 
                           (m3_awsnoop != AWSNOOP_WRITE_NO_SNOOP);
    wire m3_ar_coherent = (m3_ardomain != DOMAIN_NON_SHAREABLE) && 
                           (m3_arsnoop != ARSNOOP_READ_NO_SNOOP);
    
    // Lookup index registers for filter operations
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] m0_aw_lookup_idx, m0_ar_lookup_idx;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] m0_aw_snoop_idx, m0_ar_snoop_idx;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] m1_aw_lookup_idx, m1_ar_lookup_idx;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] m1_aw_snoop_idx, m1_ar_snoop_idx;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] m2_aw_lookup_idx, m2_ar_lookup_idx;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] m2_aw_snoop_idx, m2_ar_snoop_idx;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] m3_aw_lookup_idx, m3_ar_lookup_idx;
    reg [$clog2(SNOOP_FILTER_DEPTH)-1:0] m3_aw_snoop_idx, m3_ar_snoop_idx;

    // Enhanced Write-Invalidate Protocol State Machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            invalidate_state <= INVAL_IDLE;
            invalidate_pending <= {NUM_MASTER{1'b0}};
            invalidate_responses_rcvd <= {NUM_MASTER{1'b0}};
            invalidate_required <= {NUM_MASTER{1'b0}};
            invalidate_addr <= {WIDTH_AD{1'b0}};
            invalidate_type <= 3'b0;
            invalidate_in_progress <= 1'b0;
            conflict_detected <= {NUM_MASTER{1'b0}};
            conflict_addr <= {WIDTH_AD{1'b0}};
            write_conflict_mask <= {NUM_MASTER{1'b0}};
            conflict_detected_reg <= 1'b0;
        end else begin
            case (invalidate_state)
                INVAL_IDLE: begin
                    // Detect write conflicts requiring invalidation
                    invalidate_required <= {NUM_MASTER{1'b0}};
                    conflict_detected <= {NUM_MASTER{1'b0}};
                    
                    // Master 0 write conflict detection
                    if (m0_awvalid && m0_awready && m0_aw_coherent) begin
                        current_invalidate_tag = extract_tag(m0_awaddr);
                        current_invalidate_idx = filter_lookup(current_invalidate_tag);
                        
                        // Check if other masters have this cache line
                        if (current_invalidate_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                            write_conflict_mask = filter_master_table[current_invalidate_idx] & ~(1'b1 << 0);
                            
                            if (|write_conflict_mask) begin
                                // Conflict detected - initiate invalidation
                                invalidate_state <= INVAL_DETECT;
                                invalidate_addr <= m0_awaddr;
                                invalidate_pending <= write_conflict_mask;
                                conflict_detected[0] <= 1'b1;
                                conflict_addr <= m0_awaddr;
                                
                                // Determine invalidation type based on snoop type
                                case (m0_awsnoop)
                                    AWSNOOP_WRITE_LINE_UNIQUE: invalidate_type <= INVAL_TYPE_WRITE;
                                    AWSNOOP_EVICT: invalidate_type <= INVAL_TYPE_EVICT;
                                    default: invalidate_type <= INVAL_TYPE_WRITE;
                                endcase
                            end
                        end
                    end
                    
                    // Master 1 write conflict detection
                    if (m1_awvalid && m1_awready && m1_aw_coherent) begin
                        current_invalidate_tag = extract_tag(m1_awaddr);
                        current_invalidate_idx = filter_lookup(current_invalidate_tag);
                        
                        // Check if other masters have this cache line
                        if (current_invalidate_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                            write_conflict_mask = filter_master_table[current_invalidate_idx] & ~(1'b1 << 1);
                            
                            if (|write_conflict_mask) begin
                                // Conflict detected - initiate invalidation
                                invalidate_state <= INVAL_DETECT;
                                invalidate_addr <= m1_awaddr;
                                invalidate_pending <= write_conflict_mask;
                                conflict_detected[1] <= 1'b1;
                                conflict_addr <= m1_awaddr;
                                
                                // Determine invalidation type based on snoop type
                                case (m1_awsnoop)
                                    AWSNOOP_WRITE_LINE_UNIQUE: invalidate_type <= INVAL_TYPE_WRITE;
                                    AWSNOOP_EVICT: invalidate_type <= INVAL_TYPE_EVICT;
                                    default: invalidate_type <= INVAL_TYPE_WRITE;
                                endcase
                            end
                        end
                    end
                    
                    // Master 2 write conflict detection
                    if (m2_awvalid && m2_awready && m2_aw_coherent) begin
                        current_invalidate_tag = extract_tag(m2_awaddr);
                        current_invalidate_idx = filter_lookup(current_invalidate_tag);
                        
                        // Check if other masters have this cache line
                        if (current_invalidate_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                            write_conflict_mask = filter_master_table[current_invalidate_idx] & ~(1'b1 << 2);
                            
                            if (|write_conflict_mask) begin
                                // Conflict detected - initiate invalidation
                                invalidate_state <= INVAL_DETECT;
                                invalidate_addr <= m2_awaddr;
                                invalidate_pending <= write_conflict_mask;
                                conflict_detected[2] <= 1'b1;
                                conflict_addr <= m2_awaddr;
                                
                                // Determine invalidation type based on snoop type
                                case (m2_awsnoop)
                                    AWSNOOP_WRITE_LINE_UNIQUE: invalidate_type <= INVAL_TYPE_WRITE;
                                    AWSNOOP_EVICT: invalidate_type <= INVAL_TYPE_EVICT;
                                    default: invalidate_type <= INVAL_TYPE_WRITE;
                                endcase
                            end
                        end
                    end
                    
                    // Master 3 write conflict detection
                    if (m3_awvalid && m3_awready && m3_aw_coherent) begin
                        current_invalidate_tag = extract_tag(m3_awaddr);
                        current_invalidate_idx = filter_lookup(current_invalidate_tag);
                        
                        // Check if other masters have this cache line
                        if (current_invalidate_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                            write_conflict_mask = filter_master_table[current_invalidate_idx] & ~(1'b1 << 3);
                            
                            if (|write_conflict_mask) begin
                                // Conflict detected - initiate invalidation
                                invalidate_state <= INVAL_DETECT;
                                invalidate_addr <= m3_awaddr;
                                invalidate_pending <= write_conflict_mask;
                                conflict_detected[3] <= 1'b1;
                                conflict_addr <= m3_awaddr;
                                
                                // Determine invalidation type based on snoop type
                                case (m3_awsnoop)
                                    AWSNOOP_WRITE_LINE_UNIQUE: invalidate_type <= INVAL_TYPE_WRITE;
                                    AWSNOOP_EVICT: invalidate_type <= INVAL_TYPE_EVICT;
                                    default: invalidate_type <= INVAL_TYPE_WRITE;
                                endcase
                            end
                        end
                    end
                end
                
                INVAL_DETECT: begin
                    // Transition to broadcast invalidation
                    invalidate_state <= INVAL_BROADCAST;
                    invalidate_required <= invalidate_pending;
                    invalidate_in_progress <= 1'b1;
                    conflict_counter <= conflict_counter + 1;
                end
                
                INVAL_BROADCAST: begin
                    // Wait for invalidate_ready from interconnect
                    if (invalidate_ready) begin
                        invalidate_state <= INVAL_WAIT_RESP;
                        invalidate_responses_rcvd <= {NUM_MASTER{1'b0}};
                    end
                end
                
                INVAL_WAIT_RESP: begin
                    // Collect snoop responses from masters
                    if (m0_crvalid && invalidate_pending[0]) begin
                        invalidate_responses_rcvd[0] <= 1'b1;
                    end
                    if (m1_crvalid && invalidate_pending[1]) begin
                        invalidate_responses_rcvd[1] <= 1'b1;
                    end
                    if (m2_crvalid && invalidate_pending[2]) begin
                        invalidate_responses_rcvd[2] <= 1'b1;
                    end
                    if (m3_crvalid && invalidate_pending[3]) begin
                        invalidate_responses_rcvd[3] <= 1'b1;
                    end
                    
                    // Check if all required responses received
                    if ((invalidate_responses_rcvd & invalidate_pending) == invalidate_pending) begin
                        invalidate_state <= INVAL_COMPLETE;
                    end
                end
                
                INVAL_COMPLETE: begin
                    // Complete invalidation and update filter
                    if (current_invalidate_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                        // Clear invalidated masters from filter
                        filter_master_table[current_invalidate_idx] <= 
                            filter_master_table[current_invalidate_idx] & ~invalidate_pending;
                    end
                    
                    // Return to idle
                    invalidate_state <= INVAL_IDLE;
                    invalidate_required <= {NUM_MASTER{1'b0}};
                    invalidate_in_progress <= 1'b0;
                end
                
                default: begin
                    invalidate_state <= INVAL_IDLE;
                end
            endcase
        end
    end

    // Snoop filter table management
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            filter_valid <= {SNOOP_FILTER_DEPTH{1'b0}};
            filter_lru_ptr <= 0;
            hit_counter <= 8'h0;
            miss_counter <= 8'h0;
            conflict_counter <= {CONFLICT_COUNT_WIDTH{1'b0}};
            // Initialize filter tables would be done with generate blocks in actual RTL
            // Initialize filter tables would be done with generate blocks in actual RTL
            // Initialize filter tables would be done with generate blocks in actual RTL
            // Initialize filter tables would be done with generate blocks in actual RTL
        end else if (snoop_filter_enable && !snoop_filter_bypass && !invalidate_in_progress) begin
            // Process Master 0 write transactions
            if (m0_awvalid && m0_awready && m0_aw_coherent) begin
                m0_aw_lookup_idx = filter_lookup(m0_aw_tag);
                if (m0_aw_lookup_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    // Hit: Update existing entry
                    filter_master_table[m0_aw_lookup_idx][0] <= 1'b1;
                    if (m0_awsnoop == AWSNOOP_WRITE_LINE_UNIQUE) begin
                        filter_state_table[m0_aw_lookup_idx] <= LINE_UNIQUE;
                        // Invalidate other masters
                        filter_master_table[m0_aw_lookup_idx][1] <= 1'b0;
                        filter_master_table[m0_aw_lookup_idx][2] <= 1'b0;
                        filter_master_table[m0_aw_lookup_idx][3] <= 1'b0;
                    end else if (m0_awsnoop == AWSNOOP_WRITE_CLEAN) begin
                        filter_state_table[m0_aw_lookup_idx] <= LINE_DIRTY;
                    end
                    hit_counter <= hit_counter + 1;
                end else begin
                    // Miss: Allocate new entry
                    filter_tag_table[filter_lru_ptr] <= m0_aw_tag;
                    filter_master_table[filter_lru_ptr] <= 1'b0;
                    filter_master_table[filter_lru_ptr][0] <= 1'b1;
                    filter_state_table[filter_lru_ptr] <= LINE_SHARED;
                    filter_valid[filter_lru_ptr] <= 1'b1;
                    filter_lru_ptr <= (filter_lru_ptr + 1) % SNOOP_FILTER_DEPTH;
                    miss_counter <= miss_counter + 1;
                end
            end

            // Process Master 1 write transactions
            if (m1_awvalid && m1_awready && m1_aw_coherent) begin
                m1_aw_lookup_idx = filter_lookup(m1_aw_tag);
                if (m1_aw_lookup_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    // Hit: Update existing entry
                    filter_master_table[m1_aw_lookup_idx][1] <= 1'b1;
                    if (m1_awsnoop == AWSNOOP_WRITE_LINE_UNIQUE) begin
                        filter_state_table[m1_aw_lookup_idx] <= LINE_UNIQUE;
                        // Invalidate other masters
                        filter_master_table[m1_aw_lookup_idx][0] <= 1'b0;
                        filter_master_table[m1_aw_lookup_idx][2] <= 1'b0;
                        filter_master_table[m1_aw_lookup_idx][3] <= 1'b0;
                    end else if (m1_awsnoop == AWSNOOP_WRITE_CLEAN) begin
                        filter_state_table[m1_aw_lookup_idx] <= LINE_DIRTY;
                    end
                    hit_counter <= hit_counter + 1;
                end else begin
                    // Miss: Allocate new entry
                    filter_tag_table[filter_lru_ptr] <= m1_aw_tag;
                    filter_master_table[filter_lru_ptr] <= 1'b0;
                    filter_master_table[filter_lru_ptr][1] <= 1'b1;
                    filter_state_table[filter_lru_ptr] <= LINE_SHARED;
                    filter_valid[filter_lru_ptr] <= 1'b1;
                    filter_lru_ptr <= (filter_lru_ptr + 1) % SNOOP_FILTER_DEPTH;
                    miss_counter <= miss_counter + 1;
                end
            end

            // Process Master 2 write transactions
            if (m2_awvalid && m2_awready && m2_aw_coherent) begin
                m2_aw_lookup_idx = filter_lookup(m2_aw_tag);
                if (m2_aw_lookup_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    // Hit: Update existing entry
                    filter_master_table[m2_aw_lookup_idx][2] <= 1'b1;
                    if (m2_awsnoop == AWSNOOP_WRITE_LINE_UNIQUE) begin
                        filter_state_table[m2_aw_lookup_idx] <= LINE_UNIQUE;
                        // Invalidate other masters
                        filter_master_table[m2_aw_lookup_idx][0] <= 1'b0;
                        filter_master_table[m2_aw_lookup_idx][1] <= 1'b0;
                        filter_master_table[m2_aw_lookup_idx][3] <= 1'b0;
                    end else if (m2_awsnoop == AWSNOOP_WRITE_CLEAN) begin
                        filter_state_table[m2_aw_lookup_idx] <= LINE_DIRTY;
                    end
                    hit_counter <= hit_counter + 1;
                end else begin
                    // Miss: Allocate new entry
                    filter_tag_table[filter_lru_ptr] <= m2_aw_tag;
                    filter_master_table[filter_lru_ptr] <= 1'b0;
                    filter_master_table[filter_lru_ptr][2] <= 1'b1;
                    filter_state_table[filter_lru_ptr] <= LINE_SHARED;
                    filter_valid[filter_lru_ptr] <= 1'b1;
                    filter_lru_ptr <= (filter_lru_ptr + 1) % SNOOP_FILTER_DEPTH;
                    miss_counter <= miss_counter + 1;
                end
            end

            // Process Master 3 write transactions
            if (m3_awvalid && m3_awready && m3_aw_coherent) begin
                m3_aw_lookup_idx = filter_lookup(m3_aw_tag);
                if (m3_aw_lookup_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    // Hit: Update existing entry
                    filter_master_table[m3_aw_lookup_idx][3] <= 1'b1;
                    if (m3_awsnoop == AWSNOOP_WRITE_LINE_UNIQUE) begin
                        filter_state_table[m3_aw_lookup_idx] <= LINE_UNIQUE;
                        // Invalidate other masters
                        filter_master_table[m3_aw_lookup_idx][0] <= 1'b0;
                        filter_master_table[m3_aw_lookup_idx][1] <= 1'b0;
                        filter_master_table[m3_aw_lookup_idx][2] <= 1'b0;
                    end else if (m3_awsnoop == AWSNOOP_WRITE_CLEAN) begin
                        filter_state_table[m3_aw_lookup_idx] <= LINE_DIRTY;
                    end
                    hit_counter <= hit_counter + 1;
                end else begin
                    // Miss: Allocate new entry
                    filter_tag_table[filter_lru_ptr] <= m3_aw_tag;
                    filter_master_table[filter_lru_ptr] <= 1'b0;
                    filter_master_table[filter_lru_ptr][3] <= 1'b1;
                    filter_state_table[filter_lru_ptr] <= LINE_SHARED;
                    filter_valid[filter_lru_ptr] <= 1'b1;
                    filter_lru_ptr <= (filter_lru_ptr + 1) % SNOOP_FILTER_DEPTH;
                    miss_counter <= miss_counter + 1;
                end
            end

            // Process Master 0 read transactions
            if (m0_arvalid && m0_arready && m0_ar_coherent) begin
                m0_ar_lookup_idx = filter_lookup(m0_ar_tag);
                if (m0_ar_lookup_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    // Hit: Update existing entry
                    filter_master_table[m0_ar_lookup_idx][0] <= 1'b1;
                    if (m0_arsnoop == ARSNOOP_READ_UNIQUE) begin
                        filter_state_table[m0_ar_lookup_idx] <= LINE_UNIQUE;
                        // Invalidate other masters
                        filter_master_table[m0_ar_lookup_idx][1] <= 1'b0;
                        filter_master_table[m0_ar_lookup_idx][2] <= 1'b0;
                        filter_master_table[m0_ar_lookup_idx][3] <= 1'b0;
                    end else begin
                        filter_state_table[m0_ar_lookup_idx] <= LINE_SHARED;
                    end
                    hit_counter <= hit_counter + 1;
                end else begin
                    // Miss: Allocate new entry for coherent reads
                    if (m0_arsnoop != ARSNOOP_READ_NO_SNOOP) begin
                        filter_tag_table[filter_lru_ptr] <= m0_ar_tag;
                        filter_master_table[filter_lru_ptr] <= 1'b0;
                        filter_master_table[filter_lru_ptr][0] <= 1'b1;
                        filter_state_table[filter_lru_ptr] <= LINE_SHARED;
                        filter_valid[filter_lru_ptr] <= 1'b1;
                        filter_lru_ptr <= (filter_lru_ptr + 1) % SNOOP_FILTER_DEPTH;
                    end
                    miss_counter <= miss_counter + 1;
                end
            end

            // Process Master 1 read transactions
            if (m1_arvalid && m1_arready && m1_ar_coherent) begin
                m1_ar_lookup_idx = filter_lookup(m1_ar_tag);
                if (m1_ar_lookup_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    // Hit: Update existing entry
                    filter_master_table[m1_ar_lookup_idx][1] <= 1'b1;
                    if (m1_arsnoop == ARSNOOP_READ_UNIQUE) begin
                        filter_state_table[m1_ar_lookup_idx] <= LINE_UNIQUE;
                        // Invalidate other masters
                        filter_master_table[m1_ar_lookup_idx][0] <= 1'b0;
                        filter_master_table[m1_ar_lookup_idx][2] <= 1'b0;
                        filter_master_table[m1_ar_lookup_idx][3] <= 1'b0;
                    end else begin
                        filter_state_table[m1_ar_lookup_idx] <= LINE_SHARED;
                    end
                    hit_counter <= hit_counter + 1;
                end else begin
                    // Miss: Allocate new entry for coherent reads
                    if (m1_arsnoop != ARSNOOP_READ_NO_SNOOP) begin
                        filter_tag_table[filter_lru_ptr] <= m1_ar_tag;
                        filter_master_table[filter_lru_ptr] <= 1'b0;
                        filter_master_table[filter_lru_ptr][1] <= 1'b1;
                        filter_state_table[filter_lru_ptr] <= LINE_SHARED;
                        filter_valid[filter_lru_ptr] <= 1'b1;
                        filter_lru_ptr <= (filter_lru_ptr + 1) % SNOOP_FILTER_DEPTH;
                    end
                    miss_counter <= miss_counter + 1;
                end
            end

            // Process Master 2 read transactions
            if (m2_arvalid && m2_arready && m2_ar_coherent) begin
                m2_ar_lookup_idx = filter_lookup(m2_ar_tag);
                if (m2_ar_lookup_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    // Hit: Update existing entry
                    filter_master_table[m2_ar_lookup_idx][2] <= 1'b1;
                    if (m2_arsnoop == ARSNOOP_READ_UNIQUE) begin
                        filter_state_table[m2_ar_lookup_idx] <= LINE_UNIQUE;
                        // Invalidate other masters
                        filter_master_table[m2_ar_lookup_idx][0] <= 1'b0;
                        filter_master_table[m2_ar_lookup_idx][1] <= 1'b0;
                        filter_master_table[m2_ar_lookup_idx][3] <= 1'b0;
                    end else begin
                        filter_state_table[m2_ar_lookup_idx] <= LINE_SHARED;
                    end
                    hit_counter <= hit_counter + 1;
                end else begin
                    // Miss: Allocate new entry for coherent reads
                    if (m2_arsnoop != ARSNOOP_READ_NO_SNOOP) begin
                        filter_tag_table[filter_lru_ptr] <= m2_ar_tag;
                        filter_master_table[filter_lru_ptr] <= 1'b0;
                        filter_master_table[filter_lru_ptr][2] <= 1'b1;
                        filter_state_table[filter_lru_ptr] <= LINE_SHARED;
                        filter_valid[filter_lru_ptr] <= 1'b1;
                        filter_lru_ptr <= (filter_lru_ptr + 1) % SNOOP_FILTER_DEPTH;
                    end
                    miss_counter <= miss_counter + 1;
                end
            end

            // Process Master 3 read transactions
            if (m3_arvalid && m3_arready && m3_ar_coherent) begin
                m3_ar_lookup_idx = filter_lookup(m3_ar_tag);
                if (m3_ar_lookup_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    // Hit: Update existing entry
                    filter_master_table[m3_ar_lookup_idx][3] <= 1'b1;
                    if (m3_arsnoop == ARSNOOP_READ_UNIQUE) begin
                        filter_state_table[m3_ar_lookup_idx] <= LINE_UNIQUE;
                        // Invalidate other masters
                        filter_master_table[m3_ar_lookup_idx][0] <= 1'b0;
                        filter_master_table[m3_ar_lookup_idx][1] <= 1'b0;
                        filter_master_table[m3_ar_lookup_idx][2] <= 1'b0;
                    end else begin
                        filter_state_table[m3_ar_lookup_idx] <= LINE_SHARED;
                    end
                    hit_counter <= hit_counter + 1;
                end else begin
                    // Miss: Allocate new entry for coherent reads
                    if (m3_arsnoop != ARSNOOP_READ_NO_SNOOP) begin
                        filter_tag_table[filter_lru_ptr] <= m3_ar_tag;
                        filter_master_table[filter_lru_ptr] <= 1'b0;
                        filter_master_table[filter_lru_ptr][3] <= 1'b1;
                        filter_state_table[filter_lru_ptr] <= LINE_SHARED;
                        filter_valid[filter_lru_ptr] <= 1'b1;
                        filter_lru_ptr <= (filter_lru_ptr + 1) % SNOOP_FILTER_DEPTH;
                    end
                    miss_counter <= miss_counter + 1;
                end
            end

        end
    end

    // Snoop requirement output logic
    wire m0_snoop_req_aw, m0_snoop_req_ar;
    assign m0_snoop_req_aw = m0_awvalid && m0_aw_coherent && snoop_filter_enable;
    assign m0_snoop_req_ar = m0_arvalid && m0_ar_coherent && snoop_filter_enable;
    assign snoop_required[0] = m0_snoop_req_aw || m0_snoop_req_ar;
    assign snoop_block[0] = snoop_required[0] && !snoop_filter_bypass;
    wire m1_snoop_req_aw, m1_snoop_req_ar;
    assign m1_snoop_req_aw = m1_awvalid && m1_aw_coherent && snoop_filter_enable;
    assign m1_snoop_req_ar = m1_arvalid && m1_ar_coherent && snoop_filter_enable;
    assign snoop_required[1] = m1_snoop_req_aw || m1_snoop_req_ar;
    assign snoop_block[1] = snoop_required[1] && !snoop_filter_bypass;
    wire m2_snoop_req_aw, m2_snoop_req_ar;
    assign m2_snoop_req_aw = m2_awvalid && m2_aw_coherent && snoop_filter_enable;
    assign m2_snoop_req_ar = m2_arvalid && m2_ar_coherent && snoop_filter_enable;
    assign snoop_required[2] = m2_snoop_req_aw || m2_snoop_req_ar;
    assign snoop_block[2] = snoop_required[2] && !snoop_filter_bypass;
    wire m3_snoop_req_aw, m3_snoop_req_ar;
    assign m3_snoop_req_aw = m3_awvalid && m3_aw_coherent && snoop_filter_enable;
    assign m3_snoop_req_ar = m3_arvalid && m3_ar_coherent && snoop_filter_enable;
    assign snoop_required[3] = m3_snoop_req_aw || m3_snoop_req_ar;
    assign snoop_block[3] = snoop_required[3] && !snoop_filter_bypass;

    // Snoop target address and master selection
    always @(*) begin
        snoop_target_addr = 32'h0;
        snoop_target_masters = {NUM_MASTER{1'b0}};
        
        // Master 0 snoop targeting
        if (snoop_required[0]) begin
            if (m0_awvalid) begin
