                if (m2_aw_snoop_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
                    snoop_target_masters = filter_master_table[m2_aw_snoop_idx] & ~(1'b1 << 2);
                end
            end else if (m2_arvalid) begin
                snoop_target_addr = m2_araddr;
                // Find other masters with this cache line
                m2_ar_snoop_idx = filter_lookup(m2_ar_tag);
                if (m2_ar_snoop_idx != {$clog2(SNOOP_FILTER_DEPTH){1'b1}}) begin
