//---------------------------------------------------------------------------
// ACE-Lite Barrier Synchronization
// Memory and synchronization barrier transaction handling
//---------------------------------------------------------------------------
module ace_lite_barrier_sync
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_ID   = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , BARRIER_TIMEOUT = 1000) // Timeout cycles
(
      input  wire                       clk
    , input  wire                       rst_n
    // Master 0 barrier interface
    , input  wire [1:0]                m0_awbar
    , input  wire [1:0]                m0_arbar
    , input  wire                      m0_awvalid
    , input  wire                      m0_awready
    , input  wire                      m0_arvalid
    , input  wire                      m0_arready
    , input  wire                      m0_bvalid
    , input  wire                      m0_bready
    , input  wire                      m0_rvalid
    , input  wire                      m0_rready
    , input  wire                      m0_rlast
    // Master 1 barrier interface
    , input  wire [1:0]                m1_awbar
    , input  wire [1:0]                m1_arbar
    , input  wire                      m1_awvalid
    , input  wire                      m1_awready
    , input  wire                      m1_arvalid
    , input  wire                      m1_arready
    , input  wire                      m1_bvalid
    , input  wire                      m1_bready
    , input  wire                      m1_rvalid
    , input  wire                      m1_rready
    , input  wire                      m1_rlast
    // Master 2 barrier interface
    , input  wire [1:0]                m2_awbar
    , input  wire [1:0]                m2_arbar
    , input  wire                      m2_awvalid
    , input  wire                      m2_awready
    , input  wire                      m2_arvalid
    , input  wire                      m2_arready
    , input  wire                      m2_bvalid
    , input  wire                      m2_bready
    , input  wire                      m2_rvalid
    , input  wire                      m2_rready
    , input  wire                      m2_rlast
    // Master 3 barrier interface
    , input  wire [1:0]                m3_awbar
    , input  wire [1:0]                m3_arbar
    , input  wire                      m3_awvalid
    , input  wire                      m3_awready
    , input  wire                      m3_arvalid
    , input  wire                      m3_arready
    , input  wire                      m3_bvalid
    , input  wire                      m3_bready
    , input  wire                      m3_rvalid
    , input  wire                      m3_rready
    , input  wire                      m3_rlast
    // Barrier control
    , input  wire                       barrier_enable
    , input  wire                       global_barrier_request
    , input  wire [NUM_MASTER-1:0]      master_barrier_override
    // Barrier status outputs
    , output reg  [NUM_MASTER-1:0]       barrier_active
    , output reg  [NUM_MASTER-1:0]       barrier_block
    , output reg                         global_barrier_active
    , output wire [NUM_MASTER-1:0]       barrier_timeout
    , output reg  [15:0]                 pending_transactions [NUM_MASTER-1:0]
);

    // Barrier type encodings (ACE-Lite)
    localparam [1:0] BAR_NORMAL_ACCESS = 2'b00;
    localparam [1:0] BAR_MEMORY_BARRIER = 2'b01;
    localparam [1:0] BAR_RESERVED = 2'b10;
    localparam [1:0] BAR_SYNC_BARRIER = 2'b11;

    // Barrier state machine encodings
    localparam [2:0] BARRIER_IDLE = 3'b000;
    localparam [2:0] BARRIER_PENDING = 3'b001;
    localparam [2:0] BARRIER_DRAINING = 3'b010;
    localparam [2:0] BARRIER_ACTIVE = 3'b011;
    localparam [2:0] BARRIER_COMPLETE = 3'b100;
    localparam [2:0] BARRIER_TIMEOUT_STATE = 3'b111;

    // Master barrier state tracking
    reg [2:0] barrier_state [NUM_MASTER-1:0];
    reg [1:0] barrier_type [NUM_MASTER-1:0];
    reg [15:0] outstanding_writes [NUM_MASTER-1:0];
    reg [15:0] outstanding_reads [NUM_MASTER-1:0];
    reg [15:0] barrier_timeout_counter [NUM_MASTER-1:0];
    reg [NUM_MASTER-1:0] barrier_timeout_flag;

    // Global barrier coordination
    reg [NUM_MASTER-1:0] global_barrier_participants;
    reg [NUM_MASTER-1:0] global_barrier_ready;
    reg global_barrier_state;
    wire all_masters_barrier_ready = &(global_barrier_ready | ~global_barrier_participants);

    // Outstanding transaction tracking
    // Master 0 transaction tracking
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            outstanding_writes[0] <= 16'h0;
            outstanding_reads[0] <= 16'h0;
        end else begin
            // Write transaction tracking
            case ({m0_awvalid & m0_awready, m0_bvalid & m0_bready})
                2'b10: outstanding_writes[0] <= outstanding_writes[0] + 1; // New write
                2'b01: outstanding_writes[0] <= outstanding_writes[0] - 1; // Write complete
                2'b11: outstanding_writes[0] <= outstanding_writes[0];     // Both
                default: outstanding_writes[0] <= outstanding_writes[0];   // No change
            endcase
            
            // Read transaction tracking
            case ({m0_arvalid & m0_arready, m0_rvalid & m0_rready & m0_rlast})
                2'b10: outstanding_reads[0] <= outstanding_reads[0] + 1; // New read
                2'b01: outstanding_reads[0] <= outstanding_reads[0] - 1; // Read complete
                2'b11: outstanding_reads[0] <= outstanding_reads[0];     // Both
                default: outstanding_reads[0] <= outstanding_reads[0];   // No change
            endcase
        end
    end

    // Master 1 transaction tracking
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            outstanding_writes[1] <= 16'h0;
            outstanding_reads[1] <= 16'h0;
        end else begin
            // Write transaction tracking
            case ({m1_awvalid & m1_awready, m1_bvalid & m1_bready})
                2'b10: outstanding_writes[1] <= outstanding_writes[1] + 1; // New write
                2'b01: outstanding_writes[1] <= outstanding_writes[1] - 1; // Write complete
                2'b11: outstanding_writes[1] <= outstanding_writes[1];     // Both
                default: outstanding_writes[1] <= outstanding_writes[1];   // No change
            endcase
            
            // Read transaction tracking
            case ({m1_arvalid & m1_arready, m1_rvalid & m1_rready & m1_rlast})
                2'b10: outstanding_reads[1] <= outstanding_reads[1] + 1; // New read
                2'b01: outstanding_reads[1] <= outstanding_reads[1] - 1; // Read complete
                2'b11: outstanding_reads[1] <= outstanding_reads[1];     // Both
                default: outstanding_reads[1] <= outstanding_reads[1];   // No change
            endcase
        end
    end

    // Master 2 transaction tracking
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            outstanding_writes[2] <= 16'h0;
            outstanding_reads[2] <= 16'h0;
        end else begin
            // Write transaction tracking
            case ({m2_awvalid & m2_awready, m2_bvalid & m2_bready})
                2'b10: outstanding_writes[2] <= outstanding_writes[2] + 1; // New write
                2'b01: outstanding_writes[2] <= outstanding_writes[2] - 1; // Write complete
                2'b11: outstanding_writes[2] <= outstanding_writes[2];     // Both
                default: outstanding_writes[2] <= outstanding_writes[2];   // No change
            endcase
            
            // Read transaction tracking
            case ({m2_arvalid & m2_arready, m2_rvalid & m2_rready & m2_rlast})
                2'b10: outstanding_reads[2] <= outstanding_reads[2] + 1; // New read
                2'b01: outstanding_reads[2] <= outstanding_reads[2] - 1; // Read complete
                2'b11: outstanding_reads[2] <= outstanding_reads[2];     // Both
                default: outstanding_reads[2] <= outstanding_reads[2];   // No change
            endcase
        end
    end

    // Master 3 transaction tracking
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            outstanding_writes[3] <= 16'h0;
            outstanding_reads[3] <= 16'h0;
        end else begin
            // Write transaction tracking
            case ({m3_awvalid & m3_awready, m3_bvalid & m3_bready})
                2'b10: outstanding_writes[3] <= outstanding_writes[3] + 1; // New write
                2'b01: outstanding_writes[3] <= outstanding_writes[3] - 1; // Write complete
                2'b11: outstanding_writes[3] <= outstanding_writes[3];     // Both
                default: outstanding_writes[3] <= outstanding_writes[3];   // No change
            endcase
            
            // Read transaction tracking
            case ({m3_arvalid & m3_arready, m3_rvalid & m3_rready & m3_rlast})
                2'b10: outstanding_reads[3] <= outstanding_reads[3] + 1; // New read
                2'b01: outstanding_reads[3] <= outstanding_reads[3] - 1; // Read complete
                2'b11: outstanding_reads[3] <= outstanding_reads[3];     // Both
                default: outstanding_reads[3] <= outstanding_reads[3];   // No change
            endcase
        end
    end

    // Master 0 barrier state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            barrier_state[0] <= BARRIER_IDLE;
            barrier_type[0] <= BAR_NORMAL_ACCESS;
            barrier_timeout_counter[0] <= 16'h0;
            barrier_timeout_flag[0] <= 1'b0;
        end else begin
            case (barrier_state[0])
                BARRIER_IDLE: begin
                    barrier_timeout_counter[0] <= 16'h0;
                    barrier_timeout_flag[0] <= 1'b0;
                    // Detect barrier transaction
                    if ((m0_awvalid && m0_awbar != BAR_NORMAL_ACCESS) ||
                        (m0_arvalid && m0_arbar != BAR_NORMAL_ACCESS)) begin
                        barrier_state[0] <= BARRIER_PENDING;
                        barrier_type[0] <= m0_awvalid ? m0_awbar : m0_arbar;
                    end else if (global_barrier_request && !master_barrier_override[0]) begin
                        barrier_state[0] <= BARRIER_DRAINING;
                        barrier_type[0] <= BAR_SYNC_BARRIER;
                    end
                end
                BARRIER_PENDING: begin
                    // Wait for barrier transaction to be accepted
                    if ((m0_awvalid && m0_awready) || (m0_arvalid && m0_arready)) begin
                        barrier_state[0] <= BARRIER_DRAINING;
                    end
                    barrier_timeout_counter[0] <= barrier_timeout_counter[0] + 1;
                    if (barrier_timeout_counter[0] >= BARRIER_TIMEOUT) begin
                        barrier_state[0] <= BARRIER_TIMEOUT_STATE;
                        barrier_timeout_flag[0] <= 1'b1;
                    end
                end
                BARRIER_DRAINING: begin
                    // Wait for all outstanding transactions to complete
                    if (barrier_type[0] == BAR_MEMORY_BARRIER) begin
                        // Memory barrier: drain writes only
                        if (outstanding_writes[0] == 16'h0) begin
                            barrier_state[0] <= BARRIER_ACTIVE;
                        end
                    end else if (barrier_type[0] == BAR_SYNC_BARRIER) begin
                        // Sync barrier: drain all transactions
                        if ((outstanding_writes[0] == 16'h0) && (outstanding_reads[0] == 16'h0)) begin
                            barrier_state[0] <= BARRIER_ACTIVE;
                        end
                    end
                    barrier_timeout_counter[0] <= barrier_timeout_counter[0] + 1;
                    if (barrier_timeout_counter[0] >= BARRIER_TIMEOUT) begin
                        barrier_state[0] <= BARRIER_TIMEOUT_STATE;
                        barrier_timeout_flag[0] <= 1'b1;
                    end
                end
                BARRIER_ACTIVE: begin
                    // Barrier is active, block new transactions
                    if (barrier_type[0] == BAR_SYNC_BARRIER && global_barrier_request) begin
                        // Wait for global barrier completion
                        if (all_masters_barrier_ready) begin
                            barrier_state[0] <= BARRIER_COMPLETE;
                        end
                    end else begin
                        // Local barrier completes immediately after draining
                        barrier_state[0] <= BARRIER_COMPLETE;
                    end
                end
                BARRIER_COMPLETE: begin
                    // Barrier complete, return to idle
                    barrier_state[0] <= BARRIER_IDLE;
                end
                BARRIER_TIMEOUT_STATE: begin
                    // Barrier timeout, force completion
                    barrier_state[0] <= BARRIER_IDLE;
                end
                default: barrier_state[0] <= BARRIER_IDLE;
            endcase
        end
    end

    // Master 1 barrier state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            barrier_state[1] <= BARRIER_IDLE;
            barrier_type[1] <= BAR_NORMAL_ACCESS;
            barrier_timeout_counter[1] <= 16'h0;
            barrier_timeout_flag[1] <= 1'b0;
        end else begin
            case (barrier_state[1])
                BARRIER_IDLE: begin
                    barrier_timeout_counter[1] <= 16'h0;
                    barrier_timeout_flag[1] <= 1'b0;
                    // Detect barrier transaction
                    if ((m1_awvalid && m1_awbar != BAR_NORMAL_ACCESS) ||
                        (m1_arvalid && m1_arbar != BAR_NORMAL_ACCESS)) begin
                        barrier_state[1] <= BARRIER_PENDING;
                        barrier_type[1] <= m1_awvalid ? m1_awbar : m1_arbar;
                    end else if (global_barrier_request && !master_barrier_override[1]) begin
                        barrier_state[1] <= BARRIER_DRAINING;
                        barrier_type[1] <= BAR_SYNC_BARRIER;
                    end
                end
                BARRIER_PENDING: begin
                    // Wait for barrier transaction to be accepted
                    if ((m1_awvalid && m1_awready) || (m1_arvalid && m1_arready)) begin
                        barrier_state[1] <= BARRIER_DRAINING;
                    end
                    barrier_timeout_counter[1] <= barrier_timeout_counter[1] + 1;
                    if (barrier_timeout_counter[1] >= BARRIER_TIMEOUT) begin
                        barrier_state[1] <= BARRIER_TIMEOUT_STATE;
                        barrier_timeout_flag[1] <= 1'b1;
                    end
                end
                BARRIER_DRAINING: begin
                    // Wait for all outstanding transactions to complete
                    if (barrier_type[1] == BAR_MEMORY_BARRIER) begin
                        // Memory barrier: drain writes only
                        if (outstanding_writes[1] == 16'h0) begin
                            barrier_state[1] <= BARRIER_ACTIVE;
                        end
                    end else if (barrier_type[1] == BAR_SYNC_BARRIER) begin
                        // Sync barrier: drain all transactions
                        if ((outstanding_writes[1] == 16'h0) && (outstanding_reads[1] == 16'h0)) begin
                            barrier_state[1] <= BARRIER_ACTIVE;
                        end
                    end
                    barrier_timeout_counter[1] <= barrier_timeout_counter[1] + 1;
                    if (barrier_timeout_counter[1] >= BARRIER_TIMEOUT) begin
                        barrier_state[1] <= BARRIER_TIMEOUT_STATE;
                        barrier_timeout_flag[1] <= 1'b1;
                    end
                end
                BARRIER_ACTIVE: begin
                    // Barrier is active, block new transactions
                    if (barrier_type[1] == BAR_SYNC_BARRIER && global_barrier_request) begin
                        // Wait for global barrier completion
                        if (all_masters_barrier_ready) begin
                            barrier_state[1] <= BARRIER_COMPLETE;
                        end
                    end else begin
                        // Local barrier completes immediately after draining
                        barrier_state[1] <= BARRIER_COMPLETE;
                    end
                end
                BARRIER_COMPLETE: begin
                    // Barrier complete, return to idle
                    barrier_state[1] <= BARRIER_IDLE;
                end
                BARRIER_TIMEOUT_STATE: begin
                    // Barrier timeout, force completion
                    barrier_state[1] <= BARRIER_IDLE;
                end
                default: barrier_state[1] <= BARRIER_IDLE;
            endcase
        end
    end

    // Master 2 barrier state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            barrier_state[2] <= BARRIER_IDLE;
            barrier_type[2] <= BAR_NORMAL_ACCESS;
            barrier_timeout_counter[2] <= 16'h0;
            barrier_timeout_flag[2] <= 1'b0;
        end else begin
            case (barrier_state[2])
                BARRIER_IDLE: begin
                    barrier_timeout_counter[2] <= 16'h0;
                    barrier_timeout_flag[2] <= 1'b0;
                    // Detect barrier transaction
                    if ((m2_awvalid && m2_awbar != BAR_NORMAL_ACCESS) ||
                        (m2_arvalid && m2_arbar != BAR_NORMAL_ACCESS)) begin
                        barrier_state[2] <= BARRIER_PENDING;
                        barrier_type[2] <= m2_awvalid ? m2_awbar : m2_arbar;
                    end else if (global_barrier_request && !master_barrier_override[2]) begin
                        barrier_state[2] <= BARRIER_DRAINING;
                        barrier_type[2] <= BAR_SYNC_BARRIER;
                    end
                end
                BARRIER_PENDING: begin
                    // Wait for barrier transaction to be accepted
                    if ((m2_awvalid && m2_awready) || (m2_arvalid && m2_arready)) begin
                        barrier_state[2] <= BARRIER_DRAINING;
                    end
                    barrier_timeout_counter[2] <= barrier_timeout_counter[2] + 1;
                    if (barrier_timeout_counter[2] >= BARRIER_TIMEOUT) begin
                        barrier_state[2] <= BARRIER_TIMEOUT_STATE;
                        barrier_timeout_flag[2] <= 1'b1;
                    end
                end
                BARRIER_DRAINING: begin
                    // Wait for all outstanding transactions to complete
                    if (barrier_type[2] == BAR_MEMORY_BARRIER) begin
                        // Memory barrier: drain writes only
                        if (outstanding_writes[2] == 16'h0) begin
                            barrier_state[2] <= BARRIER_ACTIVE;
                        end
                    end else if (barrier_type[2] == BAR_SYNC_BARRIER) begin
                        // Sync barrier: drain all transactions
                        if ((outstanding_writes[2] == 16'h0) && (outstanding_reads[2] == 16'h0)) begin
                            barrier_state[2] <= BARRIER_ACTIVE;
                        end
                    end
                    barrier_timeout_counter[2] <= barrier_timeout_counter[2] + 1;
                    if (barrier_timeout_counter[2] >= BARRIER_TIMEOUT) begin
                        barrier_state[2] <= BARRIER_TIMEOUT_STATE;
                        barrier_timeout_flag[2] <= 1'b1;
                    end
                end
                BARRIER_ACTIVE: begin
                    // Barrier is active, block new transactions
                    if (barrier_type[2] == BAR_SYNC_BARRIER && global_barrier_request) begin
                        // Wait for global barrier completion
                        if (all_masters_barrier_ready) begin
                            barrier_state[2] <= BARRIER_COMPLETE;
                        end
                    end else begin
                        // Local barrier completes immediately after draining
                        barrier_state[2] <= BARRIER_COMPLETE;
                    end
                end
                BARRIER_COMPLETE: begin
                    // Barrier complete, return to idle
                    barrier_state[2] <= BARRIER_IDLE;
                end
                BARRIER_TIMEOUT_STATE: begin
                    // Barrier timeout, force completion
                    barrier_state[2] <= BARRIER_IDLE;
                end
                default: barrier_state[2] <= BARRIER_IDLE;
            endcase
        end
    end

    // Master 3 barrier state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            barrier_state[3] <= BARRIER_IDLE;
            barrier_type[3] <= BAR_NORMAL_ACCESS;
            barrier_timeout_counter[3] <= 16'h0;
            barrier_timeout_flag[3] <= 1'b0;
        end else begin
            case (barrier_state[3])
                BARRIER_IDLE: begin
                    barrier_timeout_counter[3] <= 16'h0;
                    barrier_timeout_flag[3] <= 1'b0;
                    // Detect barrier transaction
                    if ((m3_awvalid && m3_awbar != BAR_NORMAL_ACCESS) ||
                        (m3_arvalid && m3_arbar != BAR_NORMAL_ACCESS)) begin
                        barrier_state[3] <= BARRIER_PENDING;
                        barrier_type[3] <= m3_awvalid ? m3_awbar : m3_arbar;
                    end else if (global_barrier_request && !master_barrier_override[3]) begin
                        barrier_state[3] <= BARRIER_DRAINING;
                        barrier_type[3] <= BAR_SYNC_BARRIER;
                    end
                end
                BARRIER_PENDING: begin
                    // Wait for barrier transaction to be accepted
                    if ((m3_awvalid && m3_awready) || (m3_arvalid && m3_arready)) begin
                        barrier_state[3] <= BARRIER_DRAINING;
                    end
                    barrier_timeout_counter[3] <= barrier_timeout_counter[3] + 1;
                    if (barrier_timeout_counter[3] >= BARRIER_TIMEOUT) begin
                        barrier_state[3] <= BARRIER_TIMEOUT_STATE;
                        barrier_timeout_flag[3] <= 1'b1;
                    end
                end
                BARRIER_DRAINING: begin
                    // Wait for all outstanding transactions to complete
                    if (barrier_type[3] == BAR_MEMORY_BARRIER) begin
                        // Memory barrier: drain writes only
                        if (outstanding_writes[3] == 16'h0) begin
                            barrier_state[3] <= BARRIER_ACTIVE;
                        end
                    end else if (barrier_type[3] == BAR_SYNC_BARRIER) begin
                        // Sync barrier: drain all transactions
                        if ((outstanding_writes[3] == 16'h0) && (outstanding_reads[3] == 16'h0)) begin
                            barrier_state[3] <= BARRIER_ACTIVE;
                        end
                    end
                    barrier_timeout_counter[3] <= barrier_timeout_counter[3] + 1;
                    if (barrier_timeout_counter[3] >= BARRIER_TIMEOUT) begin
                        barrier_state[3] <= BARRIER_TIMEOUT_STATE;
                        barrier_timeout_flag[3] <= 1'b1;
                    end
                end
                BARRIER_ACTIVE: begin
                    // Barrier is active, block new transactions
                    if (barrier_type[3] == BAR_SYNC_BARRIER && global_barrier_request) begin
                        // Wait for global barrier completion
                        if (all_masters_barrier_ready) begin
                            barrier_state[3] <= BARRIER_COMPLETE;
                        end
                    end else begin
                        // Local barrier completes immediately after draining
                        barrier_state[3] <= BARRIER_COMPLETE;
                    end
                end
                BARRIER_COMPLETE: begin
                    // Barrier complete, return to idle
                    barrier_state[3] <= BARRIER_IDLE;
                end
                BARRIER_TIMEOUT_STATE: begin
                    // Barrier timeout, force completion
                    barrier_state[3] <= BARRIER_IDLE;
                end
                default: barrier_state[3] <= BARRIER_IDLE;
            endcase
        end
    end

    // Global barrier coordination
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            global_barrier_participants <= {NUM_MASTER{1'b0}};
            global_barrier_ready <= {NUM_MASTER{1'b0}};
            global_barrier_state <= 1'b0;
        end else begin
            if (global_barrier_request && !global_barrier_state) begin
                // Start global barrier
                global_barrier_participants <= ~master_barrier_override;
                global_barrier_state <= 1'b1;
            end
            
            // Track which masters are ready
            if (global_barrier_participants[0]) begin
                global_barrier_ready[0] <= (barrier_state[0] == BARRIER_ACTIVE);
            end
            if (global_barrier_participants[1]) begin
                global_barrier_ready[1] <= (barrier_state[1] == BARRIER_ACTIVE);
            end
            if (global_barrier_participants[2]) begin
                global_barrier_ready[2] <= (barrier_state[2] == BARRIER_ACTIVE);
            end
            if (global_barrier_participants[3]) begin
                global_barrier_ready[3] <= (barrier_state[3] == BARRIER_ACTIVE);
            end
            
            // Complete global barrier when all participants ready
            if (global_barrier_state && all_masters_barrier_ready) begin
                global_barrier_state <= 1'b0;
                global_barrier_participants <= {NUM_MASTER{1'b0}};
                global_barrier_ready <= {NUM_MASTER{1'b0}};
            end
        end
    end

    // Output signal assignments
    assign barrier_timeout = barrier_timeout_flag;
    assign global_barrier_active = global_barrier_state;
    
    // Barrier status per master
    always @(*) begin
        barrier_active[0] = (barrier_state[0] == BARRIER_ACTIVE) || 
                            (barrier_state[0] == BARRIER_DRAINING);
        barrier_block[0] = barrier_active[0] && barrier_enable;
        pending_transactions[0] = outstanding_writes[0] + outstanding_reads[0];
        barrier_active[1] = (barrier_state[1] == BARRIER_ACTIVE) || 
                            (barrier_state[1] == BARRIER_DRAINING);
        barrier_block[1] = barrier_active[1] && barrier_enable;
        pending_transactions[1] = outstanding_writes[1] + outstanding_reads[1];
        barrier_active[2] = (barrier_state[2] == BARRIER_ACTIVE) || 
                            (barrier_state[2] == BARRIER_DRAINING);
        barrier_block[2] = barrier_active[2] && barrier_enable;
        pending_transactions[2] = outstanding_writes[2] + outstanding_reads[2];
        barrier_active[3] = (barrier_state[3] == BARRIER_ACTIVE) || 
                            (barrier_state[3] == BARRIER_DRAINING);
        barrier_block[3] = barrier_active[3] && barrier_enable;
        pending_transactions[3] = outstanding_writes[3] + outstanding_reads[3];
    end

endmodule

//---------------------------------------------------------------------------
// ACE-Lite Domain Manager
// Shareability domain routing and coherency scope management
//---------------------------------------------------------------------------
module ace_lite_domain_manager
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_ID   = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , NUM_DOMAINS = 4) // Support up to 4 coherency domains
(
      input  wire                       clk
    , input  wire                       rst_n
    // Master 0 domain interface
    , input  wire [WIDTH_AD-1:0]       m0_awaddr
    , input  wire [1:0]                m0_awdomain
    , input  wire [2:0]                m0_awsnoop
    , input  wire                      m0_awvalid
    , input  wire [WIDTH_AD-1:0]       m0_araddr
    , input  wire [1:0]                m0_ardomain
    , input  wire [3:0]                m0_arsnoop
    , input  wire                      m0_arvalid
    // Master 1 domain interface
    , input  wire [WIDTH_AD-1:0]       m1_awaddr
    , input  wire [1:0]                m1_awdomain
    , input  wire [2:0]                m1_awsnoop
    , input  wire                      m1_awvalid
    , input  wire [WIDTH_AD-1:0]       m1_araddr
    , input  wire [1:0]                m1_ardomain
    , input  wire [3:0]                m1_arsnoop
    , input  wire                      m1_arvalid
    // Master 2 domain interface
    , input  wire [WIDTH_AD-1:0]       m2_awaddr
    , input  wire [1:0]                m2_awdomain
    , input  wire [2:0]                m2_awsnoop
    , input  wire                      m2_awvalid
    , input  wire [WIDTH_AD-1:0]       m2_araddr
    , input  wire [1:0]                m2_ardomain
    , input  wire [3:0]                m2_arsnoop
    , input  wire                      m2_arvalid
    // Master 3 domain interface
    , input  wire [WIDTH_AD-1:0]       m3_awaddr
    , input  wire [1:0]                m3_awdomain
    , input  wire [2:0]                m3_awsnoop
    , input  wire                      m3_awvalid
    , input  wire [WIDTH_AD-1:0]       m3_araddr
    , input  wire [1:0]                m3_ardomain
    , input  wire [3:0]                m3_arsnoop
    , input  wire                      m3_arvalid
    // Domain configuration
    , input  wire [WIDTH_AD-1:0]        domain_base_addr [NUM_DOMAINS-1:0]
    , input  wire [WIDTH_AD-1:0]        domain_addr_mask [NUM_DOMAINS-1:0]
    , input  wire [NUM_DOMAINS-1:0]     domain_enable
    , input  wire [1:0]                 domain_type [NUM_DOMAINS-1:0]
    , input  wire [NUM_MASTER-1:0]      master_domain_membership [NUM_DOMAINS-1:0]
    // Domain management outputs
    , output reg  [1:0]                 resolved_awdomain [NUM_MASTER-1:0]
    , output reg  [1:0]                 resolved_ardomain [NUM_MASTER-1:0]
    , output wire [NUM_DOMAINS-1:0]     domain_active
    , output wire [NUM_MASTER-1:0]      coherency_required
    , output reg  [NUM_MASTER-1:0]      domain_violation
    , output wire [7:0]                 domain_transaction_count [NUM_DOMAINS-1:0]
);

    // Shareability domain encodings
    localparam [1:0] DOMAIN_NON_SHAREABLE = 2'b00;
    localparam [1:0] DOMAIN_INNER_SHAREABLE = 2'b01;
    localparam [1:0] DOMAIN_OUTER_SHAREABLE = 2'b10;
    localparam [1:0] DOMAIN_SYSTEM = 2'b11;

    // Snoop encodings for domain validation
    localparam [2:0] AWSNOOP_WRITE_NO_SNOOP = 3'b000;
    localparam [3:0] ARSNOOP_READ_NO_SNOOP = 4'b0000;

    // Address to domain mapping function
    function [1:0] resolve_domain;
        input [WIDTH_AD-1:0] addr;
        input [1:0] requested_domain;
        integer k;
        begin
            resolve_domain = DOMAIN_NON_SHAREABLE; // Default
            // Check if address falls in any configured domain
            for (k = 0; k < NUM_DOMAINS; k = k + 1) begin
                if (domain_enable[k] && 
                    ((addr & domain_addr_mask[k]) == domain_base_addr[k])) begin
                    // Address is in this domain
                    if (requested_domain <= domain_type[k]) begin
                        resolve_domain = requested_domain;
                    end else begin
                        resolve_domain = domain_type[k]; // Downgrade to max supported
                    end
                end
            end
        end
    endfunction

    // Master domain membership validation
    function domain_membership_valid;
        input [7:0] master_id;
        input [1:0] domain;
        integer k;
        begin
            domain_membership_valid = 1'b1; // Default allow
            if (domain != DOMAIN_NON_SHAREABLE) begin
                domain_membership_valid = 1'b0; // Require explicit membership
                for (k = 0; k < NUM_DOMAINS; k = k + 1) begin
                    if (domain_enable[k] && (domain_type[k] == domain) &&
                        master_domain_membership[k][master_id]) begin
                        domain_membership_valid = 1'b1;
                    end
                end
            end
        end
    endfunction

    // Domain transaction tracking
    reg [7:0] domain_aw_count [NUM_DOMAINS-1:0];
    reg [7:0] domain_ar_count [NUM_DOMAINS-1:0];
    // Master 0 domain resolution
    always @(*) begin
        // Write address domain resolution
        resolved_awdomain[0] = resolve_domain(m0_awaddr, m0_awdomain);
        
        // Read address domain resolution
        resolved_ardomain[0] = resolve_domain(m0_araddr, m0_ardomain);
    end

    // Master 0 domain violation detection
    always @(*) begin
        domain_violation[0] = 1'b0;
        
        // Check write transaction violations
        if (m0_awvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(0, m0_awdomain)) begin
                domain_violation[0] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m0_awdomain != DOMAIN_NON_SHAREABLE) && 
                (m0_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
                domain_violation[0] = 1'b1;
            end
        end
        
        // Check read transaction violations
        if (m0_arvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(0, m0_ardomain)) begin
                domain_violation[0] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m0_ardomain != DOMAIN_NON_SHAREABLE) && 
                (m0_arsnoop == ARSNOOP_READ_NO_SNOOP)) begin
                domain_violation[0] = 1'b1;
            end
        end
    end

    // Master 1 domain resolution
    always @(*) begin
        // Write address domain resolution
        resolved_awdomain[1] = resolve_domain(m1_awaddr, m1_awdomain);
        
        // Read address domain resolution
        resolved_ardomain[1] = resolve_domain(m1_araddr, m1_ardomain);
    end

    // Master 1 domain violation detection
    always @(*) begin
        domain_violation[1] = 1'b0;
        
        // Check write transaction violations
        if (m1_awvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(1, m1_awdomain)) begin
                domain_violation[1] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m1_awdomain != DOMAIN_NON_SHAREABLE) && 
                (m1_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
                domain_violation[1] = 1'b1;
            end
        end
        
        // Check read transaction violations
        if (m1_arvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(1, m1_ardomain)) begin
                domain_violation[1] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m1_ardomain != DOMAIN_NON_SHAREABLE) && 
                (m1_arsnoop == ARSNOOP_READ_NO_SNOOP)) begin
                domain_violation[1] = 1'b1;
            end
        end
    end

    // Master 2 domain resolution
    always @(*) begin
        // Write address domain resolution
        resolved_awdomain[2] = resolve_domain(m2_awaddr, m2_awdomain);
        
        // Read address domain resolution
        resolved_ardomain[2] = resolve_domain(m2_araddr, m2_ardomain);
    end

    // Master 2 domain violation detection
    always @(*) begin
        domain_violation[2] = 1'b0;
        
        // Check write transaction violations
        if (m2_awvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(2, m2_awdomain)) begin
                domain_violation[2] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m2_awdomain != DOMAIN_NON_SHAREABLE) && 
                (m2_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
                domain_violation[2] = 1'b1;
            end
        end
        
        // Check read transaction violations
        if (m2_arvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(2, m2_ardomain)) begin
                domain_violation[2] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m2_ardomain != DOMAIN_NON_SHAREABLE) && 
                (m2_arsnoop == ARSNOOP_READ_NO_SNOOP)) begin
                domain_violation[2] = 1'b1;
            end
        end
    end

    // Master 3 domain resolution
    always @(*) begin
        // Write address domain resolution
        resolved_awdomain[3] = resolve_domain(m3_awaddr, m3_awdomain);
        
        // Read address domain resolution
        resolved_ardomain[3] = resolve_domain(m3_araddr, m3_ardomain);
    end

    // Master 3 domain violation detection
    always @(*) begin
        domain_violation[3] = 1'b0;
        
        // Check write transaction violations
        if (m3_awvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(3, m3_awdomain)) begin
                domain_violation[3] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m3_awdomain != DOMAIN_NON_SHAREABLE) && 
                (m3_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
                domain_violation[3] = 1'b1;
            end
        end
        
        // Check read transaction violations
        if (m3_arvalid) begin
            // Check if master is allowed in requested domain
            if (!domain_membership_valid(3, m3_ardomain)) begin
                domain_violation[3] = 1'b1;
            end
            // Check snoop consistency with domain
            if ((m3_ardomain != DOMAIN_NON_SHAREABLE) && 
                (m3_arsnoop == ARSNOOP_READ_NO_SNOOP)) begin
                domain_violation[3] = 1'b1;
            end
        end
    end

    // Domain activity and transaction counting
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            domain_aw_count[0] <= 8'h0;
            domain_ar_count[0] <= 8'h0;
            domain_aw_count[1] <= 8'h0;
            domain_ar_count[1] <= 8'h0;
            domain_aw_count[2] <= 8'h0;
            domain_ar_count[2] <= 8'h0;
            domain_aw_count[3] <= 8'h0;
            domain_ar_count[3] <= 8'h0;
        end else begin
            // Master 0 transaction counting
            if (m0_awvalid && (resolved_awdomain[0] != DOMAIN_NON_SHAREABLE)) begin
                case (resolved_awdomain[0])
                    DOMAIN_INNER_SHAREABLE: domain_aw_count[1] <= domain_aw_count[1] + 1;
                    DOMAIN_OUTER_SHAREABLE: domain_aw_count[2] <= domain_aw_count[2] + 1;
                    DOMAIN_SYSTEM: domain_aw_count[3] <= domain_aw_count[3] + 1;
                    default: ; // Non-shareable, no counting
                endcase
            end
            
            if (m0_arvalid && (resolved_ardomain[0] != DOMAIN_NON_SHAREABLE)) begin
                case (resolved_ardomain[0])
                    DOMAIN_INNER_SHAREABLE: domain_ar_count[1] <= domain_ar_count[1] + 1;
                    DOMAIN_OUTER_SHAREABLE: domain_ar_count[2] <= domain_ar_count[2] + 1;
                    DOMAIN_SYSTEM: domain_ar_count[3] <= domain_ar_count[3] + 1;
                    default: ; // Non-shareable, no counting
                endcase
            end
            // Master 1 transaction counting
            if (m1_awvalid && (resolved_awdomain[1] != DOMAIN_NON_SHAREABLE)) begin
                case (resolved_awdomain[1])
                    DOMAIN_INNER_SHAREABLE: domain_aw_count[1] <= domain_aw_count[1] + 1;
                    DOMAIN_OUTER_SHAREABLE: domain_aw_count[2] <= domain_aw_count[2] + 1;
                    DOMAIN_SYSTEM: domain_aw_count[3] <= domain_aw_count[3] + 1;
                    default: ; // Non-shareable, no counting
                endcase
            end
            
            if (m1_arvalid && (resolved_ardomain[1] != DOMAIN_NON_SHAREABLE)) begin
                case (resolved_ardomain[1])
                    DOMAIN_INNER_SHAREABLE: domain_ar_count[1] <= domain_ar_count[1] + 1;
                    DOMAIN_OUTER_SHAREABLE: domain_ar_count[2] <= domain_ar_count[2] + 1;
                    DOMAIN_SYSTEM: domain_ar_count[3] <= domain_ar_count[3] + 1;
                    default: ; // Non-shareable, no counting
                endcase
            end
            // Master 2 transaction counting
            if (m2_awvalid && (resolved_awdomain[2] != DOMAIN_NON_SHAREABLE)) begin
                case (resolved_awdomain[2])
                    DOMAIN_INNER_SHAREABLE: domain_aw_count[1] <= domain_aw_count[1] + 1;
                    DOMAIN_OUTER_SHAREABLE: domain_aw_count[2] <= domain_aw_count[2] + 1;
                    DOMAIN_SYSTEM: domain_aw_count[3] <= domain_aw_count[3] + 1;
                    default: ; // Non-shareable, no counting
                endcase
            end
            
            if (m2_arvalid && (resolved_ardomain[2] != DOMAIN_NON_SHAREABLE)) begin
                case (resolved_ardomain[2])
                    DOMAIN_INNER_SHAREABLE: domain_ar_count[1] <= domain_ar_count[1] + 1;
                    DOMAIN_OUTER_SHAREABLE: domain_ar_count[2] <= domain_ar_count[2] + 1;
                    DOMAIN_SYSTEM: domain_ar_count[3] <= domain_ar_count[3] + 1;
                    default: ; // Non-shareable, no counting
                endcase
            end
            // Master 3 transaction counting
            if (m3_awvalid && (resolved_awdomain[3] != DOMAIN_NON_SHAREABLE)) begin
                case (resolved_awdomain[3])
                    DOMAIN_INNER_SHAREABLE: domain_aw_count[1] <= domain_aw_count[1] + 1;
                    DOMAIN_OUTER_SHAREABLE: domain_aw_count[2] <= domain_aw_count[2] + 1;
                    DOMAIN_SYSTEM: domain_aw_count[3] <= domain_aw_count[3] + 1;
                    default: ; // Non-shareable, no counting
                endcase
            end
            
            if (m3_arvalid && (resolved_ardomain[3] != DOMAIN_NON_SHAREABLE)) begin
                case (resolved_ardomain[3])
                    DOMAIN_INNER_SHAREABLE: domain_ar_count[1] <= domain_ar_count[1] + 1;
                    DOMAIN_OUTER_SHAREABLE: domain_ar_count[2] <= domain_ar_count[2] + 1;
                    DOMAIN_SYSTEM: domain_ar_count[3] <= domain_ar_count[3] + 1;
                    default: ; // Non-shareable, no counting
                endcase
            end
        end
    end

    // Domain activity detection
    wire [NUM_MASTER-1:0] master_aw_coherent;
    wire [NUM_MASTER-1:0] master_ar_coherent;
    assign master_aw_coherent[0] = m0_awvalid && (resolved_awdomain[0] != DOMAIN_NON_SHAREABLE);
    assign master_ar_coherent[0] = m0_arvalid && (resolved_ardomain[0] != DOMAIN_NON_SHAREABLE);
    assign master_aw_coherent[1] = m1_awvalid && (resolved_awdomain[1] != DOMAIN_NON_SHAREABLE);
    assign master_ar_coherent[1] = m1_arvalid && (resolved_ardomain[1] != DOMAIN_NON_SHAREABLE);
    assign master_aw_coherent[2] = m2_awvalid && (resolved_awdomain[2] != DOMAIN_NON_SHAREABLE);
    assign master_ar_coherent[2] = m2_arvalid && (resolved_ardomain[2] != DOMAIN_NON_SHAREABLE);
    assign master_aw_coherent[3] = m3_awvalid && (resolved_awdomain[3] != DOMAIN_NON_SHAREABLE);
    assign master_ar_coherent[3] = m3_arvalid && (resolved_ardomain[3] != DOMAIN_NON_SHAREABLE);
    assign coherency_required = master_aw_coherent | master_ar_coherent;

    // Per-domain activity detection
    wire domain_0_aw_active = (master_aw_coherent[0] && (resolved_awdomain[0] == DOMAIN_NON_SHAREABLE)) || (master_aw_coherent[1] && (resolved_awdomain[1] == DOMAIN_NON_SHAREABLE)) || (master_aw_coherent[2] && (resolved_awdomain[2] == DOMAIN_NON_SHAREABLE)) || (master_aw_coherent[3] && (resolved_awdomain[3] == DOMAIN_NON_SHAREABLE));
    wire domain_0_ar_active = (master_ar_coherent[0] && (resolved_ardomain[0] == DOMAIN_NON_SHAREABLE)) || (master_ar_coherent[1] && (resolved_ardomain[1] == DOMAIN_NON_SHAREABLE)) || (master_ar_coherent[2] && (resolved_ardomain[2] == DOMAIN_NON_SHAREABLE)) || (master_ar_coherent[3] && (resolved_ardomain[3] == DOMAIN_NON_SHAREABLE));
    assign domain_active[0] = domain_0_aw_active || domain_0_ar_active;
    assign domain_transaction_count[0] = domain_aw_count[0] + domain_ar_count[0];

    wire domain_1_aw_active = (master_aw_coherent[0] && (resolved_awdomain[0] == DOMAIN_INNER_SHAREABLE)) || (master_aw_coherent[1] && (resolved_awdomain[1] == DOMAIN_INNER_SHAREABLE)) || (master_aw_coherent[2] && (resolved_awdomain[2] == DOMAIN_INNER_SHAREABLE)) || (master_aw_coherent[3] && (resolved_awdomain[3] == DOMAIN_INNER_SHAREABLE));
    wire domain_1_ar_active = (master_ar_coherent[0] && (resolved_ardomain[0] == DOMAIN_INNER_SHAREABLE)) || (master_ar_coherent[1] && (resolved_ardomain[1] == DOMAIN_INNER_SHAREABLE)) || (master_ar_coherent[2] && (resolved_ardomain[2] == DOMAIN_INNER_SHAREABLE)) || (master_ar_coherent[3] && (resolved_ardomain[3] == DOMAIN_INNER_SHAREABLE));
    assign domain_active[1] = domain_1_aw_active || domain_1_ar_active;
    assign domain_transaction_count[1] = domain_aw_count[1] + domain_ar_count[1];

    wire domain_2_aw_active = (master_aw_coherent[0] && (resolved_awdomain[0] == DOMAIN_OUTER_SHAREABLE)) || (master_aw_coherent[1] && (resolved_awdomain[1] == DOMAIN_OUTER_SHAREABLE)) || (master_aw_coherent[2] && (resolved_awdomain[2] == DOMAIN_OUTER_SHAREABLE)) || (master_aw_coherent[3] && (resolved_awdomain[3] == DOMAIN_OUTER_SHAREABLE));
    wire domain_2_ar_active = (master_ar_coherent[0] && (resolved_ardomain[0] == DOMAIN_OUTER_SHAREABLE)) || (master_ar_coherent[1] && (resolved_ardomain[1] == DOMAIN_OUTER_SHAREABLE)) || (master_ar_coherent[2] && (resolved_ardomain[2] == DOMAIN_OUTER_SHAREABLE)) || (master_ar_coherent[3] && (resolved_ardomain[3] == DOMAIN_OUTER_SHAREABLE));
    assign domain_active[2] = domain_2_aw_active || domain_2_ar_active;
    assign domain_transaction_count[2] = domain_aw_count[2] + domain_ar_count[2];

    wire domain_3_aw_active = (master_aw_coherent[0] && (resolved_awdomain[0] == DOMAIN_SYSTEM)) || (master_aw_coherent[1] && (resolved_awdomain[1] == DOMAIN_SYSTEM)) || (master_aw_coherent[2] && (resolved_awdomain[2] == DOMAIN_SYSTEM)) || (master_aw_coherent[3] && (resolved_awdomain[3] == DOMAIN_SYSTEM));
    wire domain_3_ar_active = (master_ar_coherent[0] && (resolved_ardomain[0] == DOMAIN_SYSTEM)) || (master_ar_coherent[1] && (resolved_ardomain[1] == DOMAIN_SYSTEM)) || (master_ar_coherent[2] && (resolved_ardomain[2] == DOMAIN_SYSTEM)) || (master_ar_coherent[3] && (resolved_ardomain[3] == DOMAIN_SYSTEM));
    assign domain_active[3] = domain_3_aw_active || domain_3_ar_active;
    assign domain_transaction_count[3] = domain_aw_count[3] + domain_ar_count[3];

    // Domain hierarchy enforcement
    // Ensure proper domain nesting: System > Outer > Inner > Non-shareable
    wire domain_hierarchy_violation = 
        // Inner shareable transactions should not bypass outer shareable domain
        (domain_active[1] && domain_enable[2] && !domain_active[2]) ||
        // Outer shareable transactions should not bypass system domain  
        (domain_active[2] && domain_enable[3] && !domain_active[3]);

    // Debug and monitoring
    reg [15:0] total_coherent_transactions;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            total_coherent_transactions <= 16'h0;
        end else begin
            if (|coherency_required) begin
                total_coherent_transactions <= total_coherent_transactions + 1;
            end
        end
    end

endmodule

//---------------------------------------------------------------------------
// ACE-Lite Cache Operations
// Cache maintenance operation decode and dispatch
//---------------------------------------------------------------------------
module ace_lite_cache_ops
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_ID   = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , CACHE_OP_DEPTH = 32 // Cache operation queue depth
              // Parameterized maintenance priority width - scales with queue depth and master count
              , MAINT_PRIORITY_WIDTH = (CACHE_OP_DEPTH <= 16 && NUM_MASTER <= 8) ? 3 : (CACHE_OP_DEPTH <= 64 && NUM_MASTER <= 16) ? 4 : (NUM_MASTER <= 32) ? 5 : 6)
(
      input  wire                       clk
    , input  wire                       rst_n
    // Master 0 cache operation interface
    , input  wire [WIDTH_ID-1:0]       m0_awid
    , input  wire [WIDTH_AD-1:0]       m0_awaddr
    , input  wire [2:0]                m0_awsnoop
    , input  wire [1:0]                m0_awdomain
    , input  wire                      m0_awvalid
    , input  wire                      m0_awready
    , input  wire [WIDTH_ID-1:0]       m0_arid
    , input  wire [WIDTH_AD-1:0]       m0_araddr
    , input  wire [3:0]                m0_arsnoop
    , input  wire [1:0]                m0_ardomain
    , input  wire                      m0_arvalid
    , input  wire                      m0_arready
    // Master 1 cache operation interface
    , input  wire [WIDTH_ID-1:0]       m1_awid
    , input  wire [WIDTH_AD-1:0]       m1_awaddr
    , input  wire [2:0]                m1_awsnoop
    , input  wire [1:0]                m1_awdomain
    , input  wire                      m1_awvalid
    , input  wire                      m1_awready
    , input  wire [WIDTH_ID-1:0]       m1_arid
    , input  wire [WIDTH_AD-1:0]       m1_araddr
    , input  wire [3:0]                m1_arsnoop
    , input  wire [1:0]                m1_ardomain
    , input  wire                      m1_arvalid
    , input  wire                      m1_arready
    // Master 2 cache operation interface
    , input  wire [WIDTH_ID-1:0]       m2_awid
    , input  wire [WIDTH_AD-1:0]       m2_awaddr
    , input  wire [2:0]                m2_awsnoop
    , input  wire [1:0]                m2_awdomain
    , input  wire                      m2_awvalid
    , input  wire                      m2_awready
    , input  wire [WIDTH_ID-1:0]       m2_arid
    , input  wire [WIDTH_AD-1:0]       m2_araddr
    , input  wire [3:0]                m2_arsnoop
    , input  wire [1:0]                m2_ardomain
    , input  wire                      m2_arvalid
    , input  wire                      m2_arready
    // Master 3 cache operation interface
    , input  wire [WIDTH_ID-1:0]       m3_awid
    , input  wire [WIDTH_AD-1:0]       m3_awaddr
    , input  wire [2:0]                m3_awsnoop
    , input  wire [1:0]                m3_awdomain
    , input  wire                      m3_awvalid
    , input  wire                      m3_awready
    , input  wire [WIDTH_ID-1:0]       m3_arid
    , input  wire [WIDTH_AD-1:0]       m3_araddr
    , input  wire [3:0]                m3_arsnoop
    , input  wire [1:0]                m3_ardomain
    , input  wire                      m3_arvalid
    , input  wire                      m3_arready
    // Enhanced Cache Operation Control
    , input  wire                       cache_ops_enable
    , input  wire                       cache_maint_bypass
    , input  wire [WIDTH_AD-1:0]        cache_base_addr
    , input  wire [WIDTH_AD-1:0]        cache_size
    , input  wire [7:0]                 cache_line_size
    // Advanced Cache Maintenance Control (Phase 4)
    , input  wire                       maint_timeout_enable
    , input  wire [15:0]                maint_timeout_cycles
    , input  wire                       maint_completion_tracking
    , input  wire                       maint_conflict_resolution
    , input  wire [MAINT_PRIORITY_WIDTH-1:0] maint_priority_level
    , input  wire                       maint_queuing_enable
    , input  wire                       maint_scheduling_enable
    // Enhanced Cache Operation Outputs
    , output reg  [NUM_MASTER-1:0]       cache_op_active
    , output reg  [NUM_MASTER-1:0]       cache_maint_required
    , output wire [3:0]                  cache_op_type [NUM_MASTER-1:0]
    , output wire [WIDTH_AD-1:0]         cache_op_addr [NUM_MASTER-1:0]
    , output wire [7:0]                  cache_op_pending_count
    , output reg  [7:0]                  cache_clean_count
    , output reg  [7:0]                  cache_invalidate_count
    // Advanced Maintenance Operation Tracking (Phase 4)
    , output reg  [7:0]                  maint_completion_count
    , output reg  [7:0]                  maint_timeout_count
    , output reg  [7:0]                  maint_error_count
    , output reg  [NUM_MASTER-1:0]       maint_conflict_detected
    , output reg  [NUM_MASTER-1:0]       maint_operation_complete
    , output reg  [MAINT_PRIORITY_WIDTH-1:0] maint_current_priority
    , output wire [7:0]                  maint_queue_depth
);

    // Enhanced Cache Maintenance Operation Type Encodings
    localparam [3:0] CACHE_OP_NONE = 4'h0;
    localparam [3:0] CACHE_OP_CLEAN = 4'h1;
    localparam [3:0] CACHE_OP_INVALIDATE = 4'h2;
    localparam [3:0] CACHE_OP_CLEAN_INVALIDATE = 4'h3;
    localparam [3:0] CACHE_OP_MAKE_UNIQUE = 4'h4;
    localparam [3:0] CACHE_OP_EVICT = 4'h5;
    localparam [3:0] CACHE_OP_WRITEBACK = 4'h6;
    localparam [3:0] CACHE_OP_ZERO = 4'h7;
    // Advanced Cache Maintenance Types (Phase 4)
    localparam [3:0] MAINT_CLEAN_POC = 4'h8;           // Clean to Point of Coherency
    localparam [3:0] MAINT_CLEAN_POU = 4'h9;           // Clean to Point of Unification
    localparam [3:0] MAINT_CLEAN_INV_POC = 4'hA;       // Clean and Invalidate to PoC
    localparam [3:0] MAINT_INV_POC = 4'hB;             // Invalidate to PoC
    localparam [3:0] MAINT_FLUSH_POC = 4'hC;           // Flush to PoC
    localparam [3:0] MAINT_FLUSH_POU = 4'hD;           // Flush to PoU
    localparam [3:0] MAINT_ZERO_POC = 4'hE;            // Zero to PoC
    localparam [3:0] MAINT_PREFETCH = 4'hF;            // Prefetch operation

    // Write snoop encodings (cache maintenance)
    localparam [2:0] AWSNOOP_WRITE_NO_SNOOP = 3'b000;
    localparam [2:0] AWSNOOP_WRITE_LINE_UNIQUE = 3'b001;
    localparam [2:0] AWSNOOP_WRITE_CLEAN = 3'b010;
    localparam [2:0] AWSNOOP_WRITE_BACK = 3'b011;
    localparam [2:0] AWSNOOP_EVICT = 3'b100;
    localparam [2:0] AWSNOOP_WRITE_EVICT = 3'b101;
    localparam [2:0] AWSNOOP_WRITE_ZERO = 3'b110;

    // Read snoop encodings (cache maintenance)
    localparam [3:0] ARSNOOP_READ_NO_SNOOP = 4'b0000;
    localparam [3:0] ARSNOOP_READ_ONCE = 4'b0001;
    localparam [3:0] ARSNOOP_READ_SHARED = 4'b0001;
    localparam [3:0] ARSNOOP_READ_CLEAN = 4'b0010;
    localparam [3:0] ARSNOOP_READ_NOT_SHARED_DIRTY = 4'b0011;
    localparam [3:0] ARSNOOP_READ_UNIQUE = 4'b0111;
    localparam [3:0] ARSNOOP_CLEAN_SHARED = 4'b1000;
    localparam [3:0] ARSNOOP_CLEAN_INVALID = 4'b1001;
    localparam [3:0] ARSNOOP_MAKE_INVALID = 4'b1101;
    localparam [3:0] ARSNOOP_CLEAN_UNIQUE = 4'b1011;

    // Enhanced Cache Operation Queue
    reg [WIDTH_ID-1:0] cache_op_queue_id [0:CACHE_OP_DEPTH-1];
    reg [WIDTH_AD-1:0] cache_op_queue_addr [0:CACHE_OP_DEPTH-1];
    reg [3:0] cache_op_queue_type [0:CACHE_OP_DEPTH-1];
    reg [7:0] cache_op_queue_master [0:CACHE_OP_DEPTH-1];
    reg [CACHE_OP_DEPTH-1:0] cache_op_queue_valid;
    reg [$clog2(CACHE_OP_DEPTH)-1:0] cache_op_wr_ptr;
    reg [$clog2(CACHE_OP_DEPTH)-1:0] cache_op_rd_ptr;
    // Advanced Maintenance Operation Tracking (Phase 4)
    reg [15:0] cache_op_queue_timestamp [0:CACHE_OP_DEPTH-1]; // Operation start time
    reg [3:0] cache_op_queue_priority [0:CACHE_OP_DEPTH-1];   // Operation priority
    reg [CACHE_OP_DEPTH-1:0] cache_op_queue_complete;        // Completion status
    reg [CACHE_OP_DEPTH-1:0] cache_op_queue_timeout;         // Timeout status
    reg [CACHE_OP_DEPTH-1:0] cache_op_queue_conflict;        // Conflict detection
    reg [7:0] cache_op_queue_retry_count [0:CACHE_OP_DEPTH-1]; // Retry attempts

    // Enhanced Performance Monitoring
    reg [15:0] total_cache_ops;
    reg [7:0] cache_writeback_count;
    reg [15:0] global_timestamp;           // Global time counter
    reg [7:0] maint_poc_count;             // Point of Coherency operations
    reg [7:0] maint_pou_count;             // Point of Unification operations
    reg [7:0] maint_flush_count;           // Flush operations
    reg [7:0] maint_prefetch_count;        // Prefetch operations
    reg [15:0] maint_avg_completion_time;  // Average completion time
    reg [7:0] maint_max_queue_depth;       // Maximum queue depth reached

    // Cache operation decode functions
    function [3:0] decode_write_cache_op;
        input [2:0] awsnoop;
        begin
            case (awsnoop)
                AWSNOOP_WRITE_CLEAN:     decode_write_cache_op = CACHE_OP_CLEAN;
                AWSNOOP_WRITE_LINE_UNIQUE: decode_write_cache_op = CACHE_OP_MAKE_UNIQUE;
                AWSNOOP_WRITE_BACK:      decode_write_cache_op = CACHE_OP_WRITEBACK;
                AWSNOOP_EVICT:           decode_write_cache_op = CACHE_OP_EVICT;
                AWSNOOP_WRITE_EVICT:     decode_write_cache_op = CACHE_OP_CLEAN_INVALIDATE;
                AWSNOOP_WRITE_ZERO:      decode_write_cache_op = CACHE_OP_ZERO;
                default:                 decode_write_cache_op = CACHE_OP_NONE;
            endcase
        end
    endfunction

    function [3:0] decode_read_cache_op;
        input [3:0] arsnoop;
        begin
            case (arsnoop)
                ARSNOOP_READ_CLEAN:           decode_read_cache_op = CACHE_OP_CLEAN;
                ARSNOOP_CLEAN_SHARED:         decode_read_cache_op = MAINT_CLEAN_POC;  // Enhanced PoC
                ARSNOOP_CLEAN_INVALID:        decode_read_cache_op = MAINT_CLEAN_INV_POC; // Enhanced PoC
                ARSNOOP_CLEAN_UNIQUE:         decode_read_cache_op = MAINT_CLEAN_POU;  // Enhanced PoU
                ARSNOOP_MAKE_INVALID:         decode_read_cache_op = MAINT_INV_POC;    // Enhanced PoC
                ARSNOOP_READ_UNIQUE:          decode_read_cache_op = CACHE_OP_MAKE_UNIQUE;
                default:                      decode_read_cache_op = CACHE_OP_NONE;
            endcase
        end
    endfunction

    // Advanced Maintenance Operation Decoding (Phase 4)
    function [3:0] decode_advanced_maint_op;
        input [3:0] cache_op_type;
        input [1:0] domain;
        input cache_maint_enable;
        begin
            if (!cache_maint_enable) begin
                decode_advanced_maint_op = cache_op_type;
            end else begin
                case ({domain, cache_op_type[1:0]})
                    {2'b00, 2'b01}: decode_advanced_maint_op = MAINT_CLEAN_POC;     // Inner Shareable, Clean
                    {2'b01, 2'b01}: decode_advanced_maint_op = MAINT_CLEAN_POU;     // Outer Shareable, Clean
                    {2'b10, 2'b01}: decode_advanced_maint_op = MAINT_FLUSH_POC;     // System, Clean (Flush)
                    {2'b00, 2'b10}: decode_advanced_maint_op = MAINT_INV_POC;       // Inner Shareable, Invalidate
                    {2'b01, 2'b10}: decode_advanced_maint_op = MAINT_INV_POC;       // Outer Shareable, Invalidate
                    {2'b10, 2'b10}: decode_advanced_maint_op = MAINT_FLUSH_POU;     // System, Invalidate (Flush)
                    {2'b00, 2'b11}: decode_advanced_maint_op = MAINT_CLEAN_INV_POC; // Inner Shareable, Clean+Inv
                    {2'b01, 2'b11}: decode_advanced_maint_op = MAINT_CLEAN_INV_POC; // Outer Shareable, Clean+Inv
                    {2'b10, 2'b11}: decode_advanced_maint_op = MAINT_FLUSH_POC;     // System, Clean+Inv (Flush)
                    default:        decode_advanced_maint_op = cache_op_type;
                endcase
            end
        end
    endfunction

    // Master 0 cache operation detection
    wire [3:0] m0_aw_cache_op = decode_write_cache_op(m0_awsnoop);
    wire [3:0] m0_ar_cache_op = decode_read_cache_op(m0_arsnoop);
    wire m0_aw_is_cache_op = (m0_aw_cache_op != CACHE_OP_NONE) && m0_awvalid;
    wire m0_ar_is_cache_op = (m0_ar_cache_op != CACHE_OP_NONE) && m0_arvalid;
    assign cache_op_type[0] = m0_aw_is_cache_op ? m0_aw_cache_op : m0_ar_cache_op;
    assign cache_op_addr[0] = m0_aw_is_cache_op ? m0_awaddr : m0_araddr;

    // Master 1 cache operation detection
    wire [3:0] m1_aw_cache_op = decode_write_cache_op(m1_awsnoop);
    wire [3:0] m1_ar_cache_op = decode_read_cache_op(m1_arsnoop);
    wire m1_aw_is_cache_op = (m1_aw_cache_op != CACHE_OP_NONE) && m1_awvalid;
    wire m1_ar_is_cache_op = (m1_ar_cache_op != CACHE_OP_NONE) && m1_arvalid;
    assign cache_op_type[1] = m1_aw_is_cache_op ? m1_aw_cache_op : m1_ar_cache_op;
    assign cache_op_addr[1] = m1_aw_is_cache_op ? m1_awaddr : m1_araddr;

    // Master 2 cache operation detection
    wire [3:0] m2_aw_cache_op = decode_write_cache_op(m2_awsnoop);
    wire [3:0] m2_ar_cache_op = decode_read_cache_op(m2_arsnoop);
    wire m2_aw_is_cache_op = (m2_aw_cache_op != CACHE_OP_NONE) && m2_awvalid;
    wire m2_ar_is_cache_op = (m2_ar_cache_op != CACHE_OP_NONE) && m2_arvalid;
    assign cache_op_type[2] = m2_aw_is_cache_op ? m2_aw_cache_op : m2_ar_cache_op;
    assign cache_op_addr[2] = m2_aw_is_cache_op ? m2_awaddr : m2_araddr;

    // Master 3 cache operation detection
    wire [3:0] m3_aw_cache_op = decode_write_cache_op(m3_awsnoop);
    wire [3:0] m3_ar_cache_op = decode_read_cache_op(m3_arsnoop);
    wire m3_aw_is_cache_op = (m3_aw_cache_op != CACHE_OP_NONE) && m3_awvalid;
    wire m3_ar_is_cache_op = (m3_ar_cache_op != CACHE_OP_NONE) && m3_arvalid;
    assign cache_op_type[3] = m3_aw_is_cache_op ? m3_aw_cache_op : m3_ar_cache_op;
    assign cache_op_addr[3] = m3_aw_is_cache_op ? m3_awaddr : m3_araddr;

    // Enhanced Cache Operation Queue Management
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cache_op_queue_valid <= {CACHE_OP_DEPTH{1'b0}};
            cache_op_wr_ptr <= 0;
            cache_op_rd_ptr <= 0;
            total_cache_ops <= 16'h0;
            cache_clean_count <= 8'h0;
            cache_invalidate_count <= 8'h0;
            cache_writeback_count <= 8'h0;
            // Enhanced Phase 4 counters reset
            global_timestamp <= 16'h0;
            maint_poc_count <= 8'h0;
            maint_pou_count <= 8'h0;
            maint_flush_count <= 8'h0;
            maint_prefetch_count <= 8'h0;
            maint_completion_count <= 8'h0;
            maint_timeout_count <= 8'h0;
            maint_error_count <= 8'h0;
            maint_avg_completion_time <= 16'h0;
            maint_max_queue_depth <= 8'h0;
            maint_current_priority <= 4'h0;
            // Reset advanced tracking arrays
            cache_op_queue_complete <= {CACHE_OP_DEPTH{1'b0}};
            cache_op_queue_timeout <= {CACHE_OP_DEPTH{1'b0}};
            cache_op_queue_conflict <= {CACHE_OP_DEPTH{1'b0}};
            cache_op_active[0] <= 1'b0;
            cache_maint_required[0] <= 1'b0;
            maint_conflict_detected[0] <= 1'b0;
            maint_operation_complete[0] <= 1'b0;
            cache_op_active[1] <= 1'b0;
            cache_maint_required[1] <= 1'b0;
            maint_conflict_detected[1] <= 1'b0;
            maint_operation_complete[1] <= 1'b0;
            cache_op_active[2] <= 1'b0;
            cache_maint_required[2] <= 1'b0;
            maint_conflict_detected[2] <= 1'b0;
            maint_operation_complete[2] <= 1'b0;
            cache_op_active[3] <= 1'b0;
            cache_maint_required[3] <= 1'b0;
            maint_conflict_detected[3] <= 1'b0;
            maint_operation_complete[3] <= 1'b0;
        end else if (cache_ops_enable) begin
            // Global timestamp increment
            global_timestamp <= global_timestamp + 1;
            // Master 0 cache operation enqueue
            if ((m0_aw_is_cache_op && m0_awready) || (m0_ar_is_cache_op && m0_arready)) begin
                if (!cache_op_queue_valid[cache_op_wr_ptr]) begin
                    // Enhanced Phase 4 operation queueing
                    cache_op_queue_id[cache_op_wr_ptr] <= m0_aw_is_cache_op ? m0_awid : m0_arid;
                    cache_op_queue_addr[cache_op_wr_ptr] <= cache_op_addr[0];
                    // Use advanced maintenance operation decoding
                    cache_op_queue_type[cache_op_wr_ptr] <= decode_advanced_maint_op(
                        cache_op_type[0], 
                        m0_aw_is_cache_op ? m0_awdomain : m0_ardomain,
                        maint_completion_tracking);
                    cache_op_queue_master[cache_op_wr_ptr] <= 0;
                    cache_op_queue_valid[cache_op_wr_ptr] <= 1'b1;
                    // Enhanced Phase 4 tracking initialization
                    cache_op_queue_timestamp[cache_op_wr_ptr] <= global_timestamp;
                    cache_op_queue_priority[cache_op_wr_ptr] <= maint_priority_level;
                    cache_op_queue_complete[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_timeout[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_conflict[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_retry_count[cache_op_wr_ptr] <= 8'h0;
                    cache_op_wr_ptr <= (cache_op_wr_ptr + 1) % CACHE_OP_DEPTH;
                    total_cache_ops <= total_cache_ops + 1;
                    
                    // Enhanced operation type counters (Phase 4)
                    case (cache_op_queue_type[cache_op_wr_ptr])
                        CACHE_OP_CLEAN, CACHE_OP_CLEAN_INVALIDATE: 
                            cache_clean_count <= cache_clean_count + 1;
                        CACHE_OP_INVALIDATE, CACHE_OP_MAKE_UNIQUE: 
                            cache_invalidate_count <= cache_invalidate_count + 1;
                        CACHE_OP_WRITEBACK, CACHE_OP_EVICT: 
                            cache_writeback_count <= cache_writeback_count + 1;
                        // Advanced Phase 4 maintenance operations
                        MAINT_CLEAN_POC, MAINT_CLEAN_INV_POC, MAINT_INV_POC:
                            maint_poc_count <= maint_poc_count + 1;
                        MAINT_CLEAN_POU, MAINT_FLUSH_POU:
                            maint_pou_count <= maint_pou_count + 1;
                        MAINT_FLUSH_POC:
                            maint_flush_count <= maint_flush_count + 1;
                        MAINT_PREFETCH:
                            maint_prefetch_count <= maint_prefetch_count + 1;
                        default: ; // No counting for other ops
                    endcase
                end
            end
            
            // Master 0 cache operation status
            cache_op_active[0] <= m0_aw_is_cache_op || m0_ar_is_cache_op;
            cache_maint_required[0] <= cache_op_active[0] && !cache_maint_bypass;
            // Master 1 cache operation enqueue
            if ((m1_aw_is_cache_op && m1_awready) || (m1_ar_is_cache_op && m1_arready)) begin
                if (!cache_op_queue_valid[cache_op_wr_ptr]) begin
                    // Enhanced Phase 4 operation queueing
                    cache_op_queue_id[cache_op_wr_ptr] <= m1_aw_is_cache_op ? m1_awid : m1_arid;
                    cache_op_queue_addr[cache_op_wr_ptr] <= cache_op_addr[1];
                    // Use advanced maintenance operation decoding
                    cache_op_queue_type[cache_op_wr_ptr] <= decode_advanced_maint_op(
                        cache_op_type[1], 
                        m1_aw_is_cache_op ? m1_awdomain : m1_ardomain,
                        maint_completion_tracking);
                    cache_op_queue_master[cache_op_wr_ptr] <= 1;
                    cache_op_queue_valid[cache_op_wr_ptr] <= 1'b1;
                    // Enhanced Phase 4 tracking initialization
                    cache_op_queue_timestamp[cache_op_wr_ptr] <= global_timestamp;
                    cache_op_queue_priority[cache_op_wr_ptr] <= maint_priority_level;
                    cache_op_queue_complete[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_timeout[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_conflict[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_retry_count[cache_op_wr_ptr] <= 8'h0;
                    cache_op_wr_ptr <= (cache_op_wr_ptr + 1) % CACHE_OP_DEPTH;
                    total_cache_ops <= total_cache_ops + 1;
                    
                    // Enhanced operation type counters (Phase 4)
                    case (cache_op_queue_type[cache_op_wr_ptr])
                        CACHE_OP_CLEAN, CACHE_OP_CLEAN_INVALIDATE: 
                            cache_clean_count <= cache_clean_count + 1;
                        CACHE_OP_INVALIDATE, CACHE_OP_MAKE_UNIQUE: 
                            cache_invalidate_count <= cache_invalidate_count + 1;
                        CACHE_OP_WRITEBACK, CACHE_OP_EVICT: 
                            cache_writeback_count <= cache_writeback_count + 1;
                        // Advanced Phase 4 maintenance operations
                        MAINT_CLEAN_POC, MAINT_CLEAN_INV_POC, MAINT_INV_POC:
                            maint_poc_count <= maint_poc_count + 1;
                        MAINT_CLEAN_POU, MAINT_FLUSH_POU:
                            maint_pou_count <= maint_pou_count + 1;
                        MAINT_FLUSH_POC:
                            maint_flush_count <= maint_flush_count + 1;
                        MAINT_PREFETCH:
                            maint_prefetch_count <= maint_prefetch_count + 1;
                        default: ; // No counting for other ops
                    endcase
                end
            end
            
            // Master 1 cache operation status
            cache_op_active[1] <= m1_aw_is_cache_op || m1_ar_is_cache_op;
            cache_maint_required[1] <= cache_op_active[1] && !cache_maint_bypass;
            // Master 2 cache operation enqueue
            if ((m2_aw_is_cache_op && m2_awready) || (m2_ar_is_cache_op && m2_arready)) begin
                if (!cache_op_queue_valid[cache_op_wr_ptr]) begin
                    // Enhanced Phase 4 operation queueing
                    cache_op_queue_id[cache_op_wr_ptr] <= m2_aw_is_cache_op ? m2_awid : m2_arid;
                    cache_op_queue_addr[cache_op_wr_ptr] <= cache_op_addr[2];
                    // Use advanced maintenance operation decoding
                    cache_op_queue_type[cache_op_wr_ptr] <= decode_advanced_maint_op(
                        cache_op_type[2], 
                        m2_aw_is_cache_op ? m2_awdomain : m2_ardomain,
                        maint_completion_tracking);
                    cache_op_queue_master[cache_op_wr_ptr] <= 2;
                    cache_op_queue_valid[cache_op_wr_ptr] <= 1'b1;
                    // Enhanced Phase 4 tracking initialization
                    cache_op_queue_timestamp[cache_op_wr_ptr] <= global_timestamp;
                    cache_op_queue_priority[cache_op_wr_ptr] <= maint_priority_level;
                    cache_op_queue_complete[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_timeout[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_conflict[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_retry_count[cache_op_wr_ptr] <= 8'h0;
                    cache_op_wr_ptr <= (cache_op_wr_ptr + 1) % CACHE_OP_DEPTH;
                    total_cache_ops <= total_cache_ops + 1;
                    
                    // Enhanced operation type counters (Phase 4)
                    case (cache_op_queue_type[cache_op_wr_ptr])
                        CACHE_OP_CLEAN, CACHE_OP_CLEAN_INVALIDATE: 
                            cache_clean_count <= cache_clean_count + 1;
                        CACHE_OP_INVALIDATE, CACHE_OP_MAKE_UNIQUE: 
                            cache_invalidate_count <= cache_invalidate_count + 1;
                        CACHE_OP_WRITEBACK, CACHE_OP_EVICT: 
                            cache_writeback_count <= cache_writeback_count + 1;
                        // Advanced Phase 4 maintenance operations
                        MAINT_CLEAN_POC, MAINT_CLEAN_INV_POC, MAINT_INV_POC:
                            maint_poc_count <= maint_poc_count + 1;
                        MAINT_CLEAN_POU, MAINT_FLUSH_POU:
                            maint_pou_count <= maint_pou_count + 1;
                        MAINT_FLUSH_POC:
                            maint_flush_count <= maint_flush_count + 1;
                        MAINT_PREFETCH:
                            maint_prefetch_count <= maint_prefetch_count + 1;
                        default: ; // No counting for other ops
                    endcase
                end
            end
            
            // Master 2 cache operation status
            cache_op_active[2] <= m2_aw_is_cache_op || m2_ar_is_cache_op;
            cache_maint_required[2] <= cache_op_active[2] && !cache_maint_bypass;
            // Master 3 cache operation enqueue
            if ((m3_aw_is_cache_op && m3_awready) || (m3_ar_is_cache_op && m3_arready)) begin
                if (!cache_op_queue_valid[cache_op_wr_ptr]) begin
                    // Enhanced Phase 4 operation queueing
                    cache_op_queue_id[cache_op_wr_ptr] <= m3_aw_is_cache_op ? m3_awid : m3_arid;
                    cache_op_queue_addr[cache_op_wr_ptr] <= cache_op_addr[3];
                    // Use advanced maintenance operation decoding
                    cache_op_queue_type[cache_op_wr_ptr] <= decode_advanced_maint_op(
                        cache_op_type[3], 
                        m3_aw_is_cache_op ? m3_awdomain : m3_ardomain,
                        maint_completion_tracking);
                    cache_op_queue_master[cache_op_wr_ptr] <= 3;
                    cache_op_queue_valid[cache_op_wr_ptr] <= 1'b1;
                    // Enhanced Phase 4 tracking initialization
                    cache_op_queue_timestamp[cache_op_wr_ptr] <= global_timestamp;
                    cache_op_queue_priority[cache_op_wr_ptr] <= maint_priority_level;
                    cache_op_queue_complete[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_timeout[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_conflict[cache_op_wr_ptr] <= 1'b0;
                    cache_op_queue_retry_count[cache_op_wr_ptr] <= 8'h0;
                    cache_op_wr_ptr <= (cache_op_wr_ptr + 1) % CACHE_OP_DEPTH;
                    total_cache_ops <= total_cache_ops + 1;
                    
                    // Enhanced operation type counters (Phase 4)
                    case (cache_op_queue_type[cache_op_wr_ptr])
                        CACHE_OP_CLEAN, CACHE_OP_CLEAN_INVALIDATE: 
                            cache_clean_count <= cache_clean_count + 1;
                        CACHE_OP_INVALIDATE, CACHE_OP_MAKE_UNIQUE: 
                            cache_invalidate_count <= cache_invalidate_count + 1;
                        CACHE_OP_WRITEBACK, CACHE_OP_EVICT: 
                            cache_writeback_count <= cache_writeback_count + 1;
                        // Advanced Phase 4 maintenance operations
                        MAINT_CLEAN_POC, MAINT_CLEAN_INV_POC, MAINT_INV_POC:
                            maint_poc_count <= maint_poc_count + 1;
                        MAINT_CLEAN_POU, MAINT_FLUSH_POU:
                            maint_pou_count <= maint_pou_count + 1;
                        MAINT_FLUSH_POC:
                            maint_flush_count <= maint_flush_count + 1;
                        MAINT_PREFETCH:
                            maint_prefetch_count <= maint_prefetch_count + 1;
                        default: ; // No counting for other ops
                    endcase
                end
            end
            
            // Master 3 cache operation status
            cache_op_active[3] <= m3_aw_is_cache_op || m3_ar_is_cache_op;
            cache_maint_required[3] <= cache_op_active[3] && !cache_maint_bypass;
            // Advanced Cache Maintenance Operation Processing (Phase 4)
            
            // Timeout detection and handling
            if (maint_timeout_enable) begin
                for (integer j = 0; j < CACHE_OP_DEPTH; j = j + 1) begin
                    if (cache_op_queue_valid[j] && !cache_op_queue_complete[j]) begin
                        // Check for timeout
                        if ((global_timestamp - cache_op_queue_timestamp[j]) >= maint_timeout_cycles) begin
                            cache_op_queue_timeout[j] <= 1'b1;
                            maint_timeout_count <= maint_timeout_count + 1;
                            maint_error_count <= maint_error_count + 1;
                            // Increment retry count
                            if (cache_op_queue_retry_count[j] < 8'hFF) begin
                                cache_op_queue_retry_count[j] <= cache_op_queue_retry_count[j] + 1;
                            end
                        end
                    end
                end
            end
            
            // Conflict resolution logic
            if (maint_conflict_resolution) begin
                for (integer j = 0; j < CACHE_OP_DEPTH; j = j + 1) begin
                    if (cache_op_queue_valid[j] && !cache_op_queue_complete[j]) begin
                        for (integer k = j + 1; k < CACHE_OP_DEPTH; k = k + 1) begin
                            if (cache_op_queue_valid[k] && !cache_op_queue_complete[k]) begin
                                // Check for address conflicts on cache line boundary
                                if (cache_op_conflict(cache_op_queue_addr[j], cache_op_queue_addr[k])) begin
                                    cache_op_queue_conflict[j] <= 1'b1;
                                    cache_op_queue_conflict[k] <= 1'b1;
                                    maint_conflict_detected[cache_op_queue_master[j]] <= 1'b1;
                                    maint_conflict_detected[cache_op_queue_master[k]] <= 1'b1;
                                end
                            end
                        end
                    end
                end
            end
            
            // Priority-based operation scheduling
            if (maint_scheduling_enable) begin
                maint_current_priority <= maint_priority_level;
                // Process highest priority operations first
                for (integer j = 0; j < CACHE_OP_DEPTH; j = j + 1) begin
                    if (cache_op_queue_valid[j] && !cache_op_queue_complete[j] && 
                        !cache_op_queue_timeout[j] && !cache_op_queue_conflict[j]) begin
                        if (cache_op_queue_priority[j] >= maint_current_priority) begin
                            // Mark as processing (simplified - real implementation would interface with cache)
                            // This is where actual cache maintenance would occur
                        end
                    end
                end
            end
            
            // Enhanced completion tracking and dequeue
            if (cache_op_queue_valid[cache_op_rd_ptr]) begin
                // Simulate completion for operations older than completion threshold
                if ((global_timestamp - cache_op_queue_timestamp[cache_op_rd_ptr]) >= 16) begin
                    cache_op_queue_complete[cache_op_rd_ptr] <= 1'b1;
                    maint_completion_count <= maint_completion_count + 1;
                    maint_operation_complete[cache_op_queue_master[cache_op_rd_ptr]] <= 1'b1;
                    
                    // Update average completion time
                    maint_avg_completion_time <= (maint_avg_completion_time + 
                        (global_timestamp - cache_op_queue_timestamp[cache_op_rd_ptr])) >> 1;
                    
                    // Dequeue completed operation
                    cache_op_queue_valid[cache_op_rd_ptr] <= 1'b0;
                    cache_op_queue_complete[cache_op_rd_ptr] <= 1'b0;
                    cache_op_queue_timeout[cache_op_rd_ptr] <= 1'b0;
                    cache_op_queue_conflict[cache_op_rd_ptr] <= 1'b0;
                    cache_op_rd_ptr <= (cache_op_rd_ptr + 1) % CACHE_OP_DEPTH;
                end
            end
        end
    end

    // Cache line address alignment
    function [WIDTH_AD-1:0] align_to_cache_line;
        input [WIDTH_AD-1:0] addr;
        begin
            align_to_cache_line = {addr[WIDTH_AD-1:$clog2(64)], {$clog2(64){1'b0}}}; // Assume 64-byte cache lines
        end
    endfunction

    // Cache operation conflict detection
    function cache_op_conflict;
        input [WIDTH_AD-1:0] addr1;
        input [WIDTH_AD-1:0] addr2;
        begin
            // Check if two addresses conflict on cache line boundary
            cache_op_conflict = (align_to_cache_line(addr1) == align_to_cache_line(addr2));
        end
    endfunction

    // Enhanced Cache Operation Pending Count
    reg [7:0] pending_count;
    reg [7:0] maint_queue_depth_reg;
    always @(*) begin
        pending_count = 8'h0;
        maint_queue_depth_reg = 8'h0;
        for (integer j = 0; j < CACHE_OP_DEPTH; j = j + 1) begin
            if (cache_op_queue_valid[j]) begin
                pending_count = pending_count + 1;
                if (!cache_op_queue_complete[j]) begin
                    maint_queue_depth_reg = maint_queue_depth_reg + 1;
                end
            end
        end
    end
    assign cache_op_pending_count = pending_count;
    assign maint_queue_depth = maint_queue_depth_reg;

    // Cache operation address validation
    function cache_addr_valid;
        input [WIDTH_AD-1:0] addr;
        begin
            cache_addr_valid = (addr >= cache_base_addr) && 
                              (addr < (cache_base_addr + cache_size));
        end
    endfunction

    // Enhanced Cache Operation Statistics and Advanced Monitoring
    reg [15:0] cache_op_cycles;
    reg [7:0] max_pending_ops;
    reg [15:0] maint_total_processing_time;   // Total processing time for all operations
    reg [7:0] maint_successful_completions;   // Successfully completed operations
    reg [7:0] maint_failed_operations;        // Failed/timed-out operations
    reg [7:0] maint_conflicts_resolved;       // Number of conflicts resolved
    reg [7:0] maint_priority_escalations;     // Priority escalation events
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cache_op_cycles <= 16'h0;
            max_pending_ops <= 8'h0;
            maint_total_processing_time <= 16'h0;
            maint_successful_completions <= 8'h0;
            maint_failed_operations <= 8'h0;
            maint_conflicts_resolved <= 8'h0;
            maint_priority_escalations <= 8'h0;
        end else begin
            if (|cache_op_active) begin
                cache_op_cycles <= cache_op_cycles + 1;
            end
            
            // Track maximum queue depth
            if (pending_count > max_pending_ops) begin
                max_pending_ops <= pending_count;
            end
            if (maint_queue_depth_reg > maint_max_queue_depth) begin
                maint_max_queue_depth <= maint_queue_depth_reg;
            end
            
            // Advanced Phase 4 statistics tracking
            for (integer j = 0; j < CACHE_OP_DEPTH; j = j + 1) begin
                if (cache_op_queue_valid[j]) begin
                    // Track total processing time
                    if (!cache_op_queue_complete[j] && !cache_op_queue_timeout[j]) begin
                        if (maint_total_processing_time < 16'hFFFF) begin
                            maint_total_processing_time <= maint_total_processing_time + 1;
                        end
                    end
                    
                    // Track successful completions
                    if (cache_op_queue_complete[j] && !cache_op_queue_timeout[j]) begin
                        maint_successful_completions <= maint_successful_completions + 1;
                    end
                    
                    // Track failed operations
                    if (cache_op_queue_timeout[j] || (cache_op_queue_retry_count[j] >= 8'h03)) begin
                        maint_failed_operations <= maint_failed_operations + 1;
                    end
                    
                    // Track conflict resolutions
                    if (cache_op_queue_conflict[j] && cache_op_queue_complete[j]) begin
                        maint_conflicts_resolved <= maint_conflicts_resolved + 1;
                    end
                    
                    // Track priority escalations (operations that take longer get higher priority)
                    if ((global_timestamp - cache_op_queue_timestamp[j]) > (maint_timeout_cycles >> 1) &&
                        cache_op_queue_priority[j] < 4'hF) begin
                        cache_op_queue_priority[j] <= cache_op_queue_priority[j] + 1;
                        maint_priority_escalations <= maint_priority_escalations + 1;
                    end
                end
            end
        end
    end

endmodule

//---------------------------------------------------------------------------
// ACE-Lite MOESI Cache State Management
//---------------------------------------------------------------------------
module ace_lite_cache_states
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , CACHE_LINE_ENTRIES = 1024)  // Number of cache lines to track
(
      input  wire                    clk
    , input  wire                    rst_n
    // Master 0 cache state interface
    , input  wire [WIDTH_AD-1:0]    m0_addr          // Address for state lookup
    , input  wire                   m0_state_req     // State query request
    , input  wire [2:0]             m0_new_state     // New cache state to set
    , input  wire                   m0_state_update  // Update cache state
    , output reg  [2:0]             m0_current_state // Current cache state
    , output reg                    m0_state_valid   // State lookup valid
    // Master 1 cache state interface
    , input  wire [WIDTH_AD-1:0]    m1_addr          // Address for state lookup
    , input  wire                   m1_state_req     // State query request
    , input  wire [2:0]             m1_new_state     // New cache state to set
    , input  wire                   m1_state_update  // Update cache state
    , output reg  [2:0]             m1_current_state // Current cache state
    , output reg                    m1_state_valid   // State lookup valid
    // Master 2 cache state interface
    , input  wire [WIDTH_AD-1:0]    m2_addr          // Address for state lookup
    , input  wire                   m2_state_req     // State query request
    , input  wire [2:0]             m2_new_state     // New cache state to set
    , input  wire                   m2_state_update  // Update cache state
    , output reg  [2:0]             m2_current_state // Current cache state
    , output reg                    m2_state_valid   // State lookup valid
    // Master 3 cache state interface
    , input  wire [WIDTH_AD-1:0]    m3_addr          // Address for state lookup
    , input  wire                   m3_state_req     // State query request
    , input  wire [2:0]             m3_new_state     // New cache state to set
    , input  wire                   m3_state_update  // Update cache state
    , output reg  [2:0]             m3_current_state // Current cache state
    , output reg                    m3_state_valid   // State lookup valid
    // Global cache state monitoring outputs
    , output reg  [31:0]            cache_hits         // Total cache hits
    , output reg  [31:0]            cache_misses       // Total cache misses
    , output reg  [31:0]            state_transitions  // Total state transitions
    , output reg  [NUM_MASTER-1:0] coherency_conflict // Coherency conflicts per master
);

    // MOESI Cache State Encodings
    localparam [2:0] STATE_INVALID   = 3'b000;  // I - Invalid (not cached)
    localparam [2:0] STATE_SHARED    = 3'b001;  // S - Shared (read-only, may be in other caches)
    localparam [2:0] STATE_EXCLUSIVE = 3'b010;  // E - Exclusive (read-only, only copy)
    localparam [2:0] STATE_OWNED     = 3'b011;  // O - Owned (dirty, shared with others)
    localparam [2:0] STATE_MODIFIED  = 3'b100;  // M - Modified (dirty, only copy)
    localparam [2:0] STATE_RESERVED1 = 3'b101;  // Reserved for future use
    localparam [2:0] STATE_RESERVED2 = 3'b110;  // Reserved for future use
    localparam [2:0] STATE_ERROR     = 3'b111;  // Error state

    // Cache Line State Tracking
    // Each cache line tracks: address tag, state per master, LRU info
    reg [WIDTH_AD-7:0] cache_tag [CACHE_LINE_ENTRIES-1:0];     // Address tag (excluding lower 6 bits)
    reg [2:0]          cache_state [CACHE_LINE_ENTRIES-1:0][NUM_MASTER-1:0]; // State per master
    reg                cache_valid [CACHE_LINE_ENTRIES-1:0];   // Valid cache line
    reg [7:0]          cache_lru [CACHE_LINE_ENTRIES-1:0];     // LRU counter (0=most recent)
    reg [NUM_MASTER-1:0] cache_owner [CACHE_LINE_ENTRIES-1:0]; // Master that owns this line

    // Internal Cache Management Signals
    reg [9:0] cache_index [NUM_MASTER-1:0];     // Cache index for each master
    reg       cache_hit [NUM_MASTER-1:0];       // Cache hit indicator
    reg [9:0] victim_index;                     // Index for cache replacement
    reg       replacement_needed;               // Need to replace cache line
    
    // Cache Lookup Logic
    // Determines cache index and hit/miss for each master
    integer k;
    always @(*) begin
        // Master 0 cache lookup
        cache_index[0] = m0_addr[15:6];  // Use middle bits for index
        cache_hit[0] = 1'b0;
        m0_current_state = STATE_INVALID;
        m0_state_valid = 1'b0;
        
        if (m0_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m0_addr[WIDTH_AD-1:6])) begin
                    cache_hit[0] = 1'b1;
                    cache_index[0] = k[9:0];
                    m0_current_state = cache_state[k][0];
                    m0_state_valid = 1'b1;
                end
            end
        end
        
        // Master 1 cache lookup
        cache_index[1] = m1_addr[15:6];  // Use middle bits for index
        cache_hit[1] = 1'b0;
        m1_current_state = STATE_INVALID;
        m1_state_valid = 1'b0;
        
        if (m1_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m1_addr[WIDTH_AD-1:6])) begin
                    cache_hit[1] = 1'b1;
                    cache_index[1] = k[9:0];
                    m1_current_state = cache_state[k][1];
                    m1_state_valid = 1'b1;
                end
            end
        end
        
        // Master 2 cache lookup
        cache_index[2] = m2_addr[15:6];  // Use middle bits for index
        cache_hit[2] = 1'b0;
        m2_current_state = STATE_INVALID;
        m2_state_valid = 1'b0;
        
        if (m2_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m2_addr[WIDTH_AD-1:6])) begin
                    cache_hit[2] = 1'b1;
                    cache_index[2] = k[9:0];
                    m2_current_state = cache_state[k][2];
                    m2_state_valid = 1'b1;
                end
            end
        end
        
        // Master 3 cache lookup
        cache_index[3] = m3_addr[15:6];  // Use middle bits for index
        cache_hit[3] = 1'b0;
        m3_current_state = STATE_INVALID;
        m3_state_valid = 1'b0;
        
        if (m3_state_req) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && 
                    (cache_tag[k] == m3_addr[WIDTH_AD-1:6])) begin
                    cache_hit[3] = 1'b1;
                    cache_index[3] = k[9:0];
                    m3_current_state = cache_state[k][3];
                    m3_state_valid = 1'b1;
                end
            end
        end
        
    end

    // LRU Victim Selection Logic
    always @(*) begin
        victim_index = 10'h000;
        replacement_needed = 1'b0;
        
        // Find invalid entry first
        for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
            if (!cache_valid[k]) begin
                victim_index = k[9:0];
                replacement_needed = 1'b0;
            end
        end
        
        // If no invalid entries, find LRU
        if (replacement_needed) begin
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_lru[k] == 8'hFF) begin  // Oldest LRU
                    victim_index = k[9:0];
                end
            end
        end
    end

    // Cache State Update Logic
    // Implements MOESI protocol state transitions
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all cache states
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                cache_valid[k] <= 1'b0;
                cache_tag[k] <= {(WIDTH_AD-6){1'b0}};
                cache_lru[k] <= 8'h00;
                cache_owner[k] <= {NUM_MASTER{1'b0}};
                cache_state[k][0] <= STATE_INVALID;
                cache_state[k][1] <= STATE_INVALID;
                cache_state[k][2] <= STATE_INVALID;
                cache_state[k][3] <= STATE_INVALID;
            end
            
            // Reset statistics
            cache_hits <= 32'h00000000;
            cache_misses <= 32'h00000000;
            state_transitions <= 32'h00000000;
            coherency_conflict <= {NUM_MASTER{1'b0}};
            
        end else begin
            // Update LRU counters (age all entries)
            for (k = 0; k < CACHE_LINE_ENTRIES; k = k + 1) begin
                if (cache_valid[k] && cache_lru[k] < 8'hFF) begin
                    cache_lru[k] <= cache_lru[k] + 1;
                end
            end
            
            // Master 0 state update processing
            if (m0_state_update) begin
                if (cache_hit[0]) begin
                    // Update existing cache line
                    cache_state[cache_index[0]][0] <= m0_new_state;
                    cache_lru[cache_index[0]] <= 8'h00;  // Mark as most recent
                    cache_hits <= cache_hits + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Check for coherency conflicts
                    if (m0_new_state == STATE_MODIFIED || m0_new_state == STATE_EXCLUSIVE) begin
                        for (k = 0; k < NUM_MASTER; k = k + 1) begin
                            if (k != 0 && cache_state[cache_index[0]][k] != STATE_INVALID) begin
                                coherency_conflict[0] <= 1'b1;
                                // Invalidate other masters' copies
                                cache_state[cache_index[0]][k] <= STATE_INVALID;
                            end
                        end
                    end
                    
                end else begin
                    // Allocate new cache line
                    cache_valid[victim_index] <= 1'b1;
                    cache_tag[victim_index] <= m0_addr[WIDTH_AD-1:6];
                    cache_state[victim_index][0] <= m0_new_state;
                    cache_lru[victim_index] <= 8'h00;
                    cache_owner[victim_index][0] <= 1'b1;
                    cache_misses <= cache_misses + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Clear other masters' ownership of this line
                    for (k = 0; k < NUM_MASTER; k = k + 1) begin
                        if (k != 0) begin
                            cache_state[victim_index][k] <= STATE_INVALID;
                            cache_owner[victim_index][k] <= 1'b0;
                        end
                    end
                end
            end
            
            // Clear coherency conflict flag after one cycle
            coherency_conflict[0] <= 1'b0;
            
            // Master 1 state update processing
            if (m1_state_update) begin
                if (cache_hit[1]) begin
                    // Update existing cache line
                    cache_state[cache_index[1]][1] <= m1_new_state;
                    cache_lru[cache_index[1]] <= 8'h00;  // Mark as most recent
                    cache_hits <= cache_hits + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Check for coherency conflicts
                    if (m1_new_state == STATE_MODIFIED || m1_new_state == STATE_EXCLUSIVE) begin
                        for (k = 0; k < NUM_MASTER; k = k + 1) begin
                            if (k != 1 && cache_state[cache_index[1]][k] != STATE_INVALID) begin
                                coherency_conflict[1] <= 1'b1;
                                // Invalidate other masters' copies
                                cache_state[cache_index[1]][k] <= STATE_INVALID;
                            end
                        end
                    end
                    
                end else begin
                    // Allocate new cache line
                    cache_valid[victim_index] <= 1'b1;
                    cache_tag[victim_index] <= m1_addr[WIDTH_AD-1:6];
                    cache_state[victim_index][1] <= m1_new_state;
                    cache_lru[victim_index] <= 8'h00;
                    cache_owner[victim_index][1] <= 1'b1;
                    cache_misses <= cache_misses + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Clear other masters' ownership of this line
                    for (k = 0; k < NUM_MASTER; k = k + 1) begin
                        if (k != 1) begin
                            cache_state[victim_index][k] <= STATE_INVALID;
                            cache_owner[victim_index][k] <= 1'b0;
                        end
                    end
                end
            end
            
            // Clear coherency conflict flag after one cycle
            coherency_conflict[1] <= 1'b0;
            
            // Master 2 state update processing
            if (m2_state_update) begin
                if (cache_hit[2]) begin
                    // Update existing cache line
                    cache_state[cache_index[2]][2] <= m2_new_state;
                    cache_lru[cache_index[2]] <= 8'h00;  // Mark as most recent
                    cache_hits <= cache_hits + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Check for coherency conflicts
                    if (m2_new_state == STATE_MODIFIED || m2_new_state == STATE_EXCLUSIVE) begin
                        for (k = 0; k < NUM_MASTER; k = k + 1) begin
                            if (k != 2 && cache_state[cache_index[2]][k] != STATE_INVALID) begin
                                coherency_conflict[2] <= 1'b1;
                                // Invalidate other masters' copies
                                cache_state[cache_index[2]][k] <= STATE_INVALID;
                            end
                        end
                    end
                    
                end else begin
                    // Allocate new cache line
                    cache_valid[victim_index] <= 1'b1;
                    cache_tag[victim_index] <= m2_addr[WIDTH_AD-1:6];
                    cache_state[victim_index][2] <= m2_new_state;
                    cache_lru[victim_index] <= 8'h00;
                    cache_owner[victim_index][2] <= 1'b1;
                    cache_misses <= cache_misses + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Clear other masters' ownership of this line
                    for (k = 0; k < NUM_MASTER; k = k + 1) begin
                        if (k != 2) begin
                            cache_state[victim_index][k] <= STATE_INVALID;
                            cache_owner[victim_index][k] <= 1'b0;
                        end
                    end
                end
            end
            
            // Clear coherency conflict flag after one cycle
            coherency_conflict[2] <= 1'b0;
            
            // Master 3 state update processing
            if (m3_state_update) begin
                if (cache_hit[3]) begin
                    // Update existing cache line
                    cache_state[cache_index[3]][3] <= m3_new_state;
                    cache_lru[cache_index[3]] <= 8'h00;  // Mark as most recent
                    cache_hits <= cache_hits + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Check for coherency conflicts
                    if (m3_new_state == STATE_MODIFIED || m3_new_state == STATE_EXCLUSIVE) begin
                        for (k = 0; k < NUM_MASTER; k = k + 1) begin
                            if (k != 3 && cache_state[cache_index[3]][k] != STATE_INVALID) begin
                                coherency_conflict[3] <= 1'b1;
                                // Invalidate other masters' copies
                                cache_state[cache_index[3]][k] <= STATE_INVALID;
                            end
                        end
                    end
                    
                end else begin
                    // Allocate new cache line
                    cache_valid[victim_index] <= 1'b1;
                    cache_tag[victim_index] <= m3_addr[WIDTH_AD-1:6];
                    cache_state[victim_index][3] <= m3_new_state;
                    cache_lru[victim_index] <= 8'h00;
                    cache_owner[victim_index][3] <= 1'b1;
                    cache_misses <= cache_misses + 1;
                    state_transitions <= state_transitions + 1;
                    
                    // Clear other masters' ownership of this line
                    for (k = 0; k < NUM_MASTER; k = k + 1) begin
                        if (k != 3) begin
                            cache_state[victim_index][k] <= STATE_INVALID;
                            cache_owner[victim_index][k] <= 1'b0;
                        end
                    end
                end
            end
            
            // Clear coherency conflict flag after one cycle
            coherency_conflict[3] <= 1'b0;
            
        end
    end

    // MOESI Protocol State Transition Validation
    // Ensures only valid MOESI transitions occur
    function automatic logic valid_transition;
        input [2:0] current_state;
        input [2:0] new_state;
        begin
            case (current_state)
                STATE_INVALID: begin
                    // From Invalid: can go to any state except Owned
                    valid_transition = (new_state != STATE_OWNED);
                end
                STATE_SHARED: begin
                    // From Shared: can go to Invalid, Exclusive, or Modified
                    valid_transition = (new_state == STATE_INVALID) || 
                                     (new_state == STATE_EXCLUSIVE) || 
                                     (new_state == STATE_MODIFIED);
                end
                STATE_EXCLUSIVE: begin
                    // From Exclusive: can go to Invalid, Shared, or Modified
                    valid_transition = (new_state == STATE_INVALID) || 
                                     (new_state == STATE_SHARED) || 
                                     (new_state == STATE_MODIFIED);
                end
                STATE_OWNED: begin
                    // From Owned: can go to Invalid or Modified
                    valid_transition = (new_state == STATE_INVALID) || 
                                     (new_state == STATE_MODIFIED);
                end
                STATE_MODIFIED: begin
                    // From Modified: can go to Invalid, Shared, or Owned
                    valid_transition = (new_state == STATE_INVALID) || 
                                     (new_state == STATE_SHARED) || 
                                     (new_state == STATE_OWNED);
                end
                default: begin
                    valid_transition = 1'b0;  // Invalid current state
                end
            endcase
        end
    endfunction

endmodule


//---------------------------------------------------------------------------
// ACE-Lite Exclusive Access Monitor
// Tracks exclusive access operations per master/ID pair
//---------------------------------------------------------------------------
module ace_lite_exclusive_monitor
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_ID   = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , EXCLUSIVE_DEPTH = 16) // Depth of exclusive tracking
(
      input  wire                       clk
    , input  wire                       rst_n
    // Master 0 exclusive access interface
    , input  wire [WIDTH_ID-1:0]       m0_awid
    , input  wire [WIDTH_AD-1:0]       m0_awaddr
    , input  wire [2:0]                m0_awsize
    , input  wire                      m0_awlock
    , input  wire                      m0_awvalid
    , input  wire                      m0_awready
    , input  wire [WIDTH_ID-1:0]       m0_arid
    , input  wire [WIDTH_AD-1:0]       m0_araddr
    , input  wire [2:0]                m0_arsize
    , input  wire                      m0_arlock
    , input  wire                      m0_arvalid
    , input  wire                      m0_arready
    , input  wire [WIDTH_ID-1:0]       m0_bid
    , input  wire [1:0]                m0_bresp
    , input  wire                      m0_bvalid
    , input  wire                      m0_bready
    // Master 1 exclusive access interface
    , input  wire [WIDTH_ID-1:0]       m1_awid
    , input  wire [WIDTH_AD-1:0]       m1_awaddr
    , input  wire [2:0]                m1_awsize
    , input  wire                      m1_awlock
    , input  wire                      m1_awvalid
    , input  wire                      m1_awready
    , input  wire [WIDTH_ID-1:0]       m1_arid
    , input  wire [WIDTH_AD-1:0]       m1_araddr
    , input  wire [2:0]                m1_arsize
    , input  wire                      m1_arlock
    , input  wire                      m1_arvalid
    , input  wire                      m1_arready
    , input  wire [WIDTH_ID-1:0]       m1_bid
    , input  wire [1:0]                m1_bresp
    , input  wire                      m1_bvalid
    , input  wire                      m1_bready
    // Master 2 exclusive access interface
    , input  wire [WIDTH_ID-1:0]       m2_awid
    , input  wire [WIDTH_AD-1:0]       m2_awaddr
    , input  wire [2:0]                m2_awsize
    , input  wire                      m2_awlock
    , input  wire                      m2_awvalid
    , input  wire                      m2_awready
    , input  wire [WIDTH_ID-1:0]       m2_arid
    , input  wire [WIDTH_AD-1:0]       m2_araddr
    , input  wire [2:0]                m2_arsize
    , input  wire                      m2_arlock
    , input  wire                      m2_arvalid
    , input  wire                      m2_arready
    , input  wire [WIDTH_ID-1:0]       m2_bid
    , input  wire [1:0]                m2_bresp
    , input  wire                      m2_bvalid
    , input  wire                      m2_bready
    // Master 3 exclusive access interface
    , input  wire [WIDTH_ID-1:0]       m3_awid
    , input  wire [WIDTH_AD-1:0]       m3_awaddr
    , input  wire [2:0]                m3_awsize
    , input  wire                      m3_awlock
    , input  wire                      m3_awvalid
    , input  wire                      m3_awready
    , input  wire [WIDTH_ID-1:0]       m3_arid
    , input  wire [WIDTH_AD-1:0]       m3_araddr
    , input  wire [2:0]                m3_arsize
    , input  wire                      m3_arlock
    , input  wire                      m3_arvalid
    , input  wire                      m3_arready
    , input  wire [WIDTH_ID-1:0]       m3_bid
    , input  wire [1:0]                m3_bresp
    , input  wire                      m3_bvalid
    , input  wire                      m3_bready
    // Exclusive access control
    , input  wire                       exclusive_enable
    , input  wire                       exclusive_clear_all
    // Exclusive access status outputs
    , output reg  [NUM_MASTER-1:0]       exclusive_active
    , output reg  [NUM_MASTER-1:0]       exclusive_granted
    , output wire [7:0]                  exclusive_count
    , output reg  [7:0]                  exclusive_violations
    , output reg  [7:0]                  exclusive_successes
);

    // Exclusive access tracking structure
    reg [WIDTH_AD-1:0] exclusive_addr [0:EXCLUSIVE_DEPTH-1];
    reg [WIDTH_ID-1:0] exclusive_id [0:EXCLUSIVE_DEPTH-1];
    reg [7:0] exclusive_master [0:EXCLUSIVE_DEPTH-1];
    reg [2:0] exclusive_size [0:EXCLUSIVE_DEPTH-1];
    reg [EXCLUSIVE_DEPTH-1:0] exclusive_valid;
    reg [$clog2(EXCLUSIVE_DEPTH)-1:0] exclusive_wr_ptr;
    reg [7:0] exclusive_count_reg;

    // Exclusive access address alignment
    function [WIDTH_AD-1:0] align_exclusive_addr;
        input [WIDTH_AD-1:0] addr;
        input [2:0] size;
        begin
            case (size)
                3'b000: align_exclusive_addr = addr;                    // 1 byte
                3'b001: align_exclusive_addr = {addr[WIDTH_AD-1:1], 1'b0};   // 2 bytes
                3'b010: align_exclusive_addr = {addr[WIDTH_AD-1:2], 2'b0};   // 4 bytes
                3'b011: align_exclusive_addr = {addr[WIDTH_AD-1:3], 3'b0};   // 8 bytes
                3'b100: align_exclusive_addr = {addr[WIDTH_AD-1:4], 4'b0};   // 16 bytes
                3'b101: align_exclusive_addr = {addr[WIDTH_AD-1:5], 5'b0};   // 32 bytes
                3'b110: align_exclusive_addr = {addr[WIDTH_AD-1:6], 6'b0};   // 64 bytes
                3'b111: align_exclusive_addr = {addr[WIDTH_AD-1:7], 7'b0};   // 128 bytes
            endcase
        end
    endfunction

    // Exclusive access match detection
    function exclusive_match;
        input [WIDTH_AD-1:0] addr1, addr2;
        input [WIDTH_ID-1:0] id1, id2;
        input [7:0] master1, master2;
        input [2:0] size1, size2;
        begin
            exclusive_match = (align_exclusive_addr(addr1, size1) == align_exclusive_addr(addr2, size2)) &&
                             (id1 == id2) && (master1 == master2);
        end
    endfunction

    // Exclusive access monitoring logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            exclusive_valid <= {EXCLUSIVE_DEPTH{1'b0}};
            exclusive_wr_ptr <= 0;
            exclusive_count_reg <= 8'h0;
            exclusive_violations <= 8'h0;
            exclusive_successes <= 8'h0;
            exclusive_active[0] <= 1'b0;
            exclusive_granted[0] <= 1'b0;
            exclusive_active[1] <= 1'b0;
            exclusive_granted[1] <= 1'b0;
            exclusive_active[2] <= 1'b0;
            exclusive_granted[2] <= 1'b0;
            exclusive_active[3] <= 1'b0;
            exclusive_granted[3] <= 1'b0;
        end else if (exclusive_enable) begin
            
            // Clear all exclusive accesses if requested
            if (exclusive_clear_all) begin
                exclusive_valid <= {EXCLUSIVE_DEPTH{1'b0}};
                exclusive_count_reg <= 8'h0;
                exclusive_active[0] <= 1'b0;
                exclusive_granted[0] <= 1'b0;
                exclusive_active[1] <= 1'b0;
                exclusive_granted[1] <= 1'b0;
                exclusive_active[2] <= 1'b0;
                exclusive_granted[2] <= 1'b0;
                exclusive_active[3] <= 1'b0;
                exclusive_granted[3] <= 1'b0;
            end else begin
                
                // Master 0 exclusive read processing
                if (m0_arvalid && m0_arready && m0_arlock) begin
                    // Record exclusive read
                    if (!exclusive_valid[exclusive_wr_ptr]) begin
                        exclusive_addr[exclusive_wr_ptr] <= align_exclusive_addr(m0_araddr, m0_arsize);
                        exclusive_id[exclusive_wr_ptr] <= m0_arid;
                        exclusive_master[exclusive_wr_ptr] <= 0;
                        exclusive_size[exclusive_wr_ptr] <= m0_arsize;
                        exclusive_valid[exclusive_wr_ptr] <= 1'b1;
                        exclusive_wr_ptr <= (exclusive_wr_ptr + 1) % EXCLUSIVE_DEPTH;
                        exclusive_count_reg <= exclusive_count_reg + 1;
                        exclusive_active[0] <= 1'b1;
                    end
                end
                
                // Master 0 exclusive write processing
                if (m0_awvalid && m0_awready && m0_awlock) begin
                    exclusive_granted[0] <= 1'b0;  // Default to not granted
                    
                    // Check for matching exclusive read
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            exclusive_match(exclusive_addr[j], align_exclusive_addr(m0_awaddr, m0_awsize),
                                          exclusive_id[j], m0_awid,
                                          exclusive_master[j], 0,
                                          exclusive_size[j], m0_awsize)) begin
                            // Grant exclusive access
                            exclusive_granted[0] <= 1'b1;
                            // Clear the exclusive reservation
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                        end
                    end
                end
                
                // Master 0 write response processing
                if (m0_bvalid && m0_bready) begin
                    if (exclusive_granted[0]) begin
                        if (m0_bresp == 2'b01) begin // EXOKAY
                            exclusive_successes <= exclusive_successes + 1;
                        end else begin // OKAY or error
                            exclusive_violations <= exclusive_violations + 1;
                        end
                        exclusive_granted[0] <= 1'b0;
                        exclusive_active[0] <= 1'b0;
                    end
                end
                
                // Master 1 exclusive read processing
                if (m1_arvalid && m1_arready && m1_arlock) begin
                    // Record exclusive read
                    if (!exclusive_valid[exclusive_wr_ptr]) begin
                        exclusive_addr[exclusive_wr_ptr] <= align_exclusive_addr(m1_araddr, m1_arsize);
                        exclusive_id[exclusive_wr_ptr] <= m1_arid;
                        exclusive_master[exclusive_wr_ptr] <= 1;
                        exclusive_size[exclusive_wr_ptr] <= m1_arsize;
                        exclusive_valid[exclusive_wr_ptr] <= 1'b1;
                        exclusive_wr_ptr <= (exclusive_wr_ptr + 1) % EXCLUSIVE_DEPTH;
                        exclusive_count_reg <= exclusive_count_reg + 1;
                        exclusive_active[1] <= 1'b1;
                    end
                end
                
                // Master 1 exclusive write processing
                if (m1_awvalid && m1_awready && m1_awlock) begin
                    exclusive_granted[1] <= 1'b0;  // Default to not granted
                    
                    // Check for matching exclusive read
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            exclusive_match(exclusive_addr[j], align_exclusive_addr(m1_awaddr, m1_awsize),
                                          exclusive_id[j], m1_awid,
                                          exclusive_master[j], 1,
                                          exclusive_size[j], m1_awsize)) begin
                            // Grant exclusive access
                            exclusive_granted[1] <= 1'b1;
                            // Clear the exclusive reservation
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                        end
                    end
                end
                
                // Master 1 write response processing
                if (m1_bvalid && m1_bready) begin
                    if (exclusive_granted[1]) begin
                        if (m1_bresp == 2'b01) begin // EXOKAY
                            exclusive_successes <= exclusive_successes + 1;
                        end else begin // OKAY or error
                            exclusive_violations <= exclusive_violations + 1;
                        end
                        exclusive_granted[1] <= 1'b0;
                        exclusive_active[1] <= 1'b0;
                    end
                end
                
                // Master 2 exclusive read processing
                if (m2_arvalid && m2_arready && m2_arlock) begin
                    // Record exclusive read
                    if (!exclusive_valid[exclusive_wr_ptr]) begin
                        exclusive_addr[exclusive_wr_ptr] <= align_exclusive_addr(m2_araddr, m2_arsize);
                        exclusive_id[exclusive_wr_ptr] <= m2_arid;
                        exclusive_master[exclusive_wr_ptr] <= 2;
                        exclusive_size[exclusive_wr_ptr] <= m2_arsize;
                        exclusive_valid[exclusive_wr_ptr] <= 1'b1;
                        exclusive_wr_ptr <= (exclusive_wr_ptr + 1) % EXCLUSIVE_DEPTH;
                        exclusive_count_reg <= exclusive_count_reg + 1;
                        exclusive_active[2] <= 1'b1;
                    end
                end
                
                // Master 2 exclusive write processing
                if (m2_awvalid && m2_awready && m2_awlock) begin
                    exclusive_granted[2] <= 1'b0;  // Default to not granted
                    
                    // Check for matching exclusive read
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            exclusive_match(exclusive_addr[j], align_exclusive_addr(m2_awaddr, m2_awsize),
                                          exclusive_id[j], m2_awid,
                                          exclusive_master[j], 2,
                                          exclusive_size[j], m2_awsize)) begin
                            // Grant exclusive access
                            exclusive_granted[2] <= 1'b1;
                            // Clear the exclusive reservation
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                        end
                    end
                end
                
                // Master 2 write response processing
                if (m2_bvalid && m2_bready) begin
                    if (exclusive_granted[2]) begin
                        if (m2_bresp == 2'b01) begin // EXOKAY
                            exclusive_successes <= exclusive_successes + 1;
                        end else begin // OKAY or error
                            exclusive_violations <= exclusive_violations + 1;
                        end
                        exclusive_granted[2] <= 1'b0;
                        exclusive_active[2] <= 1'b0;
                    end
                end
                
                // Master 3 exclusive read processing
                if (m3_arvalid && m3_arready && m3_arlock) begin
                    // Record exclusive read
                    if (!exclusive_valid[exclusive_wr_ptr]) begin
                        exclusive_addr[exclusive_wr_ptr] <= align_exclusive_addr(m3_araddr, m3_arsize);
                        exclusive_id[exclusive_wr_ptr] <= m3_arid;
                        exclusive_master[exclusive_wr_ptr] <= 3;
                        exclusive_size[exclusive_wr_ptr] <= m3_arsize;
                        exclusive_valid[exclusive_wr_ptr] <= 1'b1;
                        exclusive_wr_ptr <= (exclusive_wr_ptr + 1) % EXCLUSIVE_DEPTH;
                        exclusive_count_reg <= exclusive_count_reg + 1;
                        exclusive_active[3] <= 1'b1;
                    end
                end
                
                // Master 3 exclusive write processing
                if (m3_awvalid && m3_awready && m3_awlock) begin
                    exclusive_granted[3] <= 1'b0;  // Default to not granted
                    
                    // Check for matching exclusive read
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            exclusive_match(exclusive_addr[j], align_exclusive_addr(m3_awaddr, m3_awsize),
                                          exclusive_id[j], m3_awid,
                                          exclusive_master[j], 3,
                                          exclusive_size[j], m3_awsize)) begin
                            // Grant exclusive access
                            exclusive_granted[3] <= 1'b1;
                            // Clear the exclusive reservation
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                        end
                    end
                end
                
                // Master 3 write response processing
                if (m3_bvalid && m3_bready) begin
                    if (exclusive_granted[3]) begin
                        if (m3_bresp == 2'b01) begin // EXOKAY
                            exclusive_successes <= exclusive_successes + 1;
                        end else begin // OKAY or error
                            exclusive_violations <= exclusive_violations + 1;
                        end
                        exclusive_granted[3] <= 1'b0;
                        exclusive_active[3] <= 1'b0;
                    end
                end
                
                // Clear exclusive reservations on intervening normal writes
                if (m0_awvalid && m0_awready && !m0_awlock) begin
                    // Clear any exclusive reservations that overlap with this address
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m0_awaddr, m0_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
                if (m1_awvalid && m1_awready && !m1_awlock) begin
                    // Clear any exclusive reservations that overlap with this address
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m1_awaddr, m1_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
                if (m2_awvalid && m2_awready && !m2_awlock) begin
                    // Clear any exclusive reservations that overlap with this address
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m2_awaddr, m2_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
                if (m3_awvalid && m3_awready && !m3_awlock) begin
                    // Clear any exclusive reservations that overlap with this address
                    for (integer j = 0; j < EXCLUSIVE_DEPTH; j = j + 1) begin
                        if (exclusive_valid[j] && 
                            (align_exclusive_addr(exclusive_addr[j], exclusive_size[j]) == 
                             align_exclusive_addr(m3_awaddr, m3_awsize))) begin
                            exclusive_valid[j] <= 1'b0;
                            exclusive_count_reg <= exclusive_count_reg - 1;
                            exclusive_violations <= exclusive_violations + 1;
                        end
                    end
                end
            end
        end
    end

    // Output assignments
    assign exclusive_count = exclusive_count_reg;

endmodule

//---------------------------------------------------------------------------
// ACE-Lite DVM (Distributed Virtual Memory) Controller
// Manages DVM messages, TLB invalidation, and virtual memory coherency
//---------------------------------------------------------------------------
module ace_lite_dvm_controller
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , WIDTH_ID   = 4
              , DVM_QUEUE_DEPTH = 16)  // DVM message queue depth
(
      input  wire                    clk
    , input  wire                    rst_n
    // Master 0 DVM interface
    , input  wire [WIDTH_AD-1:0]    m0_dvm_addr       // DVM target address
    , input  wire [7:0]             m0_dvm_type       // DVM message type
    , input  wire [15:0]            m0_dvm_asid       // Address Space ID
    , input  wire                   m0_dvm_valid      // DVM request valid
    , output reg                    m0_dvm_ready      // DVM request ready
    , output reg                    m0_dvm_complete   // DVM operation complete
    , output reg  [1:0]             m0_dvm_resp       // DVM response (00=OK, 01=ERROR)
    // Master 1 DVM interface
    , input  wire [WIDTH_AD-1:0]    m1_dvm_addr       // DVM target address
    , input  wire [7:0]             m1_dvm_type       // DVM message type
    , input  wire [15:0]            m1_dvm_asid       // Address Space ID
    , input  wire                   m1_dvm_valid      // DVM request valid
    , output reg                    m1_dvm_ready      // DVM request ready
    , output reg                    m1_dvm_complete   // DVM operation complete
    , output reg  [1:0]             m1_dvm_resp       // DVM response (00=OK, 01=ERROR)
    // Master 2 DVM interface
    , input  wire [WIDTH_AD-1:0]    m2_dvm_addr       // DVM target address
    , input  wire [7:0]             m2_dvm_type       // DVM message type
    , input  wire [15:0]            m2_dvm_asid       // Address Space ID
    , input  wire                   m2_dvm_valid      // DVM request valid
    , output reg                    m2_dvm_ready      // DVM request ready
    , output reg                    m2_dvm_complete   // DVM operation complete
    , output reg  [1:0]             m2_dvm_resp       // DVM response (00=OK, 01=ERROR)
    // Master 3 DVM interface
    , input  wire [WIDTH_AD-1:0]    m3_dvm_addr       // DVM target address
    , input  wire [7:0]             m3_dvm_type       // DVM message type
    , input  wire [15:0]            m3_dvm_asid       // Address Space ID
    , input  wire                   m3_dvm_valid      // DVM request valid
    , output reg                    m3_dvm_ready      // DVM request ready
    , output reg                    m3_dvm_complete   // DVM operation complete
    , output reg  [1:0]             m3_dvm_resp       // DVM response (00=OK, 01=ERROR)
    // Global DVM status outputs
    , output reg                    dvm_active         // DVM operation in progress
    , output reg  [31:0]            dvm_operations     // Total DVM operations
    , output reg  [31:0]            dvm_timeouts       // DVM timeout count
    , output reg  [NUM_MASTER-1:0] dvm_error          // DVM error per master
);

    // DVM Message Type Definitions
    localparam [7:0] DVM_TLBI_ALL       = 8'h00;  // Invalidate all TLB entries
    localparam [7:0] DVM_TLBI_ASID      = 8'h01;  // Invalidate by ASID
    localparam [7:0] DVM_TLBI_VA        = 8'h02;  // Invalidate by Virtual Address
    localparam [7:0] DVM_TLBI_VAA       = 8'h03;  // Invalidate by VA and ASID
    localparam [7:0] DVM_TLBI_VMALL     = 8'h04;  // Invalidate all for VM
    localparam [7:0] DVM_TLBI_IPAS2     = 8'h05;  // Invalidate IPA Stage 2
    localparam [7:0] DVM_TLBI_IPAS2L    = 8'h06;  // Invalidate IPA Stage 2 Last level
    localparam [7:0] DVM_SYNC           = 8'hFF;  // DVM Synchronization

    // DVM Response Types
    localparam [1:0] DVM_RESP_OK        = 2'b00;  // Operation successful
    localparam [1:0] DVM_RESP_ERROR     = 2'b01;  // Operation failed
    localparam [1:0] DVM_RESP_TIMEOUT   = 2'b10;  // Operation timed out
    localparam [1:0] DVM_RESP_UNSUP     = 2'b11;  // Unsupported operation

    // DVM Operation State Machine
    localparam [3:0] DVM_IDLE           = 4'h0;   // Idle state
    localparam [3:0] DVM_REQUEST        = 4'h1;   // Process DVM request
    localparam [3:0] DVM_BROADCAST      = 4'h2;   // Broadcast to masters
    localparam [3:0] DVM_WAIT_ACK       = 4'h3;   // Wait for acknowledgments
    localparam [3:0] DVM_SYNC_STATE     = 4'h4;   // Synchronization phase
    localparam [3:0] DVM_COMPLETE       = 4'h5;   // Operation complete
    localparam [3:0] DVM_ERROR          = 4'h6;   // Error handling
    localparam [3:0] DVM_TIMEOUT        = 4'h7;   // Timeout handling

    // DVM Controller State Registers
    reg [3:0] dvm_state;
    reg [3:0] dvm_next_state;
    reg [$clog2(DVM_QUEUE_DEPTH)-1:0] dvm_queue_head;
    reg [$clog2(DVM_QUEUE_DEPTH)-1:0] dvm_queue_tail;
    reg [$clog2(DVM_QUEUE_DEPTH)-1:0] dvm_queue_count;
    
    // DVM Message Queue
    reg [WIDTH_AD-1:0] dvm_queue_addr [DVM_QUEUE_DEPTH-1:0];
    reg [7:0]          dvm_queue_type [DVM_QUEUE_DEPTH-1:0];
    reg [15:0]         dvm_queue_asid [DVM_QUEUE_DEPTH-1:0];
    reg [3:0]          dvm_queue_master [DVM_QUEUE_DEPTH-1:0];
    reg                dvm_queue_valid [DVM_QUEUE_DEPTH-1:0];
    
    // DVM Acknowledgment Tracking
    reg [NUM_MASTER-1:0] dvm_ack_pending;     // Acknowledgments pending per master
    reg [NUM_MASTER-1:0] dvm_ack_received;    // Acknowledgments received per master
    reg [NUM_MASTER-1:0] dvm_target_masters;  // Target masters for current DVM
    reg [15:0] dvm_timeout_counter;           // Timeout counter
    reg        dvm_timeout_error;             // Timeout error flag
    
    // Current DVM Operation Tracking
    reg [WIDTH_AD-1:0] current_dvm_addr;
    reg [7:0]          current_dvm_type;
    reg [15:0]         current_dvm_asid;
    reg [3:0]          current_dvm_master;
    
    // DVM Queue Management Logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dvm_queue_head <= 0;
            dvm_queue_tail <= 0;
            dvm_queue_count <= 0;
            
            for (integer k = 0; k < DVM_QUEUE_DEPTH; k = k + 1) begin
                dvm_queue_valid[k] <= 1'b0;
            end
            
            m0_dvm_ready <= 1'b1;
            m0_dvm_complete <= 1'b0;
            m0_dvm_resp <= DVM_RESP_OK;
            m1_dvm_ready <= 1'b1;
            m1_dvm_complete <= 1'b0;
            m1_dvm_resp <= DVM_RESP_OK;
            m2_dvm_ready <= 1'b1;
            m2_dvm_complete <= 1'b0;
            m2_dvm_resp <= DVM_RESP_OK;
            m3_dvm_ready <= 1'b1;
            m3_dvm_complete <= 1'b0;
            m3_dvm_resp <= DVM_RESP_OK;
        end else begin
            // DVM request enqueueing
            // Master 0 DVM request enqueueing
            if (m0_dvm_valid && m0_dvm_ready && (dvm_queue_count < DVM_QUEUE_DEPTH)) begin
                // Enqueue DVM request
                dvm_queue_addr[dvm_queue_tail] <= m0_dvm_addr;
                dvm_queue_type[dvm_queue_tail] <= m0_dvm_type;
                dvm_queue_asid[dvm_queue_tail] <= m0_dvm_asid;
                dvm_queue_master[dvm_queue_tail] <= 0;
                dvm_queue_valid[dvm_queue_tail] <= 1'b1;
                
                dvm_queue_tail <= (dvm_queue_tail + 1) % DVM_QUEUE_DEPTH;
                dvm_queue_count <= dvm_queue_count + 1;
                
                // Block further requests until queue has space
                if (dvm_queue_count == (DVM_QUEUE_DEPTH - 2)) begin
                    m0_dvm_ready <= 1'b0;
                end
            end
            
            // Master 1 DVM request enqueueing
            if (m1_dvm_valid && m1_dvm_ready && (dvm_queue_count < DVM_QUEUE_DEPTH)) begin
                // Enqueue DVM request
                dvm_queue_addr[dvm_queue_tail] <= m1_dvm_addr;
                dvm_queue_type[dvm_queue_tail] <= m1_dvm_type;
                dvm_queue_asid[dvm_queue_tail] <= m1_dvm_asid;
                dvm_queue_master[dvm_queue_tail] <= 1;
                dvm_queue_valid[dvm_queue_tail] <= 1'b1;
                
                dvm_queue_tail <= (dvm_queue_tail + 1) % DVM_QUEUE_DEPTH;
                dvm_queue_count <= dvm_queue_count + 1;
                
                // Block further requests until queue has space
                if (dvm_queue_count == (DVM_QUEUE_DEPTH - 2)) begin
                    m1_dvm_ready <= 1'b0;
                end
            end
            
            // Master 2 DVM request enqueueing
            if (m2_dvm_valid && m2_dvm_ready && (dvm_queue_count < DVM_QUEUE_DEPTH)) begin
                // Enqueue DVM request
                dvm_queue_addr[dvm_queue_tail] <= m2_dvm_addr;
                dvm_queue_type[dvm_queue_tail] <= m2_dvm_type;
                dvm_queue_asid[dvm_queue_tail] <= m2_dvm_asid;
                dvm_queue_master[dvm_queue_tail] <= 2;
                dvm_queue_valid[dvm_queue_tail] <= 1'b1;
                
                dvm_queue_tail <= (dvm_queue_tail + 1) % DVM_QUEUE_DEPTH;
                dvm_queue_count <= dvm_queue_count + 1;
                
                // Block further requests until queue has space
                if (dvm_queue_count == (DVM_QUEUE_DEPTH - 2)) begin
                    m2_dvm_ready <= 1'b0;
                end
            end
            
            // Master 3 DVM request enqueueing
            if (m3_dvm_valid && m3_dvm_ready && (dvm_queue_count < DVM_QUEUE_DEPTH)) begin
                // Enqueue DVM request
                dvm_queue_addr[dvm_queue_tail] <= m3_dvm_addr;
                dvm_queue_type[dvm_queue_tail] <= m3_dvm_type;
                dvm_queue_asid[dvm_queue_tail] <= m3_dvm_asid;
                dvm_queue_master[dvm_queue_tail] <= 3;
                dvm_queue_valid[dvm_queue_tail] <= 1'b1;
                
                dvm_queue_tail <= (dvm_queue_tail + 1) % DVM_QUEUE_DEPTH;
                dvm_queue_count <= dvm_queue_count + 1;
                
                // Block further requests until queue has space
                if (dvm_queue_count == (DVM_QUEUE_DEPTH - 2)) begin
                    m3_dvm_ready <= 1'b0;
                end
            end
            
            // DVM request dequeuing (handled by state machine)
            if ((dvm_state == DVM_REQUEST) && (dvm_queue_count > 0) && dvm_queue_valid[dvm_queue_head]) begin
                // Dequeue DVM request
                current_dvm_addr <= dvm_queue_addr[dvm_queue_head];
                current_dvm_type <= dvm_queue_type[dvm_queue_head];
                current_dvm_asid <= dvm_queue_asid[dvm_queue_head];
                current_dvm_master <= dvm_queue_master[dvm_queue_head];
                
                dvm_queue_valid[dvm_queue_head] <= 1'b0;
                dvm_queue_head <= (dvm_queue_head + 1) % DVM_QUEUE_DEPTH;
                dvm_queue_count <= dvm_queue_count - 1;
                
                // Re-enable ready signals if queue has space
                if (dvm_queue_count < (DVM_QUEUE_DEPTH - 1)) begin
                    m0_dvm_ready <= 1'b1;
                end
                if (dvm_queue_count < (DVM_QUEUE_DEPTH - 1)) begin
                    m1_dvm_ready <= 1'b1;
                end
                if (dvm_queue_count < (DVM_QUEUE_DEPTH - 1)) begin
                    m2_dvm_ready <= 1'b1;
                end
                if (dvm_queue_count < (DVM_QUEUE_DEPTH - 1)) begin
                    m3_dvm_ready <= 1'b1;
                end
            end
        end
    end

    // DVM Operation State Machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dvm_state <= DVM_IDLE;
            dvm_ack_pending <= {NUM_MASTER{1'b0}};
            dvm_ack_received <= {NUM_MASTER{1'b0}};
            dvm_target_masters <= {NUM_MASTER{1'b0}};
            dvm_timeout_counter <= 16'h0000;
            dvm_timeout_error <= 1'b0;
            dvm_active <= 1'b0;
            dvm_operations <= 32'h00000000;
            dvm_timeouts <= 32'h00000000;
            dvm_error <= {NUM_MASTER{1'b0}};
        end else begin
            case (dvm_state)
                DVM_IDLE: begin
                    dvm_active <= 1'b0;
                    dvm_timeout_counter <= 16'h0000;
                    dvm_timeout_error <= 1'b0;
                    
                    // Check for queued DVM operations
                    if (dvm_queue_count > 0 && dvm_queue_valid[dvm_queue_head]) begin
                        dvm_state <= DVM_REQUEST;
                        dvm_active <= 1'b1;
                    end
                end
                
                DVM_REQUEST: begin
                    // Process the dequeued DVM request
                    dvm_state <= DVM_BROADCAST;
                    dvm_operations <= dvm_operations + 1;
                    
                    // Determine target masters based on DVM type
                    case (current_dvm_type)
                        DVM_TLBI_ALL: begin
                            // Broadcast to all masters except originator
                            dvm_target_masters <= {NUM_MASTER{1'b1}} & ~(1 << current_dvm_master);
                        end
                        
                        DVM_TLBI_ASID: begin
                            // Broadcast to all masters for ASID invalidation
                            dvm_target_masters <= {NUM_MASTER{1'b1}} & ~(1 << current_dvm_master);
                        end
                        
                        DVM_TLBI_VA, DVM_TLBI_VAA: begin
                            // Broadcast to all masters for VA invalidation
                            dvm_target_masters <= {NUM_MASTER{1'b1}} & ~(1 << current_dvm_master);
                        end
                        
                        DVM_SYNC_STATE: begin
                            // Synchronization with all masters
                            dvm_target_masters <= {NUM_MASTER{1'b1}} & ~(1 << current_dvm_master);
                        end
                        
                        default: begin
                            // Unknown DVM type - error
                            dvm_target_masters <= {NUM_MASTER{1'b0}};
                            dvm_state <= DVM_ERROR;
                        end
                    endcase
                end
                
                DVM_BROADCAST: begin
                    // Initiate broadcast to target masters
                    dvm_ack_pending <= dvm_target_masters;
                    dvm_ack_received <= {NUM_MASTER{1'b0}};
                    dvm_timeout_counter <= 16'h0001;
                    
                    if (|dvm_target_masters) begin
                        dvm_state <= DVM_WAIT_ACK;
                    end else begin
                        // No targets - complete immediately
                        dvm_state <= DVM_COMPLETE;
                    end
                end
                
                DVM_WAIT_ACK: begin
                    // Wait for acknowledgments from target masters
                    dvm_timeout_counter <= dvm_timeout_counter + 1;
                    
                    // Simulate acknowledgment reception (placeholder)
                    // In real implementation, this would be connected to actual DVM responses
                    if (dvm_ack_pending[0] && (dvm_timeout_counter > 16'h0100)) begin
                        // Simulate acknowledgment from master 0
                        dvm_ack_received[0] <= 1'b1;
                    end
                    if (dvm_ack_pending[1] && (dvm_timeout_counter > 16'h0100)) begin
                        // Simulate acknowledgment from master 1
                        dvm_ack_received[1] <= 1'b1;
                    end
                    if (dvm_ack_pending[2] && (dvm_timeout_counter > 16'h0100)) begin
                        // Simulate acknowledgment from master 2
                        dvm_ack_received[2] <= 1'b1;
                    end
                    if (dvm_ack_pending[3] && (dvm_timeout_counter > 16'h0100)) begin
                        // Simulate acknowledgment from master 3
                        dvm_ack_received[3] <= 1'b1;
                    end
                    
                    // Check if all acknowledgments received
                    if ((dvm_ack_received & dvm_ack_pending) == dvm_ack_pending) begin
                        // All acknowledgments received
                        if (current_dvm_type == DVM_SYNC) begin
                            dvm_state <= DVM_SYNC_STATE;
                        end else begin
                            dvm_state <= DVM_COMPLETE;
                        end
                    end else if (dvm_timeout_counter > 16'hFF00) begin
                        // Timeout occurred
                        dvm_state <= DVM_TIMEOUT;
                    end
                end
                
                DVM_SYNC_STATE: begin
                    // DVM synchronization phase
                    // Ensure all masters have completed their operations
                    dvm_state <= DVM_COMPLETE;
                end
                
                DVM_COMPLETE: begin
                    // DVM operation completed successfully
                    if (current_dvm_master == 0) begin
                        m0_dvm_complete <= 1'b1;
                        m0_dvm_resp <= DVM_RESP_OK;
                    end
                    if (current_dvm_master == 1) begin
                        m1_dvm_complete <= 1'b1;
                        m1_dvm_resp <= DVM_RESP_OK;
                    end
                    if (current_dvm_master == 2) begin
                        m2_dvm_complete <= 1'b1;
                        m2_dvm_resp <= DVM_RESP_OK;
                    end
                    if (current_dvm_master == 3) begin
                        m3_dvm_complete <= 1'b1;
                        m3_dvm_resp <= DVM_RESP_OK;
                    end
                    
                    dvm_state <= DVM_IDLE;
                    dvm_ack_pending <= {NUM_MASTER{1'b0}};
                    dvm_ack_received <= {NUM_MASTER{1'b0}};
                    dvm_target_masters <= {NUM_MASTER{1'b0}};
                end
                
                DVM_ERROR: begin
                    // DVM operation failed
                    dvm_error[current_dvm_master] <= 1'b1;
                    if (current_dvm_master == 0) begin
                        m0_dvm_complete <= 1'b1;
                        m0_dvm_resp <= DVM_RESP_ERROR;
                    end
                    if (current_dvm_master == 1) begin
                        m1_dvm_complete <= 1'b1;
                        m1_dvm_resp <= DVM_RESP_ERROR;
                    end
                    if (current_dvm_master == 2) begin
                        m2_dvm_complete <= 1'b1;
                        m2_dvm_resp <= DVM_RESP_ERROR;
                    end
                    if (current_dvm_master == 3) begin
                        m3_dvm_complete <= 1'b1;
                        m3_dvm_resp <= DVM_RESP_ERROR;
                    end
                    
                    dvm_state <= DVM_IDLE;
                end
                
                DVM_TIMEOUT: begin
                    // DVM operation timed out
                    dvm_timeout_error <= 1'b1;
                    dvm_timeouts <= dvm_timeouts + 1;
                    dvm_error[current_dvm_master] <= 1'b1;
                    if (current_dvm_master == 0) begin
                        m0_dvm_complete <= 1'b1;
                        m0_dvm_resp <= DVM_RESP_TIMEOUT;
                    end
                    if (current_dvm_master == 1) begin
                        m1_dvm_complete <= 1'b1;
                        m1_dvm_resp <= DVM_RESP_TIMEOUT;
                    end
                    if (current_dvm_master == 2) begin
                        m2_dvm_complete <= 1'b1;
                        m2_dvm_resp <= DVM_RESP_TIMEOUT;
                    end
                    if (current_dvm_master == 3) begin
                        m3_dvm_complete <= 1'b1;
                        m3_dvm_resp <= DVM_RESP_TIMEOUT;
                    end
                    
                    dvm_state <= DVM_IDLE;
                end
                
                default: begin
                    dvm_state <= DVM_IDLE;
                end
            endcase
            
            // Clear completion flags after one cycle
            if (m0_dvm_complete) begin
                m0_dvm_complete <= 1'b0;
            end
            if (m1_dvm_complete) begin
                m1_dvm_complete <= 1'b0;
            end
            if (m2_dvm_complete) begin
                m2_dvm_complete <= 1'b0;
            end
            if (m3_dvm_complete) begin
                m3_dvm_complete <= 1'b0;
            end
            
            // Clear error flags periodically
            if (dvm_timeout_counter[7:0] == 8'h00) begin
                dvm_error <= {NUM_MASTER{1'b0}};
            end
        end
    end

    // DVM Message Validation Function
    function automatic logic dvm_message_valid;
        input [7:0] dvm_type;
        input [WIDTH_AD-1:0] dvm_addr;
        input [15:0] dvm_asid;
        begin
            case (dvm_type)
                DVM_TLBI_ALL: begin
                    // No address or ASID required
                    dvm_message_valid = 1'b1;
                end
                
                DVM_TLBI_ASID: begin
                    // Valid ASID required
                    dvm_message_valid = (dvm_asid != 16'h0000);
                end
                
                DVM_TLBI_VA: begin
                    // Valid virtual address required
                    dvm_message_valid = 1'b1; // All addresses are valid
                end
                
                DVM_TLBI_VAA: begin
                    // Both address and ASID required
                    dvm_message_valid = (dvm_asid != 16'h0000);
                end
                
                DVM_SYNC_STATE: begin
                    // Synchronization is always valid
                    dvm_message_valid = 1'b1;
                end
                
                default: begin
                    // Unknown DVM message type
                    dvm_message_valid = 1'b0;
                end
            endcase
        end
    endfunction

endmodule


//---------------------------------------------------------------------------
// ACE-Lite TLB (Translation Lookaside Buffer) Manager
// Manages TLB invalidation, ASID tracking, and virtual address management
//---------------------------------------------------------------------------
module ace_lite_tlb_manager
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , WIDTH_ID   = 4
              , TLB_ENTRIES = 128)  // TLB entries per master
(
      input  wire                    clk
    , input  wire                    rst_n
    // Master 0 TLB interface
    , input  wire [WIDTH_AD-1:0]    m0_tlb_va         // Virtual address
    , input  wire [15:0]            m0_tlb_asid       // Address Space ID
    , input  wire [2:0]             m0_tlb_op         // TLB operation type
    , input  wire                   m0_tlb_valid      // TLB request valid
    , output reg                    m0_tlb_ready      // TLB request ready
    , output reg                    m0_tlb_complete   // TLB operation complete
    , output reg  [1:0]             m0_tlb_resp       // TLB response
    , output reg  [31:0]            m0_tlb_entries_inv // Entries invalidated
    // Master 1 TLB interface
    , input  wire [WIDTH_AD-1:0]    m1_tlb_va         // Virtual address
    , input  wire [15:0]            m1_tlb_asid       // Address Space ID
    , input  wire [2:0]             m1_tlb_op         // TLB operation type
    , input  wire                   m1_tlb_valid      // TLB request valid
    , output reg                    m1_tlb_ready      // TLB request ready
    , output reg                    m1_tlb_complete   // TLB operation complete
    , output reg  [1:0]             m1_tlb_resp       // TLB response
    , output reg  [31:0]            m1_tlb_entries_inv // Entries invalidated
    // Master 2 TLB interface
    , input  wire [WIDTH_AD-1:0]    m2_tlb_va         // Virtual address
    , input  wire [15:0]            m2_tlb_asid       // Address Space ID
    , input  wire [2:0]             m2_tlb_op         // TLB operation type
    , input  wire                   m2_tlb_valid      // TLB request valid
    , output reg                    m2_tlb_ready      // TLB request ready
    , output reg                    m2_tlb_complete   // TLB operation complete
    , output reg  [1:0]             m2_tlb_resp       // TLB response
    , output reg  [31:0]            m2_tlb_entries_inv // Entries invalidated
    // Master 3 TLB interface
    , input  wire [WIDTH_AD-1:0]    m3_tlb_va         // Virtual address
    , input  wire [15:0]            m3_tlb_asid       // Address Space ID
    , input  wire [2:0]             m3_tlb_op         // TLB operation type
    , input  wire                   m3_tlb_valid      // TLB request valid
    , output reg                    m3_tlb_ready      // TLB request ready
    , output reg                    m3_tlb_complete   // TLB operation complete
    , output reg  [1:0]             m3_tlb_resp       // TLB response
    , output reg  [31:0]            m3_tlb_entries_inv // Entries invalidated
    // Global TLB status outputs
    , output reg                    tlb_invalidation_active  // TLB invalidation in progress
    , output reg  [31:0]            tlb_total_invalidations  // Total invalidations
    , output reg  [31:0]            tlb_entries_per_master [NUM_MASTER-1:0] // Valid entries per master
    , output reg  [NUM_MASTER-1:0] tlb_maintenance_error   // TLB error per master
);

    // TLB Operation Type Definitions
    localparam [2:0] TLB_INV_ALL        = 3'b000;  // Invalidate all entries
    localparam [2:0] TLB_INV_ASID       = 3'b001;  // Invalidate by ASID
    localparam [2:0] TLB_INV_VA         = 3'b010;  // Invalidate by Virtual Address
    localparam [2:0] TLB_INV_VA_ASID    = 3'b011;  // Invalidate by VA and ASID
    localparam [2:0] TLB_INV_RANGE      = 3'b100;  // Invalidate address range
    localparam [2:0] TLB_FLUSH          = 3'b101;  // Flush all entries
    localparam [2:0] TLB_LOOKUP         = 3'b110;  // TLB lookup (read-only)
    localparam [2:0] TLB_SYNC           = 3'b111;  // TLB synchronization

    // TLB Response Types
    localparam [1:0] TLB_RESP_OK        = 2'b00;  // Operation successful
    localparam [1:0] TLB_RESP_ERROR     = 2'b01;  // Operation failed
    localparam [1:0] TLB_RESP_PARTIAL   = 2'b10;  // Partial invalidation
    localparam [1:0] TLB_RESP_TIMEOUT   = 2'b11;  // Operation timed out

    // TLB Entry Structure (per master)
    // Each master maintains its own TLB entries
    reg [WIDTH_AD-13:0] tlb_tag [NUM_MASTER-1:0][TLB_ENTRIES-1:0];     // VA tag (page aligned)
    reg [15:0]          tlb_asid [NUM_MASTER-1:0][TLB_ENTRIES-1:0];    // Address Space ID
    reg                 tlb_valid [NUM_MASTER-1:0][TLB_ENTRIES-1:0];   // Valid bit
    reg [7:0]           tlb_age [NUM_MASTER-1:0][TLB_ENTRIES-1:0];     // Age for replacement
    reg                 tlb_global [NUM_MASTER-1:0][TLB_ENTRIES-1:0];  // Global translation
    
    // TLB Operation State Tracking
    reg [NUM_MASTER-1:0] tlb_op_pending;      // Operations pending per master
    reg [NUM_MASTER-1:0] tlb_op_complete;     // Operations complete per master
    reg [31:0] invalidation_counter [NUM_MASTER-1:0]; // Invalidations per operation
    
    // TLB Maintenance and Invalidation Logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all TLB entries and state
            tlb_invalidation_active <= 1'b0;
            tlb_total_invalidations <= 32'h00000000;
            tlb_maintenance_error <= {NUM_MASTER{1'b0}};
            tlb_op_pending <= {NUM_MASTER{1'b0}};
            tlb_op_complete <= {NUM_MASTER{1'b0}};
            
            // Initialize per-master states
            // Master 0 TLB initialization
            m0_tlb_ready <= 1'b1;
            m0_tlb_complete <= 1'b0;
            m0_tlb_resp <= TLB_RESP_OK;
            m0_tlb_entries_inv <= 32'h00000000;
            tlb_entries_per_master[0] <= 32'h00000000;
            invalidation_counter[0] <= 32'h00000000;
            
            // Clear all TLB entries for master 0
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                tlb_valid[0][k] <= 1'b0;
                tlb_tag[0][k] <= {(WIDTH_AD-12){1'b0}};
                tlb_asid[0][k] <= 16'h0000;
                tlb_age[0][k] <= 8'h00;
                tlb_global[0][k] <= 1'b0;
            end
            
            // Master 1 TLB initialization
            m1_tlb_ready <= 1'b1;
            m1_tlb_complete <= 1'b0;
            m1_tlb_resp <= TLB_RESP_OK;
            m1_tlb_entries_inv <= 32'h00000000;
            tlb_entries_per_master[1] <= 32'h00000000;
            invalidation_counter[1] <= 32'h00000000;
            
            // Clear all TLB entries for master 1
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                tlb_valid[1][k] <= 1'b0;
                tlb_tag[1][k] <= {(WIDTH_AD-12){1'b0}};
                tlb_asid[1][k] <= 16'h0000;
                tlb_age[1][k] <= 8'h00;
                tlb_global[1][k] <= 1'b0;
            end
            
            // Master 2 TLB initialization
            m2_tlb_ready <= 1'b1;
            m2_tlb_complete <= 1'b0;
            m2_tlb_resp <= TLB_RESP_OK;
            m2_tlb_entries_inv <= 32'h00000000;
            tlb_entries_per_master[2] <= 32'h00000000;
            invalidation_counter[2] <= 32'h00000000;
            
            // Clear all TLB entries for master 2
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                tlb_valid[2][k] <= 1'b0;
                tlb_tag[2][k] <= {(WIDTH_AD-12){1'b0}};
                tlb_asid[2][k] <= 16'h0000;
                tlb_age[2][k] <= 8'h00;
                tlb_global[2][k] <= 1'b0;
            end
            
            // Master 3 TLB initialization
            m3_tlb_ready <= 1'b1;
            m3_tlb_complete <= 1'b0;
            m3_tlb_resp <= TLB_RESP_OK;
            m3_tlb_entries_inv <= 32'h00000000;
            tlb_entries_per_master[3] <= 32'h00000000;
            invalidation_counter[3] <= 32'h00000000;
            
            // Clear all TLB entries for master 3
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                tlb_valid[3][k] <= 1'b0;
                tlb_tag[3][k] <= {(WIDTH_AD-12){1'b0}};
                tlb_asid[3][k] <= 16'h0000;
                tlb_age[3][k] <= 8'h00;
                tlb_global[3][k] <= 1'b0;
            end
            
        end else begin
            // Process TLB operations for each master
            // Master 0 TLB operation processing
            if (m0_tlb_valid && m0_tlb_ready) begin
                // Start TLB operation
                tlb_op_pending[0] <= 1'b1;
                m0_tlb_ready <= 1'b0;
                invalidation_counter[0] <= 32'h00000000;
                tlb_invalidation_active <= 1'b1;
                
                case (m0_tlb_op)
                    TLB_INV_ALL: begin
                        // Invalidate all TLB entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[0][k]) begin
                                tlb_valid[0][k] <= 1'b0;
                                invalidation_counter[0] <= invalidation_counter[0] + 1;
                            end
                        end
                        tlb_entries_per_master[0] <= 32'h00000000;
                    end
                    
                    TLB_INV_ASID: begin
                        // Invalidate entries matching ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[0][k] && (tlb_asid[0][k] == m0_tlb_asid) && !tlb_global[0][k]) begin
                                tlb_valid[0][k] <= 1'b0;
                                invalidation_counter[0] <= invalidation_counter[0] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA: begin
                        // Invalidate entries matching Virtual Address
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[0][k] && (tlb_tag[0][k] == m0_tlb_va[WIDTH_AD-1:12])) begin
                                tlb_valid[0][k] <= 1'b0;
                                invalidation_counter[0] <= invalidation_counter[0] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA_ASID: begin
                        // Invalidate entries matching both VA and ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[0][k] && 
                                (tlb_tag[0][k] == m0_tlb_va[WIDTH_AD-1:12]) &&
                                (tlb_asid[0][k] == m0_tlb_asid) && !tlb_global[0][k]) begin
                                tlb_valid[0][k] <= 1'b0;
                                invalidation_counter[0] <= invalidation_counter[0] + 1;
                            end
                        end
                    end
                    
                    TLB_FLUSH: begin
                        // Flush all entries including global ones
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[0][k]) begin
                                tlb_valid[0][k] <= 1'b0;
                                tlb_global[0][k] <= 1'b0;
                                invalidation_counter[0] <= invalidation_counter[0] + 1;
                            end
                        end
                        tlb_entries_per_master[0] <= 32'h00000000;
                    end
                    
                    TLB_LOOKUP: begin
                        // TLB lookup operation (read-only)
                        // Count matching entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[0][k] && 
                                (tlb_tag[0][k] == m0_tlb_va[WIDTH_AD-1:12]) &&
                                ((tlb_asid[0][k] == m0_tlb_asid) || tlb_global[0][k])) begin
                                invalidation_counter[0] <= invalidation_counter[0] + 1;
                            end
                        end
                    end
                    
                    TLB_SYNC: begin
                        // TLB synchronization - no actual operation
                        invalidation_counter[0] <= 32'h00000001;
                    end
                    
                    default: begin
                        // Unknown operation
                        tlb_maintenance_error[0] <= 1'b1;
                        invalidation_counter[0] <= 32'h00000000;
                    end
                endcase
                
            end else if (tlb_op_pending[0] && !tlb_op_complete[0]) begin
                // Complete the TLB operation
                tlb_op_complete[0] <= 1'b1;
                tlb_op_pending[0] <= 1'b0;
                m0_tlb_ready <= 1'b1;
                m0_tlb_complete <= 1'b1;
                m0_tlb_entries_inv <= invalidation_counter[0];
                
                // Update statistics
                tlb_total_invalidations <= tlb_total_invalidations + invalidation_counter[0];
                
                // Set response based on operation result
                if (tlb_maintenance_error[0]) begin
                    m0_tlb_resp <= TLB_RESP_ERROR;
                end else if (invalidation_counter[0] == 0 && m0_tlb_op != TLB_SYNC) begin
                    m0_tlb_resp <= TLB_RESP_PARTIAL;
                end else begin
                    m0_tlb_resp <= TLB_RESP_OK;
                end
                
            end else if (tlb_op_complete[0]) begin
                // Clear completion flag
                tlb_op_complete[0] <= 1'b0;
                m0_tlb_complete <= 1'b0;
                
                // Clear error flag
                tlb_maintenance_error[0] <= 1'b0;
            end
            
            // Update valid entry count for master 0
            tlb_entries_per_master[0] <= 0;
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                if (tlb_valid[0][k]) begin
                    tlb_entries_per_master[0] <= tlb_entries_per_master[0] + 1;
                end
            end
            
            // Master 1 TLB operation processing
            if (m1_tlb_valid && m1_tlb_ready) begin
                // Start TLB operation
                tlb_op_pending[1] <= 1'b1;
                m1_tlb_ready <= 1'b0;
                invalidation_counter[1] <= 32'h00000000;
                tlb_invalidation_active <= 1'b1;
                
                case (m1_tlb_op)
                    TLB_INV_ALL: begin
                        // Invalidate all TLB entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[1][k]) begin
                                tlb_valid[1][k] <= 1'b0;
                                invalidation_counter[1] <= invalidation_counter[1] + 1;
                            end
                        end
                        tlb_entries_per_master[1] <= 32'h00000000;
                    end
                    
                    TLB_INV_ASID: begin
                        // Invalidate entries matching ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[1][k] && (tlb_asid[1][k] == m1_tlb_asid) && !tlb_global[1][k]) begin
                                tlb_valid[1][k] <= 1'b0;
                                invalidation_counter[1] <= invalidation_counter[1] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA: begin
                        // Invalidate entries matching Virtual Address
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[1][k] && (tlb_tag[1][k] == m1_tlb_va[WIDTH_AD-1:12])) begin
                                tlb_valid[1][k] <= 1'b0;
                                invalidation_counter[1] <= invalidation_counter[1] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA_ASID: begin
                        // Invalidate entries matching both VA and ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[1][k] && 
                                (tlb_tag[1][k] == m1_tlb_va[WIDTH_AD-1:12]) &&
                                (tlb_asid[1][k] == m1_tlb_asid) && !tlb_global[1][k]) begin
                                tlb_valid[1][k] <= 1'b0;
                                invalidation_counter[1] <= invalidation_counter[1] + 1;
                            end
                        end
                    end
                    
                    TLB_FLUSH: begin
                        // Flush all entries including global ones
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[1][k]) begin
                                tlb_valid[1][k] <= 1'b0;
                                tlb_global[1][k] <= 1'b0;
                                invalidation_counter[1] <= invalidation_counter[1] + 1;
                            end
                        end
                        tlb_entries_per_master[1] <= 32'h00000000;
                    end
                    
                    TLB_LOOKUP: begin
                        // TLB lookup operation (read-only)
                        // Count matching entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[1][k] && 
                                (tlb_tag[1][k] == m1_tlb_va[WIDTH_AD-1:12]) &&
                                ((tlb_asid[1][k] == m1_tlb_asid) || tlb_global[1][k])) begin
                                invalidation_counter[1] <= invalidation_counter[1] + 1;
                            end
                        end
                    end
                    
                    TLB_SYNC: begin
                        // TLB synchronization - no actual operation
                        invalidation_counter[1] <= 32'h00000001;
                    end
                    
                    default: begin
                        // Unknown operation
                        tlb_maintenance_error[1] <= 1'b1;
                        invalidation_counter[1] <= 32'h00000000;
                    end
                endcase
                
            end else if (tlb_op_pending[1] && !tlb_op_complete[1]) begin
                // Complete the TLB operation
                tlb_op_complete[1] <= 1'b1;
                tlb_op_pending[1] <= 1'b0;
                m1_tlb_ready <= 1'b1;
                m1_tlb_complete <= 1'b1;
                m1_tlb_entries_inv <= invalidation_counter[1];
                
                // Update statistics
                tlb_total_invalidations <= tlb_total_invalidations + invalidation_counter[1];
                
                // Set response based on operation result
                if (tlb_maintenance_error[1]) begin
                    m1_tlb_resp <= TLB_RESP_ERROR;
                end else if (invalidation_counter[1] == 0 && m1_tlb_op != TLB_SYNC) begin
                    m1_tlb_resp <= TLB_RESP_PARTIAL;
                end else begin
                    m1_tlb_resp <= TLB_RESP_OK;
                end
                
            end else if (tlb_op_complete[1]) begin
                // Clear completion flag
                tlb_op_complete[1] <= 1'b0;
                m1_tlb_complete <= 1'b0;
                
                // Clear error flag
                tlb_maintenance_error[1] <= 1'b0;
            end
            
            // Update valid entry count for master 1
            tlb_entries_per_master[1] <= 0;
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                if (tlb_valid[1][k]) begin
                    tlb_entries_per_master[1] <= tlb_entries_per_master[1] + 1;
                end
            end
            
            // Master 2 TLB operation processing
            if (m2_tlb_valid && m2_tlb_ready) begin
                // Start TLB operation
                tlb_op_pending[2] <= 1'b1;
                m2_tlb_ready <= 1'b0;
                invalidation_counter[2] <= 32'h00000000;
                tlb_invalidation_active <= 1'b1;
                
                case (m2_tlb_op)
                    TLB_INV_ALL: begin
                        // Invalidate all TLB entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[2][k]) begin
                                tlb_valid[2][k] <= 1'b0;
                                invalidation_counter[2] <= invalidation_counter[2] + 1;
                            end
                        end
                        tlb_entries_per_master[2] <= 32'h00000000;
                    end
                    
                    TLB_INV_ASID: begin
                        // Invalidate entries matching ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[2][k] && (tlb_asid[2][k] == m2_tlb_asid) && !tlb_global[2][k]) begin
                                tlb_valid[2][k] <= 1'b0;
                                invalidation_counter[2] <= invalidation_counter[2] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA: begin
                        // Invalidate entries matching Virtual Address
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[2][k] && (tlb_tag[2][k] == m2_tlb_va[WIDTH_AD-1:12])) begin
                                tlb_valid[2][k] <= 1'b0;
                                invalidation_counter[2] <= invalidation_counter[2] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA_ASID: begin
                        // Invalidate entries matching both VA and ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[2][k] && 
                                (tlb_tag[2][k] == m2_tlb_va[WIDTH_AD-1:12]) &&
                                (tlb_asid[2][k] == m2_tlb_asid) && !tlb_global[2][k]) begin
                                tlb_valid[2][k] <= 1'b0;
                                invalidation_counter[2] <= invalidation_counter[2] + 1;
                            end
                        end
                    end
                    
                    TLB_FLUSH: begin
                        // Flush all entries including global ones
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[2][k]) begin
                                tlb_valid[2][k] <= 1'b0;
                                tlb_global[2][k] <= 1'b0;
                                invalidation_counter[2] <= invalidation_counter[2] + 1;
                            end
                        end
                        tlb_entries_per_master[2] <= 32'h00000000;
                    end
                    
                    TLB_LOOKUP: begin
                        // TLB lookup operation (read-only)
                        // Count matching entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[2][k] && 
                                (tlb_tag[2][k] == m2_tlb_va[WIDTH_AD-1:12]) &&
                                ((tlb_asid[2][k] == m2_tlb_asid) || tlb_global[2][k])) begin
                                invalidation_counter[2] <= invalidation_counter[2] + 1;
                            end
                        end
                    end
                    
                    TLB_SYNC: begin
                        // TLB synchronization - no actual operation
                        invalidation_counter[2] <= 32'h00000001;
                    end
                    
                    default: begin
                        // Unknown operation
                        tlb_maintenance_error[2] <= 1'b1;
                        invalidation_counter[2] <= 32'h00000000;
                    end
                endcase
                
            end else if (tlb_op_pending[2] && !tlb_op_complete[2]) begin
                // Complete the TLB operation
                tlb_op_complete[2] <= 1'b1;
                tlb_op_pending[2] <= 1'b0;
                m2_tlb_ready <= 1'b1;
                m2_tlb_complete <= 1'b1;
                m2_tlb_entries_inv <= invalidation_counter[2];
                
                // Update statistics
                tlb_total_invalidations <= tlb_total_invalidations + invalidation_counter[2];
                
                // Set response based on operation result
                if (tlb_maintenance_error[2]) begin
                    m2_tlb_resp <= TLB_RESP_ERROR;
                end else if (invalidation_counter[2] == 0 && m2_tlb_op != TLB_SYNC) begin
                    m2_tlb_resp <= TLB_RESP_PARTIAL;
                end else begin
                    m2_tlb_resp <= TLB_RESP_OK;
                end
                
            end else if (tlb_op_complete[2]) begin
                // Clear completion flag
                tlb_op_complete[2] <= 1'b0;
                m2_tlb_complete <= 1'b0;
                
                // Clear error flag
                tlb_maintenance_error[2] <= 1'b0;
            end
            
            // Update valid entry count for master 2
            tlb_entries_per_master[2] <= 0;
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                if (tlb_valid[2][k]) begin
                    tlb_entries_per_master[2] <= tlb_entries_per_master[2] + 1;
                end
            end
            
            // Master 3 TLB operation processing
            if (m3_tlb_valid && m3_tlb_ready) begin
                // Start TLB operation
                tlb_op_pending[3] <= 1'b1;
                m3_tlb_ready <= 1'b0;
                invalidation_counter[3] <= 32'h00000000;
                tlb_invalidation_active <= 1'b1;
                
                case (m3_tlb_op)
                    TLB_INV_ALL: begin
                        // Invalidate all TLB entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[3][k]) begin
                                tlb_valid[3][k] <= 1'b0;
                                invalidation_counter[3] <= invalidation_counter[3] + 1;
                            end
                        end
                        tlb_entries_per_master[3] <= 32'h00000000;
                    end
                    
                    TLB_INV_ASID: begin
                        // Invalidate entries matching ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[3][k] && (tlb_asid[3][k] == m3_tlb_asid) && !tlb_global[3][k]) begin
                                tlb_valid[3][k] <= 1'b0;
                                invalidation_counter[3] <= invalidation_counter[3] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA: begin
                        // Invalidate entries matching Virtual Address
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[3][k] && (tlb_tag[3][k] == m3_tlb_va[WIDTH_AD-1:12])) begin
                                tlb_valid[3][k] <= 1'b0;
                                invalidation_counter[3] <= invalidation_counter[3] + 1;
                            end
                        end
                    end
                    
                    TLB_INV_VA_ASID: begin
                        // Invalidate entries matching both VA and ASID
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[3][k] && 
                                (tlb_tag[3][k] == m3_tlb_va[WIDTH_AD-1:12]) &&
                                (tlb_asid[3][k] == m3_tlb_asid) && !tlb_global[3][k]) begin
                                tlb_valid[3][k] <= 1'b0;
                                invalidation_counter[3] <= invalidation_counter[3] + 1;
                            end
                        end
                    end
                    
                    TLB_FLUSH: begin
                        // Flush all entries including global ones
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[3][k]) begin
                                tlb_valid[3][k] <= 1'b0;
                                tlb_global[3][k] <= 1'b0;
                                invalidation_counter[3] <= invalidation_counter[3] + 1;
                            end
                        end
                        tlb_entries_per_master[3] <= 32'h00000000;
                    end
                    
                    TLB_LOOKUP: begin
                        // TLB lookup operation (read-only)
                        // Count matching entries
                        for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                            if (tlb_valid[3][k] && 
                                (tlb_tag[3][k] == m3_tlb_va[WIDTH_AD-1:12]) &&
                                ((tlb_asid[3][k] == m3_tlb_asid) || tlb_global[3][k])) begin
                                invalidation_counter[3] <= invalidation_counter[3] + 1;
                            end
                        end
                    end
                    
                    TLB_SYNC: begin
                        // TLB synchronization - no actual operation
                        invalidation_counter[3] <= 32'h00000001;
                    end
                    
                    default: begin
                        // Unknown operation
                        tlb_maintenance_error[3] <= 1'b1;
                        invalidation_counter[3] <= 32'h00000000;
                    end
                endcase
                
            end else if (tlb_op_pending[3] && !tlb_op_complete[3]) begin
                // Complete the TLB operation
                tlb_op_complete[3] <= 1'b1;
                tlb_op_pending[3] <= 1'b0;
                m3_tlb_ready <= 1'b1;
                m3_tlb_complete <= 1'b1;
                m3_tlb_entries_inv <= invalidation_counter[3];
                
                // Update statistics
                tlb_total_invalidations <= tlb_total_invalidations + invalidation_counter[3];
                
                // Set response based on operation result
                if (tlb_maintenance_error[3]) begin
                    m3_tlb_resp <= TLB_RESP_ERROR;
                end else if (invalidation_counter[3] == 0 && m3_tlb_op != TLB_SYNC) begin
                    m3_tlb_resp <= TLB_RESP_PARTIAL;
                end else begin
                    m3_tlb_resp <= TLB_RESP_OK;
                end
                
            end else if (tlb_op_complete[3]) begin
                // Clear completion flag
                tlb_op_complete[3] <= 1'b0;
                m3_tlb_complete <= 1'b0;
                
                // Clear error flag
                tlb_maintenance_error[3] <= 1'b0;
            end
            
            // Update valid entry count for master 3
            tlb_entries_per_master[3] <= 0;
            for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                if (tlb_valid[3][k]) begin
                    tlb_entries_per_master[3] <= tlb_entries_per_master[3] + 1;
                end
            end
            
            // Update global TLB invalidation status
            tlb_invalidation_active <= |tlb_op_pending;
            
        end
    end

    // TLB Age Management for LRU Replacement
    // Ages all TLB entries periodically to support replacement
    reg [15:0] age_counter;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            age_counter <= 16'h0000;
        end else begin
            age_counter <= age_counter + 1;
            
            // Age TLB entries every 256 cycles
            if (age_counter[7:0] == 8'h00) begin
                // Age master 0 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[0][k] && tlb_age[0][k] < 8'hFF) begin
                        tlb_age[0][k] <= tlb_age[0][k] + 1;
                    end
                end
                // Age master 1 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[1][k] && tlb_age[1][k] < 8'hFF) begin
                        tlb_age[1][k] <= tlb_age[1][k] + 1;
                    end
                end
                // Age master 2 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[2][k] && tlb_age[2][k] < 8'hFF) begin
                        tlb_age[2][k] <= tlb_age[2][k] + 1;
                    end
                end
                // Age master 3 TLB entries
                for (integer k = 0; k < TLB_ENTRIES; k = k + 1) begin
                    if (tlb_valid[3][k] && tlb_age[3][k] < 8'hFF) begin
                        tlb_age[3][k] <= tlb_age[3][k] + 1;
                    end
                end
            end
        end
    end

    // TLB Statistics and Monitoring
    // Provides visibility into TLB usage and effectiveness
    reg [31:0] tlb_hit_count [NUM_MASTER-1:0];
    reg [31:0] tlb_miss_count [NUM_MASTER-1:0];
    reg [31:0] tlb_access_count [NUM_MASTER-1:0];
    
    // Note: In a real implementation, TLB hits/misses would be tracked
    // based on actual address translation requests from the CPU/masters
    // This is a simplified monitoring framework

endmodule


//---------------------------------------------------------------------------
// ACE-Lite System Coordinator
// Manages system-level coherency, global barriers, and cross-master coordination
//---------------------------------------------------------------------------
module ace_lite_system_coordinator
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , WIDTH_ID   = 4
              , GLOBAL_BARRIER_TIMEOUT = 65536)  // Global barrier timeout cycles
(
      input  wire                    clk
    , input  wire                    rst_n
    // Master 0 system coordination interface
    , input  wire                   m0_barrier_req    // Barrier request
    , input  wire [1:0]             m0_barrier_type   // Barrier type (00=Normal, 01=Memory, 10=Reserved, 11=Sync)
    , input  wire [WIDTH_ID-1:0]    m0_barrier_id     // Barrier transaction ID
    , output reg                    m0_barrier_ack    // Barrier acknowledge
    , output reg                    m0_barrier_stall  // Stall new transactions
    
    , input  wire                   m0_txn_active     // Transaction active
    , input  wire [WIDTH_ID-1:0]    m0_txn_id         // Active transaction ID
    , input  wire [WIDTH_AD-1:0]    m0_txn_addr       // Transaction address
    , input  wire [1:0]             m0_coherency_req  // Coherency requirement
    , output reg                    m0_coherency_grant // Coherency grant
    , output reg                    m0_priority_boost  // Priority boost
    // Master 1 system coordination interface
    , input  wire                   m1_barrier_req    // Barrier request
    , input  wire [1:0]             m1_barrier_type   // Barrier type (00=Normal, 01=Memory, 10=Reserved, 11=Sync)
    , input  wire [WIDTH_ID-1:0]    m1_barrier_id     // Barrier transaction ID
    , output reg                    m1_barrier_ack    // Barrier acknowledge
    , output reg                    m1_barrier_stall  // Stall new transactions
    
    , input  wire                   m1_txn_active     // Transaction active
    , input  wire [WIDTH_ID-1:0]    m1_txn_id         // Active transaction ID
    , input  wire [WIDTH_AD-1:0]    m1_txn_addr       // Transaction address
    , input  wire [1:0]             m1_coherency_req  // Coherency requirement
    , output reg                    m1_coherency_grant // Coherency grant
    , output reg                    m1_priority_boost  // Priority boost
    // Master 2 system coordination interface
    , input  wire                   m2_barrier_req    // Barrier request
    , input  wire [1:0]             m2_barrier_type   // Barrier type (00=Normal, 01=Memory, 10=Reserved, 11=Sync)
    , input  wire [WIDTH_ID-1:0]    m2_barrier_id     // Barrier transaction ID
    , output reg                    m2_barrier_ack    // Barrier acknowledge
    , output reg                    m2_barrier_stall  // Stall new transactions
    
    , input  wire                   m2_txn_active     // Transaction active
    , input  wire [WIDTH_ID-1:0]    m2_txn_id         // Active transaction ID
    , input  wire [WIDTH_AD-1:0]    m2_txn_addr       // Transaction address
    , input  wire [1:0]             m2_coherency_req  // Coherency requirement
    , output reg                    m2_coherency_grant // Coherency grant
    , output reg                    m2_priority_boost  // Priority boost
    // Master 3 system coordination interface
    , input  wire                   m3_barrier_req    // Barrier request
    , input  wire [1:0]             m3_barrier_type   // Barrier type (00=Normal, 01=Memory, 10=Reserved, 11=Sync)
    , input  wire [WIDTH_ID-1:0]    m3_barrier_id     // Barrier transaction ID
    , output reg                    m3_barrier_ack    // Barrier acknowledge
    , output reg                    m3_barrier_stall  // Stall new transactions
    
    , input  wire                   m3_txn_active     // Transaction active
    , input  wire [WIDTH_ID-1:0]    m3_txn_id         // Active transaction ID
    , input  wire [WIDTH_AD-1:0]    m3_txn_addr       // Transaction address
    , input  wire [1:0]             m3_coherency_req  // Coherency requirement
    , output reg                    m3_coherency_grant // Coherency grant
    , output reg                    m3_priority_boost  // Priority boost
    // Global system status outputs
    , output reg                    global_barrier_active   // Global barrier in progress
    , output reg  [31:0]            total_barriers          // Total barrier operations
    , output reg  [31:0]            system_violations       // System-level violations
    , output reg  [NUM_MASTER-1:0] master_stall_status     // Per-master stall status
    , output reg  [31:0]            global_performance_counter // Global performance metric
);

    // System Coordination State Definitions
    localparam [2:0] SYS_IDLE              = 3'b000;  // System idle
    localparam [2:0] SYS_BARRIER_COLLECT   = 3'b001;  // Collecting barrier requests
    localparam [2:0] SYS_BARRIER_SYNC      = 3'b010;  // Synchronizing barriers
    localparam [2:0] SYS_BARRIER_COMPLETE  = 3'b011;  // Completing barriers
    localparam [2:0] SYS_COHERENCY_MANAGE  = 3'b100;  // Managing coherency
    localparam [2:0] SYS_DEADLOCK_RESOLVE  = 3'b101;  // Resolving deadlocks
    localparam [2:0] SYS_ERROR_RECOVERY    = 3'b110;  // Error recovery
    localparam [2:0] SYS_PERFORMANCE_OPT   = 3'b111;  // Performance optimization

    // Barrier Type Definitions
    localparam [1:0] BARRIER_NORMAL        = 2'b00;   // Normal access
    localparam [1:0] BARRIER_MEMORY        = 2'b01;   // Memory barrier
    localparam [1:0] BARRIER_RESERVED      = 2'b10;   // Reserved
    localparam [1:0] BARRIER_SYNC          = 2'b11;   // Synchronization barrier

    // System Coordination State Registers
    reg [2:0] system_state;
    reg [NUM_MASTER-1:0] barrier_requests_pending;
    reg [NUM_MASTER-1:0] barrier_acks_pending;
    reg [NUM_MASTER-1:0] transaction_outstanding;
    reg [15:0] global_barrier_timeout_counter;
    reg global_barrier_timeout_error;
    
    // Global Barrier Coordination Tracking
    reg [1:0] active_barrier_type;
    reg [WIDTH_ID-1:0] barrier_id_tracker [NUM_MASTER-1:0];
    reg [NUM_MASTER-1:0] barrier_participants;
    reg [NUM_MASTER-1:0] barrier_completed;
    
    // Cross-Master Dependency Tracking
    reg [NUM_MASTER-1:0] dependency_matrix [NUM_MASTER-1:0]; // Master dependencies
    reg [NUM_MASTER-1:0] coherency_conflicts;
    reg [15:0] dependency_age [NUM_MASTER-1:0];
    reg [NUM_MASTER-1:0] deadlock_candidates;
    
    // Performance Monitoring and Statistics
    reg [31:0] barrier_latency_accumulator;
    reg [15:0] current_barrier_cycles;
    reg [31:0] coherency_operations;
    reg [31:0] deadlock_resolutions;
    
    // System Coordination State Machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            system_state <= SYS_IDLE;
            barrier_requests_pending <= {NUM_MASTER{1'b0}};
            barrier_acks_pending <= {NUM_MASTER{1'b0}};
            transaction_outstanding <= {NUM_MASTER{1'b0}};
            global_barrier_timeout_counter <= 16'h0000;
            global_barrier_timeout_error <= 1'b0;
            global_barrier_active <= 1'b0;
            
            // Initialize tracking structures
            active_barrier_type <= BARRIER_NORMAL;
            barrier_participants <= {NUM_MASTER{1'b0}};
            barrier_completed <= {NUM_MASTER{1'b0}};
            coherency_conflicts <= {NUM_MASTER{1'b0}};
            deadlock_candidates <= {NUM_MASTER{1'b0}};
            
            // Initialize statistics
            total_barriers <= 32'h00000000;
            system_violations <= 32'h00000000;
            barrier_latency_accumulator <= 32'h00000000;
            current_barrier_cycles <= 16'h0000;
            coherency_operations <= 32'h00000000;
            deadlock_resolutions <= 32'h00000000;
            
            // Initialize per-master states
            // Master 0 initialization
            m0_barrier_ack <= 1'b0;
            m0_barrier_stall <= 1'b0;
            m0_coherency_grant <= 1'b1;
            m0_priority_boost <= 1'b0;
            barrier_id_tracker[0] <= {WIDTH_ID{1'b0}};
            dependency_age[0] <= 16'h0000;
            
            // Clear dependency matrix row 0
            dependency_matrix[0] <= {NUM_MASTER{1'b0}};
            // Master 1 initialization
            m1_barrier_ack <= 1'b0;
            m1_barrier_stall <= 1'b0;
            m1_coherency_grant <= 1'b1;
            m1_priority_boost <= 1'b0;
            barrier_id_tracker[1] <= {WIDTH_ID{1'b0}};
            dependency_age[1] <= 16'h0000;
            
            // Clear dependency matrix row 1
            dependency_matrix[1] <= {NUM_MASTER{1'b0}};
            // Master 2 initialization
            m2_barrier_ack <= 1'b0;
            m2_barrier_stall <= 1'b0;
            m2_coherency_grant <= 1'b1;
            m2_priority_boost <= 1'b0;
            barrier_id_tracker[2] <= {WIDTH_ID{1'b0}};
            dependency_age[2] <= 16'h0000;
            
            // Clear dependency matrix row 2
            dependency_matrix[2] <= {NUM_MASTER{1'b0}};
            // Master 3 initialization
            m3_barrier_ack <= 1'b0;
            m3_barrier_stall <= 1'b0;
            m3_coherency_grant <= 1'b1;
            m3_priority_boost <= 1'b0;
            barrier_id_tracker[3] <= {WIDTH_ID{1'b0}};
            dependency_age[3] <= 16'h0000;
            
            // Clear dependency matrix row 3
            dependency_matrix[3] <= {NUM_MASTER{1'b0}};
            master_stall_status <= {NUM_MASTER{1'b0}};
            global_performance_counter <= 32'h00000000;
            
        end else begin
            case (system_state)
                SYS_IDLE: begin
                    global_barrier_active <= 1'b0;
                    current_barrier_cycles <= 16'h0000;
                    global_barrier_timeout_error <= 1'b0;
                    
                    // Check for barrier requests from any master
                    barrier_requests_pending <= {NUM_MASTER{1'b0}};
                    if (m0_barrier_req) begin
                        barrier_requests_pending[0] <= 1'b1;
                        barrier_id_tracker[0] <= m0_barrier_id;
                        active_barrier_type <= m0_barrier_type;
                    end
                    if (m1_barrier_req) begin
                        barrier_requests_pending[1] <= 1'b1;
                        barrier_id_tracker[1] <= m1_barrier_id;
                        active_barrier_type <= m1_barrier_type;
                    end
                    if (m2_barrier_req) begin
                        barrier_requests_pending[2] <= 1'b1;
                        barrier_id_tracker[2] <= m2_barrier_id;
                        active_barrier_type <= m2_barrier_type;
                    end
                    if (m3_barrier_req) begin
                        barrier_requests_pending[3] <= 1'b1;
                        barrier_id_tracker[3] <= m3_barrier_id;
                        active_barrier_type <= m3_barrier_type;
                    end
                    
                    // Transition to barrier collection if any requests
                    if (|barrier_requests_pending) begin
                        system_state <= SYS_BARRIER_COLLECT;
                        global_barrier_active <= 1'b1;
                        total_barriers <= total_barriers + 1;
                    end else if (|coherency_conflicts) begin
                        system_state <= SYS_COHERENCY_MANAGE;
                    end else if (|deadlock_candidates) begin
                        system_state <= SYS_DEADLOCK_RESOLVE;
                    end
                end
                
                SYS_BARRIER_COLLECT: begin
                    // Collect barrier requests and determine participants
                    current_barrier_cycles <= current_barrier_cycles + 1;
                    global_barrier_timeout_counter <= global_barrier_timeout_counter + 1;
                    
                    // Determine barrier participants based on barrier type
                    case (active_barrier_type)
                        BARRIER_MEMORY: begin
                            // Memory barriers affect all masters with outstanding transactions
                            barrier_participants <= transaction_outstanding;
                        end
                        
                        BARRIER_SYNC: begin
                            // Sync barriers affect all masters
                            barrier_participants <= {NUM_MASTER{1'b1}};
                        end
                        
                        default: begin
                            // Normal barriers only affect requesting masters
                            barrier_participants <= barrier_requests_pending;
                        end
                    endcase
                    
                    system_state <= SYS_BARRIER_SYNC;
                end
                
                SYS_BARRIER_SYNC: begin
                    // Synchronize barrier across all participants
                    current_barrier_cycles <= current_barrier_cycles + 1;
                    global_barrier_timeout_counter <= global_barrier_timeout_counter + 1;
                    
                    // Stall new transactions on participating masters
                    m0_barrier_stall <= barrier_participants[0];
                    master_stall_status[0] <= barrier_participants[0];
                    
                    // Check if master 0 has completed its part
                    if (barrier_participants[0] && !m0_txn_active) begin
                        barrier_completed[0] <= 1'b1;
                    end
                    m1_barrier_stall <= barrier_participants[1];
                    master_stall_status[1] <= barrier_participants[1];
                    
                    // Check if master 1 has completed its part
                    if (barrier_participants[1] && !m1_txn_active) begin
                        barrier_completed[1] <= 1'b1;
                    end
                    m2_barrier_stall <= barrier_participants[2];
                    master_stall_status[2] <= barrier_participants[2];
                    
                    // Check if master 2 has completed its part
                    if (barrier_participants[2] && !m2_txn_active) begin
                        barrier_completed[2] <= 1'b1;
                    end
                    m3_barrier_stall <= barrier_participants[3];
                    master_stall_status[3] <= barrier_participants[3];
                    
                    // Check if master 3 has completed its part
                    if (barrier_participants[3] && !m3_txn_active) begin
                        barrier_completed[3] <= 1'b1;
                    end
                    
                    // Check if all participants have completed
                    if ((barrier_completed & barrier_participants) == barrier_participants) begin
                        system_state <= SYS_BARRIER_COMPLETE;
                    end else if (global_barrier_timeout_counter > GLOBAL_BARRIER_TIMEOUT) begin
                        // Barrier timeout
                        global_barrier_timeout_error <= 1'b1;
                        system_violations <= system_violations + 1;
                        system_state <= SYS_ERROR_RECOVERY;
                    end
                end
                
                SYS_BARRIER_COMPLETE: begin
                    // Complete barrier operation
                    current_barrier_cycles <= current_barrier_cycles + 1;
                    
                    // Send acknowledgments to requesting masters
                    if (barrier_requests_pending[0]) begin
                        m0_barrier_ack <= 1'b1;
                        m0_barrier_stall <= 1'b0;
                    end
                    if (barrier_requests_pending[1]) begin
                        m1_barrier_ack <= 1'b1;
                        m1_barrier_stall <= 1'b0;
                    end
                    if (barrier_requests_pending[2]) begin
                        m2_barrier_ack <= 1'b1;
                        m2_barrier_stall <= 1'b0;
                    end
                    if (barrier_requests_pending[3]) begin
                        m3_barrier_ack <= 1'b1;
                        m3_barrier_stall <= 1'b0;
                    end
                    
                    // Update performance statistics
                    barrier_latency_accumulator <= barrier_latency_accumulator + current_barrier_cycles;
                    
                    // Clear barrier state and return to idle
                    barrier_requests_pending <= {NUM_MASTER{1'b0}};
                    barrier_participants <= {NUM_MASTER{1'b0}};
                    barrier_completed <= {NUM_MASTER{1'b0}};
                    master_stall_status <= {NUM_MASTER{1'b0}};
                    global_barrier_timeout_counter <= 16'h0000;
                    
                    system_state <= SYS_IDLE;
                end
                
                SYS_COHERENCY_MANAGE: begin
                    // Manage coherency conflicts between masters
                    coherency_operations <= coherency_operations + 1;
                    // Handle coherency for master 0
                    if (coherency_conflicts[0]) begin
                        // Grant coherency based on priority or fairness
                        if (dependency_age[0] > 16'hF000) begin
                            m0_coherency_grant <= 1'b1;
                            m0_priority_boost <= 1'b1;
                            coherency_conflicts[0] <= 1'b0;
                        end else begin
                            m0_coherency_grant <= 1'b0;
                        end
                    end else begin
                        m0_coherency_grant <= 1'b1;
                        m0_priority_boost <= 1'b0;
                    end
                    // Handle coherency for master 1
                    if (coherency_conflicts[1]) begin
                        // Grant coherency based on priority or fairness
                        if (dependency_age[1] > 16'hF000) begin
                            m1_coherency_grant <= 1'b1;
                            m1_priority_boost <= 1'b1;
                            coherency_conflicts[1] <= 1'b0;
                        end else begin
                            m1_coherency_grant <= 1'b0;
                        end
                    end else begin
                        m1_coherency_grant <= 1'b1;
                        m1_priority_boost <= 1'b0;
                    end
                    // Handle coherency for master 2
                    if (coherency_conflicts[2]) begin
                        // Grant coherency based on priority or fairness
                        if (dependency_age[2] > 16'hF000) begin
                            m2_coherency_grant <= 1'b1;
                            m2_priority_boost <= 1'b1;
                            coherency_conflicts[2] <= 1'b0;
                        end else begin
                            m2_coherency_grant <= 1'b0;
                        end
                    end else begin
                        m2_coherency_grant <= 1'b1;
                        m2_priority_boost <= 1'b0;
                    end
                    // Handle coherency for master 3
                    if (coherency_conflicts[3]) begin
                        // Grant coherency based on priority or fairness
                        if (dependency_age[3] > 16'hF000) begin
                            m3_coherency_grant <= 1'b1;
                            m3_priority_boost <= 1'b1;
                            coherency_conflicts[3] <= 1'b0;
                        end else begin
                            m3_coherency_grant <= 1'b0;
                        end
                    end else begin
                        m3_coherency_grant <= 1'b1;
                        m3_priority_boost <= 1'b0;
                    end
                    
                    // Return to idle when no conflicts remain
                    if (!|coherency_conflicts) begin
                        system_state <= SYS_IDLE;
                    end
                end
                
                SYS_DEADLOCK_RESOLVE: begin
                    // Resolve potential deadlocks
                    deadlock_resolutions <= deadlock_resolutions + 1;
                    
                    // Apply priority boosting to resolve deadlocks
                    if (deadlock_candidates[0]) begin
                        m0_priority_boost <= 1'b1;
                        m0_coherency_grant <= 1'b1;
                        deadlock_candidates[0] <= 1'b0;
                    end
                    if (deadlock_candidates[1]) begin
                        m1_priority_boost <= 1'b1;
                        m1_coherency_grant <= 1'b1;
                        deadlock_candidates[1] <= 1'b0;
                    end
                    if (deadlock_candidates[2]) begin
                        m2_priority_boost <= 1'b1;
                        m2_coherency_grant <= 1'b1;
                        deadlock_candidates[2] <= 1'b0;
                    end
                    if (deadlock_candidates[3]) begin
                        m3_priority_boost <= 1'b1;
                        m3_coherency_grant <= 1'b1;
                        deadlock_candidates[3] <= 1'b0;
                    end
                    
                    system_state <= SYS_IDLE;
                end
                
                SYS_ERROR_RECOVERY: begin
                    // Recover from system-level errors
                    system_violations <= system_violations + 1;
                    
                    // Clear all barrier states and stalls
                    barrier_requests_pending <= {NUM_MASTER{1'b0}};
                    barrier_participants <= {NUM_MASTER{1'b0}};
                    barrier_completed <= {NUM_MASTER{1'b0}};
                    master_stall_status <= {NUM_MASTER{1'b0}};
                    
                    m0_barrier_ack <= 1'b0;
                    m0_barrier_stall <= 1'b0;
                    m0_coherency_grant <= 1'b1;
                    m0_priority_boost <= 1'b0;
                    m1_barrier_ack <= 1'b0;
                    m1_barrier_stall <= 1'b0;
                    m1_coherency_grant <= 1'b1;
                    m1_priority_boost <= 1'b0;
                    m2_barrier_ack <= 1'b0;
                    m2_barrier_stall <= 1'b0;
                    m2_coherency_grant <= 1'b1;
                    m2_priority_boost <= 1'b0;
                    m3_barrier_ack <= 1'b0;
                    m3_barrier_stall <= 1'b0;
                    m3_coherency_grant <= 1'b1;
                    m3_priority_boost <= 1'b0;
                    
                    system_state <= SYS_IDLE;
                end
                
                SYS_PERFORMANCE_OPT: begin
                    // Performance optimization mode (placeholder)
                    system_state <= SYS_IDLE;
                end
                
                default: begin
                    system_state <= SYS_IDLE;
                end
            endcase
            
            // Update dependency ages and detect deadlocks
            // Master 0 dependency tracking
            if (m0_txn_active) begin
                transaction_outstanding[0] <= 1'b1;
                if (dependency_age[0] < 16'hFFFF) begin
                    dependency_age[0] <= dependency_age[0] + 1;
                end
                
                // Detect potential deadlock
                if (dependency_age[0] > 16'hFF00) begin
                    deadlock_candidates[0] <= 1'b1;
                end
            end else begin
                transaction_outstanding[0] <= 1'b0;
                dependency_age[0] <= 16'h0000;
                deadlock_candidates[0] <= 1'b0;
            end
            
            // Update coherency conflicts
            if (m0_coherency_req != 2'b00 && !m0_coherency_grant) begin
                coherency_conflicts[0] <= 1'b1;
            end else begin
                coherency_conflicts[0] <= 1'b0;
            end
            
            // Clear acknowledgments after one cycle
            if (m0_barrier_ack) begin
                m0_barrier_ack <= 1'b0;
            end
            
            // Master 1 dependency tracking
            if (m1_txn_active) begin
                transaction_outstanding[1] <= 1'b1;
                if (dependency_age[1] < 16'hFFFF) begin
                    dependency_age[1] <= dependency_age[1] + 1;
                end
                
                // Detect potential deadlock
                if (dependency_age[1] > 16'hFF00) begin
                    deadlock_candidates[1] <= 1'b1;
                end
            end else begin
                transaction_outstanding[1] <= 1'b0;
                dependency_age[1] <= 16'h0000;
                deadlock_candidates[1] <= 1'b0;
            end
            
            // Update coherency conflicts
            if (m1_coherency_req != 2'b00 && !m1_coherency_grant) begin
                coherency_conflicts[1] <= 1'b1;
            end else begin
                coherency_conflicts[1] <= 1'b0;
            end
            
            // Clear acknowledgments after one cycle
            if (m1_barrier_ack) begin
                m1_barrier_ack <= 1'b0;
            end
            
            // Master 2 dependency tracking
            if (m2_txn_active) begin
                transaction_outstanding[2] <= 1'b1;
                if (dependency_age[2] < 16'hFFFF) begin
                    dependency_age[2] <= dependency_age[2] + 1;
                end
                
                // Detect potential deadlock
                if (dependency_age[2] > 16'hFF00) begin
                    deadlock_candidates[2] <= 1'b1;
                end
            end else begin
                transaction_outstanding[2] <= 1'b0;
                dependency_age[2] <= 16'h0000;
                deadlock_candidates[2] <= 1'b0;
            end
            
            // Update coherency conflicts
            if (m2_coherency_req != 2'b00 && !m2_coherency_grant) begin
                coherency_conflicts[2] <= 1'b1;
            end else begin
                coherency_conflicts[2] <= 1'b0;
            end
            
            // Clear acknowledgments after one cycle
            if (m2_barrier_ack) begin
                m2_barrier_ack <= 1'b0;
            end
            
            // Master 3 dependency tracking
            if (m3_txn_active) begin
                transaction_outstanding[3] <= 1'b1;
                if (dependency_age[3] < 16'hFFFF) begin
                    dependency_age[3] <= dependency_age[3] + 1;
                end
                
                // Detect potential deadlock
                if (dependency_age[3] > 16'hFF00) begin
                    deadlock_candidates[3] <= 1'b1;
                end
            end else begin
                transaction_outstanding[3] <= 1'b0;
                dependency_age[3] <= 16'h0000;
                deadlock_candidates[3] <= 1'b0;
            end
            
            // Update coherency conflicts
            if (m3_coherency_req != 2'b00 && !m3_coherency_grant) begin
                coherency_conflicts[3] <= 1'b1;
            end else begin
                coherency_conflicts[3] <= 1'b0;
            end
            
            // Clear acknowledgments after one cycle
            if (m3_barrier_ack) begin
                m3_barrier_ack <= 1'b0;
            end
            
            // Update global performance counter
            global_performance_counter <= global_performance_counter + 1;
            
        end
    end

    // System Health Monitoring
    // Tracks system-wide metrics and health indicators
    reg [31:0] system_efficiency_metric;
    reg [15:0] average_barrier_latency;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            system_efficiency_metric <= 32'h64646464; // Start at 100% efficiency
            average_barrier_latency <= 16'h0000;
        end else begin
            // Update efficiency based on stalls and violations
            if (|master_stall_status) begin
                if (system_efficiency_metric > 32'h00000000) begin
                    system_efficiency_metric <= system_efficiency_metric - 1;
                end
            end else if (system_efficiency_metric < 32'h64646464) begin
                system_efficiency_metric <= system_efficiency_metric + 1;
            end
            
            // Calculate average barrier latency
            if (total_barriers > 0) begin
                average_barrier_latency <= barrier_latency_accumulator / total_barriers;
            end
        end
    end

endmodule


//---------------------------------------------------------------------------
// ACE-Lite Signal Arbiter
// Resolves signal conflicts between multiple coherency modules
//---------------------------------------------------------------------------
module ace_lite_signal_arbiter
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_ID   = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32)
(
      input  wire                       clk
    , input  wire                       rst_n
    
    // Input signals from coherency controller
    , input  wire                       coherency_ctrl_active
    , input  wire                       coherency_ctrl_snoop_broadcast
    , input  wire [NUM_MASTER-1:0]      coherency_ctrl_master_coherent
    
    // Input signals from DVM controller
    , input  wire                       dvm_ctrl_active
    , input  wire                       dvm_ctrl_broadcast
    , input  wire [NUM_MASTER-1:0]      dvm_ctrl_master_sync
    
    // Input signals from system coordinator
    , input  wire                       sys_coord_active
    , input  wire                       sys_coord_barrier
    , input  wire [NUM_MASTER-1:0]      sys_coord_master_sync
    
    // Input signals from cache operations
    , input  wire                       cache_ops_active
    , input  wire [NUM_MASTER-1:0]      cache_ops_master_maint
    
    // Input signals from exclusive monitor
    , input  wire                       exclusive_mon_active
    , input  wire [NUM_MASTER-1:0]      exclusive_mon_master_exclusive
    
    // Arbitrated output signals (single drivers)
    , output reg                        coherency_active
    , output reg                        snoop_broadcast_active
    , output reg  [NUM_MASTER-1:0]      master_coherent_transaction
    , output reg                        barrier_active
    , output reg                        dvm_operation_active
    , output reg  [NUM_MASTER-1:0]      master_sync_required
    , output reg                        cache_maintenance_active
    , output reg  [NUM_MASTER-1:0]      exclusive_access_active
    , output reg  [2:0]                 active_module_id
    , output reg                        conflict_detected
    
);

    // Active module ID encodings
    localparam [2:0] MODULE_IDLE         = 3'b000;
    localparam [2:0] MODULE_COHERENCY    = 3'b001;
    localparam [2:0] MODULE_DVM          = 3'b010;
    localparam [2:0] MODULE_SYSTEM       = 3'b011;
    localparam [2:0] MODULE_CACHE_OPS    = 3'b100;
    localparam [2:0] MODULE_EXCLUSIVE    = 3'b101;
    localparam [2:0] MODULE_CONFLICT     = 3'b111;

    // Module priority encoding (0 = highest priority)
    wire [2:0] module_priority [0:5];
    assign module_priority[0] = 3'd0;  // DVM (highest priority)
    assign module_priority[1] = 3'd1;  // System coordinator
    assign module_priority[2] = 3'd2;  // Coherency controller
    assign module_priority[3] = 3'd3;  // Cache operations
    assign module_priority[4] = 3'd4;  // Exclusive monitor
    assign module_priority[5] = 3'd7;  // Idle (lowest priority)

    // Signal arbitration logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            coherency_active <= 1'b0;
            snoop_broadcast_active <= 1'b0;
            master_coherent_transaction <= {NUM_MASTER{1'b0}};
            barrier_active <= 1'b0;
            dvm_operation_active <= 1'b0;
            master_sync_required <= {NUM_MASTER{1'b0}};
            cache_maintenance_active <= 1'b0;
            exclusive_access_active <= {NUM_MASTER{1'b0}};
            active_module_id <= MODULE_IDLE;
            conflict_detected <= 1'b0;
        end else begin
            
            // Conflict detection
            reg [4:0] active_modules;
            active_modules = {exclusive_mon_active, cache_ops_active, sys_coord_active, dvm_ctrl_active, coherency_ctrl_active};
            conflict_detected <= (active_modules != 5'b00000) && (active_modules & (active_modules - 1)) != 5'b00000;
            
            // Priority-based arbitration
            if (dvm_ctrl_active) begin
                // DVM controller has highest priority
                active_module_id <= MODULE_DVM;
                coherency_active <= dvm_ctrl_active;
                snoop_broadcast_active <= dvm_ctrl_broadcast;
                master_coherent_transaction <= dvm_ctrl_master_sync;
                barrier_active <= 1'b0;
                dvm_operation_active <= dvm_ctrl_active;
                master_sync_required <= dvm_ctrl_master_sync;
                cache_maintenance_active <= 1'b0;
                exclusive_access_active <= {NUM_MASTER{1'b0}};
            end else if (sys_coord_active) begin
                // System coordinator has second priority
                active_module_id <= MODULE_SYSTEM;
                coherency_active <= sys_coord_active;
                snoop_broadcast_active <= 1'b0;
                master_coherent_transaction <= sys_coord_master_sync;
                barrier_active <= sys_coord_barrier;
                dvm_operation_active <= 1'b0;
                master_sync_required <= sys_coord_master_sync;
                cache_maintenance_active <= 1'b0;
                exclusive_access_active <= {NUM_MASTER{1'b0}};
            end else if (coherency_ctrl_active) begin
                // Coherency controller has third priority
                active_module_id <= MODULE_COHERENCY;
                coherency_active <= coherency_ctrl_active;
                snoop_broadcast_active <= coherency_ctrl_snoop_broadcast;
                master_coherent_transaction <= coherency_ctrl_master_coherent;
                barrier_active <= 1'b0;
                dvm_operation_active <= 1'b0;
                master_sync_required <= {NUM_MASTER{1'b0}};
                cache_maintenance_active <= 1'b0;
                exclusive_access_active <= {NUM_MASTER{1'b0}};
            end else if (cache_ops_active) begin
                // Cache operations has fourth priority
                active_module_id <= MODULE_CACHE_OPS;
                coherency_active <= cache_ops_active;
                snoop_broadcast_active <= 1'b0;
                master_coherent_transaction <= cache_ops_master_maint;
                barrier_active <= 1'b0;
                dvm_operation_active <= 1'b0;
                master_sync_required <= {NUM_MASTER{1'b0}};
                cache_maintenance_active <= cache_ops_active;
                exclusive_access_active <= {NUM_MASTER{1'b0}};
            end else if (exclusive_mon_active) begin
                // Exclusive monitor has lowest priority
                active_module_id <= MODULE_EXCLUSIVE;
                coherency_active <= exclusive_mon_active;
                snoop_broadcast_active <= 1'b0;
                master_coherent_transaction <= exclusive_mon_master_exclusive;
                barrier_active <= 1'b0;
                dvm_operation_active <= 1'b0;
                master_sync_required <= {NUM_MASTER{1'b0}};
                cache_maintenance_active <= 1'b0;
                exclusive_access_active <= exclusive_mon_master_exclusive;
            end else begin
                // All modules idle
                active_module_id <= MODULE_IDLE;
                coherency_active <= 1'b0;
                snoop_broadcast_active <= 1'b0;
                master_coherent_transaction <= {NUM_MASTER{1'b0}};
                barrier_active <= 1'b0;
                dvm_operation_active <= 1'b0;
                master_sync_required <= {NUM_MASTER{1'b0}};
                cache_maintenance_active <= 1'b0;
                exclusive_access_active <= {NUM_MASTER{1'b0}};
            end
        end
    end

endmodule

