        , .m1_arready(M1_ARREADY)
        , .m1_bvalid(M1_BVALID)
        , .m1_bready(M1_BREADY)
        , .m1_rvalid(M1_RVALID)
        , .m1_rready(M1_RREADY)
        , .m1_rlast(M1_RLAST)
        , .m2_awbar(M2_AWBAR)
        , .m2_arbar(M2_ARBAR)
        , .m2_awvalid(M2_AWVALID)
        , .m2_awready(M2_AWREADY)
        , .m2_arvalid(M2_ARVALID)
        , .m2_arready(M2_ARREADY)
        , .m2_bvalid(M2_BVALID)
        , .m2_bready(M2_BREADY)
        , .m2_rvalid(M2_RVALID)
        , .m2_rready(M2_RREADY)
        , .m2_rlast(M2_RLAST)
        , .m3_awbar(M3_AWBAR)
        , .m3_arbar(M3_ARBAR)
        , .m3_awvalid(M3_AWVALID)
        , .m3_awready(M3_AWREADY)
        , .m3_arvalid(M3_ARVALID)
        , .m3_arready(M3_ARREADY)
        , .m3_bvalid(M3_BVALID)
        , .m3_bready(M3_BREADY)
        , .m3_rvalid(M3_RVALID)
        , .m3_rready(M3_RREADY)
        , .m3_rlast(M3_RLAST)
        , .barrier_enable(barrier_enable)
        , .global_barrier_request(1'b0)
        , .master_barrier_override({NUM_MASTER{1'b0}})
        , .barrier_active(barrier_active_per_master)
        , .barrier_block(barrier_block)
        , .global_barrier_active(global_barrier_active)
        , .barrier_timeout(barrier_timeout)
        , .pending_transactions(pending_transactions)
    );

    // Instantiate ACE-Lite Domain Manager
    ace_lite_domain_manager domain_mgr (
          .clk(ACLK)
        , .rst_n(ARESETn)
        , .m0_awaddr(M0_AWADDR)
        , .m0_awdomain(M0_AWDOMAIN)
        , .m0_awsnoop(M0_AWSNOOP)
        , .m0_awvalid(M0_AWVALID)
        , .m0_araddr(M0_ARADDR)
        , .m0_ardomain(M0_ARDOMAIN)
        , .m0_arsnoop(M0_ARSNOOP)
        , .m0_arvalid(M0_ARVALID)
        , .m1_awaddr(M1_AWADDR)
        , .m1_awdomain(M1_AWDOMAIN)
        , .m1_awsnoop(M1_AWSNOOP)
        , .m1_awvalid(M1_AWVALID)
        , .m1_araddr(M1_ARADDR)
        , .m1_ardomain(M1_ARDOMAIN)
        , .m1_arsnoop(M1_ARSNOOP)
        , .m1_arvalid(M1_ARVALID)
        , .m2_awaddr(M2_AWADDR)
        , .m2_awdomain(M2_AWDOMAIN)
        , .m2_awsnoop(M2_AWSNOOP)
        , .m2_awvalid(M2_AWVALID)
        , .m2_araddr(M2_ARADDR)
        , .m2_ardomain(M2_ARDOMAIN)
        , .m2_arsnoop(M2_ARSNOOP)
        , .m2_arvalid(M2_ARVALID)
        , .m3_awaddr(M3_AWADDR)
        , .m3_awdomain(M3_AWDOMAIN)
        , .m3_awsnoop(M3_AWSNOOP)
        , .m3_awvalid(M3_AWVALID)
        , .m3_araddr(M3_ARADDR)
        , .m3_ardomain(M3_ARDOMAIN)
        , .m3_arsnoop(M3_ARSNOOP)
        , .m3_arvalid(M3_ARVALID)
        , .domain_base_addr('{32'h0000_0000, 32'h1000_0000, 32'h2000_0000, 32'h3000_0000})
        , .domain_addr_mask('{32'hF000_0000, 32'hF000_0000, 32'hF000_0000, 32'hF000_0000})
        , .domain_enable(4'b1111)
        , .domain_type('{2'b00, 2'b01, 2'b10, 2'b11})
        , .master_domain_membership('{4'hF, 4'hF, 4'hF, 4'hF})
        , .resolved_awdomain(resolved_awdomain)
        , .resolved_ardomain(resolved_ardomain)
        , .domain_active(domain_active)
        , .coherency_required(coherency_required)
        , .domain_violation(domain_violation)
        , .domain_transaction_count(domain_transaction_count)
    );

    // Instantiate ACE-Lite Cache Operations
    ace_lite_cache_ops cache_ops (
          .clk(ACLK)
        , .rst_n(ARESETn)
        , .m0_awid(M0_AWID)
        , .m0_awaddr(M0_AWADDR)
        , .m0_awsnoop(M0_AWSNOOP)
        , .m0_awdomain(M0_AWDOMAIN)
        , .m0_awvalid(M0_AWVALID)
        , .m0_awready(M0_AWREADY)
        , .m0_arid(M0_ARID)
        , .m0_araddr(M0_ARADDR)
        , .m0_arsnoop(M0_ARSNOOP)
        , .m0_ardomain(M0_ARDOMAIN)
        , .m0_arvalid(M0_ARVALID)
        , .m0_arready(M0_ARREADY)
        , .m1_awid(M1_AWID)
        , .m1_awaddr(M1_AWADDR)
        , .m1_awsnoop(M1_AWSNOOP)
        , .m1_awdomain(M1_AWDOMAIN)
        , .m1_awvalid(M1_AWVALID)
        , .m1_awready(M1_AWREADY)
        , .m1_arid(M1_ARID)
        , .m1_araddr(M1_ARADDR)
        , .m1_arsnoop(M1_ARSNOOP)
        , .m1_ardomain(M1_ARDOMAIN)
        , .m1_arvalid(M1_ARVALID)
        , .m1_arready(M1_ARREADY)
        , .m2_awid(M2_AWID)
        , .m2_awaddr(M2_AWADDR)
        , .m2_awsnoop(M2_AWSNOOP)
        , .m2_awdomain(M2_AWDOMAIN)
        , .m2_awvalid(M2_AWVALID)
        , .m2_awready(M2_AWREADY)
        , .m2_arid(M2_ARID)
        , .m2_araddr(M2_ARADDR)
        , .m2_arsnoop(M2_ARSNOOP)
        , .m2_ardomain(M2_ARDOMAIN)
        , .m2_arvalid(M2_ARVALID)
        , .m2_arready(M2_ARREADY)
        , .m3_awid(M3_AWID)
        , .m3_awaddr(M3_AWADDR)
        , .m3_awsnoop(M3_AWSNOOP)
        , .m3_awdomain(M3_AWDOMAIN)
        , .m3_awvalid(M3_AWVALID)
        , .m3_awready(M3_AWREADY)
        , .m3_arid(M3_ARID)
        , .m3_araddr(M3_ARADDR)
        , .m3_arsnoop(M3_ARSNOOP)
        , .m3_ardomain(M3_ARDOMAIN)
        , .m3_arvalid(M3_ARVALID)
        , .m3_arready(M3_ARREADY)
        , .cache_ops_enable(cache_ops_enable)
        , .cache_maint_bypass(1'b0)
        , .cache_base_addr(32'h0000_0000)
        , .cache_size(32'h1000_0000)
        , .cache_line_size(8'd64)
        , .cache_op_active(cache_op_active)
        , .cache_maint_required(cache_maint_required)
        , .cache_op_type(cache_op_type)
        , .cache_op_addr(cache_op_addr)
        , .cache_op_pending_count(cache_op_pending_count)
        , .cache_clean_count(cache_clean_count)
        , .cache_invalidate_count(cache_invalidate_count)
        , .maint_timeout_enable(1'b0)
        , .maint_timeout_cycles(16'h1000)
        , .maint_completion_tracking(1'b0)
        , .maint_conflict_resolution(1'b0)
        , .maint_priority_level({MAINT_PRIORITY_WIDTH{1'b0}})
        , .maint_queuing_enable(1'b0)
        , .maint_scheduling_enable(1'b0)
        , .maint_completion_count() // output, left unconnected
        , .maint_timeout_count() // output, left unconnected
        , .maint_error_count() // output, left unconnected
        , .maint_conflict_detected() // output, left unconnected
        , .maint_operation_complete() // output, left unconnected
        , .maint_current_priority() // output, left unconnected
        , .maint_queue_depth() // output, left unconnected
    );

    // Default ACE acknowledgment signals - tie off for non-ACE slaves
    assign S0_RACK = 1'b1;  // Always acknowledge read requests
    assign S0_WACK = 1'b1;  // Always acknowledge write requests
    assign S1_RACK = 1'b1;  // Always acknowledge read requests
    assign S1_WACK = 1'b1;  // Always acknowledge write requests
    assign S2_RACK = 1'b1;  // Always acknowledge read requests
    assign S2_WACK = 1'b1;  // Always acknowledge write requests
    assign S3_RACK = 1'b1;  // Always acknowledge read requests
    assign S3_WACK = 1'b1;  // Always acknowledge write requests

    // ACE-Lite interconnect components provide complete AXI4 + coherency functionality
    // Master/slave signal routing handled by component interconnections
    // ACE-Lite status outputs
    assign coherency_violation = |coherency_violation_per_master || |domain_violation;
    assign barrier_active = |barrier_active_per_master || global_barrier_active;
    assign cache_ops_pending = cache_op_pending_count;
    assign master_coherency_state = coherency_required;

endmodule

//---------------------------------------------------------------------------
// ACE-Lite Coherency Extension Module
//---------------------------------------------------------------------------
module axi_ace_lite
      #(parameter NUM_MASTER = 4
              , NUM_SLAVE  = 4
              , WIDTH_ID   = 4
              , WIDTH_AD   = 32
              , WIDTH_DA   = 32
              , WIDTH_SD_AWUSER = 8
              , WIDTH_SD_WUSER  = 4
              , WIDTH_SD_BUSER  = 4
              , WIDTH_SD_ARUSER = 8
              , WIDTH_SD_RUSER  = 4)
(
      input  wire                    clk
    , input  wire                    rst_n
    // Master 0 interface
    , input  wire [WIDTH_ID-1:0]    m0_awid
    , input  wire [WIDTH_AD-1:0]    m0_awaddr
    , input  wire [1:0]             m0_awdomain
    , input  wire [2:0]             m0_awsnoop
    , input  wire [1:0]             m0_awbar
    , input  wire [WIDTH_SD_AWUSER-1:0] m0_sd_awuser
    , input  wire                   m0_awvalid
    , input  wire                   m0_awready
    , input  wire [WIDTH_SD_WUSER-1:0]  m0_sd_wuser
    , input  wire [WIDTH_ID-1:0]    m0_arid
    , input  wire [WIDTH_AD-1:0]    m0_araddr
    , input  wire [1:0]             m0_ardomain
    , input  wire [3:0]             m0_arsnoop
    , input  wire [1:0]             m0_arbar
    , input  wire [WIDTH_SD_ARUSER-1:0] m0_sd_aruser
    , input  wire                   m0_arvalid
    , input  wire                   m0_arready
    , input  wire [WIDTH_SD_BUSER-1:0]  m0_sd_buser
    , input  wire                   m0_bvalid
    , input  wire                   m0_bready
    , input  wire [WIDTH_SD_RUSER-1:0]  m0_sd_ruser
    , input  wire                   m0_rlast
    , input  wire                   m0_rvalid
    , input  wire                   m0_rready
    // Master 1 interface
    , input  wire [WIDTH_ID-1:0]    m1_awid
    , input  wire [WIDTH_AD-1:0]    m1_awaddr
    , input  wire [1:0]             m1_awdomain
    , input  wire [2:0]             m1_awsnoop
    , input  wire [1:0]             m1_awbar
    , input  wire [WIDTH_SD_AWUSER-1:0] m1_sd_awuser
    , input  wire                   m1_awvalid
    , input  wire                   m1_awready
    , input  wire [WIDTH_SD_WUSER-1:0]  m1_sd_wuser
    , input  wire [WIDTH_ID-1:0]    m1_arid
    , input  wire [WIDTH_AD-1:0]    m1_araddr
    , input  wire [1:0]             m1_ardomain
    , input  wire [3:0]             m1_arsnoop
    , input  wire [1:0]             m1_arbar
    , input  wire [WIDTH_SD_ARUSER-1:0] m1_sd_aruser
    , input  wire                   m1_arvalid
    , input  wire                   m1_arready
    , input  wire [WIDTH_SD_BUSER-1:0]  m1_sd_buser
    , input  wire                   m1_bvalid
    , input  wire                   m1_bready
    , input  wire [WIDTH_SD_RUSER-1:0]  m1_sd_ruser
    , input  wire                   m1_rlast
    , input  wire                   m1_rvalid
    , input  wire                   m1_rready
    // Master 2 interface
    , input  wire [WIDTH_ID-1:0]    m2_awid
    , input  wire [WIDTH_AD-1:0]    m2_awaddr
    , input  wire [1:0]             m2_awdomain
    , input  wire [2:0]             m2_awsnoop
    , input  wire [1:0]             m2_awbar
    , input  wire [WIDTH_SD_AWUSER-1:0] m2_sd_awuser
    , input  wire                   m2_awvalid
    , input  wire                   m2_awready
    , input  wire [WIDTH_SD_WUSER-1:0]  m2_sd_wuser
    , input  wire [WIDTH_ID-1:0]    m2_arid
    , input  wire [WIDTH_AD-1:0]    m2_araddr
    , input  wire [1:0]             m2_ardomain
    , input  wire [3:0]             m2_arsnoop
    , input  wire [1:0]             m2_arbar
    , input  wire [WIDTH_SD_ARUSER-1:0] m2_sd_aruser
    , input  wire                   m2_arvalid
    , input  wire                   m2_arready
    , input  wire [WIDTH_SD_BUSER-1:0]  m2_sd_buser
    , input  wire                   m2_bvalid
    , input  wire                   m2_bready
    , input  wire [WIDTH_SD_RUSER-1:0]  m2_sd_ruser
    , input  wire                   m2_rlast
    , input  wire                   m2_rvalid
    , input  wire                   m2_rready
    // Master 3 interface
    , input  wire [WIDTH_ID-1:0]    m3_awid
    , input  wire [WIDTH_AD-1:0]    m3_awaddr
    , input  wire [1:0]             m3_awdomain
    , input  wire [2:0]             m3_awsnoop
    , input  wire [1:0]             m3_awbar
    , input  wire [WIDTH_SD_AWUSER-1:0] m3_sd_awuser
    , input  wire                   m3_awvalid
    , input  wire                   m3_awready
    , input  wire [WIDTH_SD_WUSER-1:0]  m3_sd_wuser
    , input  wire [WIDTH_ID-1:0]    m3_arid
    , input  wire [WIDTH_AD-1:0]    m3_araddr
    , input  wire [1:0]             m3_ardomain
    , input  wire [3:0]             m3_arsnoop
    , input  wire [1:0]             m3_arbar
    , input  wire [WIDTH_SD_ARUSER-1:0] m3_sd_aruser
    , input  wire                   m3_arvalid
    , input  wire                   m3_arready
    , input  wire [WIDTH_SD_BUSER-1:0]  m3_sd_buser
    , input  wire                   m3_bvalid
    , input  wire                   m3_bready
    , input  wire [WIDTH_SD_RUSER-1:0]  m3_sd_ruser
    , input  wire                   m3_rlast
    , input  wire                   m3_rvalid
    , input  wire                   m3_rready
    // Master 0 Coherency Channels
    , output wire [WIDTH_AD-1:0]    m0_acaddr     // Snoop address
    , output wire [2:0]             m0_acsnoop    // Snoop transaction type
    , output wire [2:0]             m0_acprot     // Snoop protection type
    , output wire                   m0_acvalid    // Snoop address valid
    , input  wire                   m0_acready    // Snoop address ready
    , input  wire [4:0]             m0_crresp     // Snoop response
    , input  wire                   m0_crvalid    // Snoop response valid
    , output wire                   m0_crready    // Snoop response ready
    , input  wire [WIDTH_DA-1:0]    m0_cddata     // Snoop data
    , input  wire [WIDTH_DA/8-1:0]  m0_cdstrb     // Snoop data strobe
    , input  wire                   m0_cdlast     // Snoop data last
    , input  wire                   m0_cdvalid    // Snoop data valid
    , output wire                   m0_cdready    // Snoop data ready

    // Master 1 Coherency Channels
    , output wire [WIDTH_AD-1:0]    m1_acaddr     // Snoop address
    , output wire [2:0]             m1_acsnoop    // Snoop transaction type
    , output wire [2:0]             m1_acprot     // Snoop protection type
    , output wire                   m1_acvalid    // Snoop address valid
    , input  wire                   m1_acready    // Snoop address ready
    , input  wire [4:0]             m1_crresp     // Snoop response
    , input  wire                   m1_crvalid    // Snoop response valid
    , output wire                   m1_crready    // Snoop response ready
    , input  wire [WIDTH_DA-1:0]    m1_cddata     // Snoop data
    , input  wire [WIDTH_DA/8-1:0]  m1_cdstrb     // Snoop data strobe
    , input  wire                   m1_cdlast     // Snoop data last
    , input  wire                   m1_cdvalid    // Snoop data valid
    , output wire                   m1_cdready    // Snoop data ready

    // Master 2 Coherency Channels
    , output wire [WIDTH_AD-1:0]    m2_acaddr     // Snoop address
    , output wire [2:0]             m2_acsnoop    // Snoop transaction type
    , output wire [2:0]             m2_acprot     // Snoop protection type
    , output wire                   m2_acvalid    // Snoop address valid
    , input  wire                   m2_acready    // Snoop address ready
    , input  wire [4:0]             m2_crresp     // Snoop response
    , input  wire                   m2_crvalid    // Snoop response valid
    , output wire                   m2_crready    // Snoop response ready
    , input  wire [WIDTH_DA-1:0]    m2_cddata     // Snoop data
    , input  wire [WIDTH_DA/8-1:0]  m2_cdstrb     // Snoop data strobe
    , input  wire                   m2_cdlast     // Snoop data last
    , input  wire                   m2_cdvalid    // Snoop data valid
    , output wire                   m2_cdready    // Snoop data ready

    // Master 3 Coherency Channels
    , output wire [WIDTH_AD-1:0]    m3_acaddr     // Snoop address
    , output wire [2:0]             m3_acsnoop    // Snoop transaction type
    , output wire [2:0]             m3_acprot     // Snoop protection type
    , output wire                   m3_acvalid    // Snoop address valid
    , input  wire                   m3_acready    // Snoop address ready
    , input  wire [4:0]             m3_crresp     // Snoop response
    , input  wire                   m3_crvalid    // Snoop response valid
    , output wire                   m3_crready    // Snoop response ready
    , input  wire [WIDTH_DA-1:0]    m3_cddata     // Snoop data
    , input  wire [WIDTH_DA/8-1:0]  m3_cdstrb     // Snoop data strobe
    , input  wire                   m3_cdlast     // Snoop data last
    , input  wire                   m3_cdvalid    // Snoop data valid
    , output wire                   m3_cdready    // Snoop data ready

    // Coherency monitoring outputs
    , output reg  [NUM_MASTER-1:0]  coherency_violation
    , output reg                    snoop_required
    , output reg                    barrier_active
    
    // ACE-Lite transaction validation error outputs
    , output wire                   transaction_error      // Aggregate error flag
    , output reg                    ace_lite_txn_error     // ACE-Lite specific errors
    , output reg  [NUM_MASTER-1:0] invalid_write_txn      // Per-master write errors
    , output reg  [NUM_MASTER-1:0] invalid_read_txn       // Per-master read errors
    , output reg  [NUM_MASTER-1:0] unsupported_cache_maint // Unsupported cache maintenance
);

    // ACE-Lite parameters
    localparam WIDTH_DOMAIN = 2;  // Shareability domain
    localparam WIDTH_SNOOP_AW = 3; // Write snoop type
    localparam WIDTH_SNOOP_AR = 4; // Read snoop type
    localparam WIDTH_BAR = 2;     // Barrier type

    // SD_USER signal bit field definitions
    // SD_AWUSER bit fields (coherency attributes for write address)
    localparam SD_AWUSER_CACHE_ALLOC  = 0;  // Cache allocation hint
    localparam SD_AWUSER_CACHE_POLICY = 1;  // Cache policy hint
    localparam SD_AWUSER_QOS_START    = 2;  // QoS field start
    localparam SD_AWUSER_QOS_WIDTH    = 4;  // QoS field width
    localparam SD_AWUSER_SECURE       = 6;  // Security attribute
    localparam SD_AWUSER_PRIV         = 7;  // Privilege level

    // SD_ARUSER bit fields (coherency attributes for read address)
    localparam SD_ARUSER_CACHE_ALLOC  = 0;  // Cache allocation hint
    localparam SD_ARUSER_CACHE_POLICY = 1;  // Cache policy hint
    localparam SD_ARUSER_QOS_START    = 2;  // QoS field start
    localparam SD_ARUSER_QOS_WIDTH    = 4;  // QoS field width
    localparam SD_ARUSER_SECURE       = 6;  // Security attribute
    localparam SD_ARUSER_PRIV         = 7;  // Privilege level

    // SD_WUSER bit fields (coherency attributes for write data)
    localparam SD_WUSER_DIRTY_BIT     = 0;  // Cache line dirty indicator
    localparam SD_WUSER_SHARED_BIT    = 1;  // Shared cache line indicator
    localparam SD_WUSER_ERROR_BIT     = 2;  // Error injection for testing

    // SD_BUSER/SD_RUSER bit fields (response coherency attributes)
    localparam SD_RESP_CACHE_STATE    = 0;  // Cache state after operation
    localparam SD_RESP_SHARED_DIRTY   = 2;  // Shared dirty indication
    localparam SD_RESP_ERROR_INJECT   = 3;  // Error injection response

    // Domain encodings (shareability)
    localparam [1:0] DOMAIN_NON_SHAREABLE = 2'b00;
    localparam [1:0] DOMAIN_INNER_SHAREABLE = 2'b01;
    localparam [1:0] DOMAIN_OUTER_SHAREABLE = 2'b10;
    localparam [1:0] DOMAIN_SYSTEM = 2'b11;

    // Write snoop encodings (ACE-Lite subset)
    localparam [2:0] AWSNOOP_WRITE_NO_SNOOP = 3'b000;
    localparam [2:0] AWSNOOP_WRITE_LINE_UNIQUE = 3'b001;
    localparam [2:0] AWSNOOP_WRITE_CLEAN = 3'b010;
    // Additional ACE-Lite write snoops
    localparam [2:0] AWSNOOP_WRITE_BACK = 3'b011;
    localparam [2:0] AWSNOOP_EVICT = 3'b100;
    localparam [2:0] AWSNOOP_WRITE_EVICT = 3'b101;

    // Read snoop encodings (ACE-Lite subset)
    localparam [3:0] ARSNOOP_READ_NO_SNOOP = 4'b0000;
    localparam [3:0] ARSNOOP_READ_ONCE = 4'b0001;
    localparam [3:0] ARSNOOP_READ_SHARED = 4'b0001;
    localparam [3:0] ARSNOOP_READ_CLEAN = 4'b0010;
    localparam [3:0] ARSNOOP_READ_NOT_SHARED_DIRTY = 4'b0011;
    localparam [3:0] ARSNOOP_READ_UNIQUE = 4'b0111;
    localparam [3:0] ARSNOOP_CLEAN_UNIQUE = 4'b1011;

    // Barrier type encodings
    localparam [1:0] BAR_NORMAL_ACCESS = 2'b00;
    localparam [1:0] BAR_MEMORY_BARRIER = 2'b01;
    localparam [1:0] BAR_RESERVED = 2'b10;
    localparam [1:0] BAR_SYNC_BARRIER = 2'b11;

    // Coherency snoop transaction encodings (ACSNOOP)
    localparam [2:0] ACSNOOP_READ_ONCE        = 3'b000;
    localparam [2:0] ACSNOOP_READ_SHARED      = 3'b001;
    localparam [2:0] ACSNOOP_READ_CLEAN       = 3'b010;
    localparam [2:0] ACSNOOP_READ_NOT_SHARED_DIRTY = 3'b011;
    localparam [2:0] ACSNOOP_READ_UNIQUE      = 3'b111;
    localparam [2:0] ACSNOOP_CLEAN_INVALID    = 3'b100;
    localparam [2:0] ACSNOOP_MAKE_INVALID     = 3'b101;

    // Coherency response encodings (CRRESP)
    localparam [4:0] CRRESP_DATATRANSFER      = 5'b00000;
    localparam [4:0] CRRESP_ERROR             = 5'b00001;
    localparam [4:0] CRRESP_OK_WAS_UNIQUE     = 5'b00010;
    localparam [4:0] CRRESP_OK_SHARED_CLEAN   = 5'b00100;
    localparam [4:0] CRRESP_OK_SHARED_DIRTY   = 5'b01000;
    localparam [4:0] CRRESP_OK_PASS_DIRTY     = 5'b10000;

    // Coherency channel state registers
    reg [NUM_MASTER-1:0] snoop_pending;        // Snoop requests pending per master
    reg [NUM_MASTER-1:0] snoop_response_ready; // Response ready per master
    reg [NUM_MASTER-1:0] snoop_data_pending;   // Data response pending per master
    
    // Coherency checking logic
    // This ensures coherent transactions are handled correctly
    reg coherency_error;
    always @(*) begin
        coherency_error = 1'b0;
        // Check Master 0 coherency
        if (m0_awvalid && m0_awdomain != DOMAIN_NON_SHAREABLE) begin
            // Coherent write transaction
            if (m0_awsnoop == AWSNOOP_WRITE_NO_SNOOP) begin
                // Error: Shareable domain but no snoop
                coherency_error = 1'b1;
            end
        end
        // Check Master 1 coherency
        if (m1_awvalid && m1_awdomain != DOMAIN_NON_SHAREABLE) begin
            // Coherent write transaction
            if (m1_awsnoop == AWSNOOP_WRITE_NO_SNOOP) begin
                // Error: Shareable domain but no snoop
                coherency_error = 1'b1;
            end
        end
        // Check Master 2 coherency
        if (m2_awvalid && m2_awdomain != DOMAIN_NON_SHAREABLE) begin
            // Coherent write transaction
            if (m2_awsnoop == AWSNOOP_WRITE_NO_SNOOP) begin
                // Error: Shareable domain but no snoop
                coherency_error = 1'b1;
            end
        end
        // Check Master 3 coherency
        if (m3_awvalid && m3_awdomain != DOMAIN_NON_SHAREABLE) begin
            // Coherent write transaction
            if (m3_awsnoop == AWSNOOP_WRITE_NO_SNOOP) begin
                // Error: Shareable domain but no snoop
                coherency_error = 1'b1;
            end
        end
    end

    // Coherency Channel State Management
    // Tracks snoop requests and responses for each master
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            snoop_pending <= {NUM_MASTER{1'b0}};
            snoop_response_ready <= {NUM_MASTER{1'b0}};
            snoop_data_pending <= {NUM_MASTER{1'b0}};
        end else begin
            // Master 0 snoop channel state tracking
            if (m0_acvalid && m0_acready) begin
                snoop_pending[0] <= 1'b1;    // Snoop request started
            end
            
            if (m0_crvalid && m0_crready) begin
                snoop_response_ready[0] <= 1'b1; // Response received
                if (m0_crresp[0]) begin  // Check if data transfer required
                    snoop_data_pending[0] <= 1'b1;
                end
            end
            
            if (m0_cdvalid && m0_cdready && m0_cdlast) begin
                snoop_data_pending[0] <= 1'b0;  // Data transfer complete
                snoop_pending[0] <= 1'b0;       // Complete snoop transaction
                snoop_response_ready[0] <= 1'b0;
            end else if (m0_crvalid && m0_crready && !m0_crresp[0]) begin
                // No data required, complete immediately
                snoop_pending[0] <= 1'b0;
                snoop_response_ready[0] <= 1'b0;
            end
            
            // Master 1 snoop channel state tracking
            if (m1_acvalid && m1_acready) begin
                snoop_pending[1] <= 1'b1;    // Snoop request started
            end
            
            if (m1_crvalid && m1_crready) begin
                snoop_response_ready[1] <= 1'b1; // Response received
                if (m1_crresp[0]) begin  // Check if data transfer required
                    snoop_data_pending[1] <= 1'b1;
                end
            end
            
            if (m1_cdvalid && m1_cdready && m1_cdlast) begin
                snoop_data_pending[1] <= 1'b0;  // Data transfer complete
                snoop_pending[1] <= 1'b0;       // Complete snoop transaction
                snoop_response_ready[1] <= 1'b0;
            end else if (m1_crvalid && m1_crready && !m1_crresp[0]) begin
                // No data required, complete immediately
                snoop_pending[1] <= 1'b0;
                snoop_response_ready[1] <= 1'b0;
            end
            
            // Master 2 snoop channel state tracking
            if (m2_acvalid && m2_acready) begin
                snoop_pending[2] <= 1'b1;    // Snoop request started
            end
            
            if (m2_crvalid && m2_crready) begin
                snoop_response_ready[2] <= 1'b1; // Response received
                if (m2_crresp[0]) begin  // Check if data transfer required
                    snoop_data_pending[2] <= 1'b1;
                end
            end
            
            if (m2_cdvalid && m2_cdready && m2_cdlast) begin
                snoop_data_pending[2] <= 1'b0;  // Data transfer complete
                snoop_pending[2] <= 1'b0;       // Complete snoop transaction
                snoop_response_ready[2] <= 1'b0;
            end else if (m2_crvalid && m2_crready && !m2_crresp[0]) begin
                // No data required, complete immediately
                snoop_pending[2] <= 1'b0;
                snoop_response_ready[2] <= 1'b0;
            end
            
            // Master 3 snoop channel state tracking
            if (m3_acvalid && m3_acready) begin
                snoop_pending[3] <= 1'b1;    // Snoop request started
            end
            
            if (m3_crvalid && m3_crready) begin
                snoop_response_ready[3] <= 1'b1; // Response received
                if (m3_crresp[0]) begin  // Check if data transfer required
                    snoop_data_pending[3] <= 1'b1;
                end
            end
            
            if (m3_cdvalid && m3_cdready && m3_cdlast) begin
                snoop_data_pending[3] <= 1'b0;  // Data transfer complete
                snoop_pending[3] <= 1'b0;       // Complete snoop transaction
                snoop_response_ready[3] <= 1'b0;
            end else if (m3_crvalid && m3_crready && !m3_crresp[0]) begin
                // No data required, complete immediately
                snoop_pending[3] <= 1'b0;
                snoop_response_ready[3] <= 1'b0;
            end
            
        end
    end

    // Coherency Channel Timeout Detection
    reg [15:0] snoop_timeout_counter [NUM_MASTER-1:0];
    reg [NUM_MASTER-1:0] snoop_timeout_error;
    
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            snoop_timeout_counter[0] <= 16'h0000;
            snoop_timeout_counter[1] <= 16'h0000;
            snoop_timeout_counter[2] <= 16'h0000;
            snoop_timeout_counter[3] <= 16'h0000;
            snoop_timeout_error <= {NUM_MASTER{1'b0}};
        end else begin
            // Master 0 timeout tracking
            if (snoop_pending[0]) begin
                if (snoop_timeout_counter[0] > 16'hFFF0) begin
                    snoop_timeout_error[0] <= 1'b1;
                end else begin
                    snoop_timeout_counter[0] <= snoop_timeout_counter[0] + 1;
                end
            end else begin
                snoop_timeout_counter[0] <= 16'h0000;
                snoop_timeout_error[0] <= 1'b0;
            end
            
            // Master 1 timeout tracking
            if (snoop_pending[1]) begin
                if (snoop_timeout_counter[1] > 16'hFFF0) begin
                    snoop_timeout_error[1] <= 1'b1;
                end else begin
                    snoop_timeout_counter[1] <= snoop_timeout_counter[1] + 1;
                end
            end else begin
                snoop_timeout_counter[1] <= 16'h0000;
                snoop_timeout_error[1] <= 1'b0;
            end
            
            // Master 2 timeout tracking
            if (snoop_pending[2]) begin
                if (snoop_timeout_counter[2] > 16'hFFF0) begin
                    snoop_timeout_error[2] <= 1'b1;
                end else begin
                    snoop_timeout_counter[2] <= snoop_timeout_counter[2] + 1;
                end
            end else begin
                snoop_timeout_counter[2] <= 16'h0000;
                snoop_timeout_error[2] <= 1'b0;
            end
            
            // Master 3 timeout tracking
            if (snoop_pending[3]) begin
                if (snoop_timeout_counter[3] > 16'hFFF0) begin
                    snoop_timeout_error[3] <= 1'b1;
                end else begin
                    snoop_timeout_counter[3] <= snoop_timeout_counter[3] + 1;
                end
            end else begin
                snoop_timeout_counter[3] <= 16'h0000;
                snoop_timeout_error[3] <= 1'b0;
            end
            
        end
    end

    // ACE-Lite Transaction Type Validation
    // ACE-Lite supports only specific transaction types
    
    // Valid ACE-Lite transaction types
    localparam [2:0] ACELIT_WRITE_NO_SNOOP     = 3'b000; // Non-coherent write
    localparam [2:0] ACELIT_WRITE_LINE_UNIQUE  = 3'b001; // Write with invalidation
    localparam [2:0] ACELIT_WRITE_CLEAN        = 3'b010; // Clean write
    localparam [2:0] ACELIT_EVICT              = 3'b100; // Cache line eviction
    
    localparam [3:0] ACELIT_READ_NO_SNOOP      = 4'b0000; // Non-coherent read
    localparam [3:0] ACELIT_READ_SHARED        = 4'b0001; // Read shared
    localparam [3:0] ACELIT_READ_CLEAN         = 4'b0010; // Read clean
    localparam [3:0] ACELIT_READ_UNIQUE        = 4'b0111; // Read exclusive
    localparam [3:0] ACELIT_CLEAN_SHARED       = 4'b1000; // Cache maintenance
    localparam [3:0] ACELIT_CLEAN_INVALID      = 4'b1001; // Cache maintenance
    localparam [3:0] ACELIT_MAKE_INVALID       = 4'b1101; // Cache maintenance
    
    // Transaction type validation logic
    
    always @(*) begin
        ace_lite_txn_error = 1'b0;
        invalid_write_txn = {NUM_MASTER{1'b0}};
        invalid_read_txn = {NUM_MASTER{1'b0}};
        unsupported_cache_maint = {NUM_MASTER{1'b0}};
        
        // Master 0 transaction validation
        if (m0_awvalid) begin
            // Validate write transactions
            case (m0_awsnoop)
                ACELIT_WRITE_NO_SNOOP: begin
                    // Valid: Non-coherent write allowed
                    if (m0_awdomain != DOMAIN_NON_SHAREABLE) begin
                        invalid_write_txn[0] = 1'b1; // Domain mismatch
                    end
                end
                ACELIT_WRITE_LINE_UNIQUE: begin
                    // Valid: Write with invalidation for coherency
                    if (m0_awdomain == DOMAIN_NON_SHAREABLE) begin
                        invalid_write_txn[0] = 1'b1; // Should be shareable
                    end
                end
                ACELIT_WRITE_CLEAN: begin
                    // Valid: Clean write (write-through)
                end
                ACELIT_EVICT: begin
                    // Valid: Cache line eviction
                end
                default: begin
                    // Invalid: Unsupported write snoop type for ACE-Lite
                    invalid_write_txn[0] = 1'b1;
                end
            endcase
        end
        
        if (m0_arvalid) begin
            // Validate read transactions
            case (m0_arsnoop)
                ACELIT_READ_NO_SNOOP: begin
                    // Valid: Non-coherent read allowed
                    if (m0_ardomain != DOMAIN_NON_SHAREABLE) begin
                        invalid_read_txn[0] = 1'b1; // Domain mismatch
                    end
                end
                ACELIT_READ_SHARED: begin
                    // Valid: Read shared line
                end
                ACELIT_READ_CLEAN: begin
                    // Valid: Read clean (may allocate in cache)
                end
                ACELIT_READ_UNIQUE: begin
                    // Valid: Read exclusive
                end
                ACELIT_CLEAN_SHARED: begin
                    // Valid: Cache maintenance - clean shared lines
                end
                ACELIT_CLEAN_INVALID: begin
                    // Valid: Cache maintenance - clean and invalidate
                end
                ACELIT_MAKE_INVALID: begin
                    // Valid: Cache maintenance - make invalid
                end
                default: begin
                    // Invalid: Unsupported read snoop type for ACE-Lite
                    invalid_read_txn[0] = 1'b1;
                end
            endcase
        end
        
        // Master 1 transaction validation
        if (m1_awvalid) begin
            // Validate write transactions
            case (m1_awsnoop)
                ACELIT_WRITE_NO_SNOOP: begin
                    // Valid: Non-coherent write allowed
                    if (m1_awdomain != DOMAIN_NON_SHAREABLE) begin
                        invalid_write_txn[1] = 1'b1; // Domain mismatch
                    end
                end
                ACELIT_WRITE_LINE_UNIQUE: begin
                    // Valid: Write with invalidation for coherency
                    if (m1_awdomain == DOMAIN_NON_SHAREABLE) begin
                        invalid_write_txn[1] = 1'b1; // Should be shareable
                    end
                end
                ACELIT_WRITE_CLEAN: begin
                    // Valid: Clean write (write-through)
                end
                ACELIT_EVICT: begin
                    // Valid: Cache line eviction
                end
                default: begin
                    // Invalid: Unsupported write snoop type for ACE-Lite
                    invalid_write_txn[1] = 1'b1;
                end
            endcase
        end
        
        if (m1_arvalid) begin
            // Validate read transactions
            case (m1_arsnoop)
                ACELIT_READ_NO_SNOOP: begin
                    // Valid: Non-coherent read allowed
                    if (m1_ardomain != DOMAIN_NON_SHAREABLE) begin
                        invalid_read_txn[1] = 1'b1; // Domain mismatch
                    end
                end
                ACELIT_READ_SHARED: begin
                    // Valid: Read shared line
                end
                ACELIT_READ_CLEAN: begin
                    // Valid: Read clean (may allocate in cache)
                end
                ACELIT_READ_UNIQUE: begin
                    // Valid: Read exclusive
                end
                ACELIT_CLEAN_SHARED: begin
                    // Valid: Cache maintenance - clean shared lines
                end
                ACELIT_CLEAN_INVALID: begin
                    // Valid: Cache maintenance - clean and invalidate
                end
                ACELIT_MAKE_INVALID: begin
                    // Valid: Cache maintenance - make invalid
                end
                default: begin
                    // Invalid: Unsupported read snoop type for ACE-Lite
                    invalid_read_txn[1] = 1'b1;
                end
            endcase
        end
        
        // Master 2 transaction validation
        if (m2_awvalid) begin
            // Validate write transactions
            case (m2_awsnoop)
                ACELIT_WRITE_NO_SNOOP: begin
                    // Valid: Non-coherent write allowed
                    if (m2_awdomain != DOMAIN_NON_SHAREABLE) begin
                        invalid_write_txn[2] = 1'b1; // Domain mismatch
                    end
                end
                ACELIT_WRITE_LINE_UNIQUE: begin
                    // Valid: Write with invalidation for coherency
                    if (m2_awdomain == DOMAIN_NON_SHAREABLE) begin
                        invalid_write_txn[2] = 1'b1; // Should be shareable
                    end
                end
                ACELIT_WRITE_CLEAN: begin
                    // Valid: Clean write (write-through)
                end
                ACELIT_EVICT: begin
                    // Valid: Cache line eviction
                end
                default: begin
                    // Invalid: Unsupported write snoop type for ACE-Lite
                    invalid_write_txn[2] = 1'b1;
                end
            endcase
        end
        
        if (m2_arvalid) begin
            // Validate read transactions
            case (m2_arsnoop)
                ACELIT_READ_NO_SNOOP: begin
                    // Valid: Non-coherent read allowed
                    if (m2_ardomain != DOMAIN_NON_SHAREABLE) begin
                        invalid_read_txn[2] = 1'b1; // Domain mismatch
                    end
                end
                ACELIT_READ_SHARED: begin
                    // Valid: Read shared line
                end
                ACELIT_READ_CLEAN: begin
                    // Valid: Read clean (may allocate in cache)
                end
                ACELIT_READ_UNIQUE: begin
                    // Valid: Read exclusive
                end
                ACELIT_CLEAN_SHARED: begin
                    // Valid: Cache maintenance - clean shared lines
                end
                ACELIT_CLEAN_INVALID: begin
                    // Valid: Cache maintenance - clean and invalidate
                end
                ACELIT_MAKE_INVALID: begin
                    // Valid: Cache maintenance - make invalid
                end
                default: begin
                    // Invalid: Unsupported read snoop type for ACE-Lite
                    invalid_read_txn[2] = 1'b1;
                end
            endcase
        end
        
        // Master 3 transaction validation
        if (m3_awvalid) begin
            // Validate write transactions
            case (m3_awsnoop)
                ACELIT_WRITE_NO_SNOOP: begin
                    // Valid: Non-coherent write allowed
                    if (m3_awdomain != DOMAIN_NON_SHAREABLE) begin
                        invalid_write_txn[3] = 1'b1; // Domain mismatch
                    end
                end
                ACELIT_WRITE_LINE_UNIQUE: begin
                    // Valid: Write with invalidation for coherency
                    if (m3_awdomain == DOMAIN_NON_SHAREABLE) begin
                        invalid_write_txn[3] = 1'b1; // Should be shareable
                    end
                end
                ACELIT_WRITE_CLEAN: begin
                    // Valid: Clean write (write-through)
                end
                ACELIT_EVICT: begin
                    // Valid: Cache line eviction
                end
                default: begin
                    // Invalid: Unsupported write snoop type for ACE-Lite
                    invalid_write_txn[3] = 1'b1;
                end
            endcase
        end
        
        if (m3_arvalid) begin
            // Validate read transactions
            case (m3_arsnoop)
                ACELIT_READ_NO_SNOOP: begin
                    // Valid: Non-coherent read allowed
                    if (m3_ardomain != DOMAIN_NON_SHAREABLE) begin
                        invalid_read_txn[3] = 1'b1; // Domain mismatch
                    end
                end
                ACELIT_READ_SHARED: begin
                    // Valid: Read shared line
                end
                ACELIT_READ_CLEAN: begin
                    // Valid: Read clean (may allocate in cache)
                end
                ACELIT_READ_UNIQUE: begin
                    // Valid: Read exclusive
                end
                ACELIT_CLEAN_SHARED: begin
                    // Valid: Cache maintenance - clean shared lines
                end
                ACELIT_CLEAN_INVALID: begin
                    // Valid: Cache maintenance - clean and invalidate
                end
                ACELIT_MAKE_INVALID: begin
                    // Valid: Cache maintenance - make invalid
                end
                default: begin
                    // Invalid: Unsupported read snoop type for ACE-Lite
                    invalid_read_txn[3] = 1'b1;
                end
            endcase
        end
        
        // Aggregate transaction validation errors
        ace_lite_txn_error = |invalid_write_txn || |invalid_read_txn || |unsupported_cache_maint;
    end
    
    // Error reporting outputs
    wire transaction_error = coherency_error || ace_lite_txn_error;
    
    // SD_USER signal processing and validation
    // Extract coherency attributes from SD_USER signals
    wire m0_cache_alloc_aw, m0_cache_alloc_ar;
    wire m0_secure_aw, m0_secure_ar;
    wire [3:0] m0_qos_aw, m0_qos_ar;
    assign m0_cache_alloc_aw = m0_sd_awuser[SD_AWUSER_CACHE_ALLOC];
    assign m0_cache_alloc_ar = m0_sd_aruser[SD_ARUSER_CACHE_ALLOC];
    assign m0_secure_aw = m0_sd_awuser[SD_AWUSER_SECURE];
    assign m0_secure_ar = m0_sd_aruser[SD_ARUSER_SECURE];
    assign m0_qos_aw = m0_sd_awuser[SD_AWUSER_QOS_START +: SD_AWUSER_QOS_WIDTH];
    assign m0_qos_ar = m0_sd_aruser[SD_ARUSER_QOS_START +: SD_ARUSER_QOS_WIDTH];
    wire m1_cache_alloc_aw, m1_cache_alloc_ar;
    wire m1_secure_aw, m1_secure_ar;
    wire [3:0] m1_qos_aw, m1_qos_ar;
    assign m1_cache_alloc_aw = m1_sd_awuser[SD_AWUSER_CACHE_ALLOC];
    assign m1_cache_alloc_ar = m1_sd_aruser[SD_ARUSER_CACHE_ALLOC];
    assign m1_secure_aw = m1_sd_awuser[SD_AWUSER_SECURE];
    assign m1_secure_ar = m1_sd_aruser[SD_ARUSER_SECURE];
    assign m1_qos_aw = m1_sd_awuser[SD_AWUSER_QOS_START +: SD_AWUSER_QOS_WIDTH];
    assign m1_qos_ar = m1_sd_aruser[SD_ARUSER_QOS_START +: SD_ARUSER_QOS_WIDTH];
    wire m2_cache_alloc_aw, m2_cache_alloc_ar;
    wire m2_secure_aw, m2_secure_ar;
    wire [3:0] m2_qos_aw, m2_qos_ar;
    assign m2_cache_alloc_aw = m2_sd_awuser[SD_AWUSER_CACHE_ALLOC];
    assign m2_cache_alloc_ar = m2_sd_aruser[SD_ARUSER_CACHE_ALLOC];
    assign m2_secure_aw = m2_sd_awuser[SD_AWUSER_SECURE];
    assign m2_secure_ar = m2_sd_aruser[SD_ARUSER_SECURE];
    assign m2_qos_aw = m2_sd_awuser[SD_AWUSER_QOS_START +: SD_AWUSER_QOS_WIDTH];
    assign m2_qos_ar = m2_sd_aruser[SD_ARUSER_QOS_START +: SD_ARUSER_QOS_WIDTH];
    wire m3_cache_alloc_aw, m3_cache_alloc_ar;
    wire m3_secure_aw, m3_secure_ar;
    wire [3:0] m3_qos_aw, m3_qos_ar;
    assign m3_cache_alloc_aw = m3_sd_awuser[SD_AWUSER_CACHE_ALLOC];
    assign m3_cache_alloc_ar = m3_sd_aruser[SD_ARUSER_CACHE_ALLOC];
    assign m3_secure_aw = m3_sd_awuser[SD_AWUSER_SECURE];
    assign m3_secure_ar = m3_sd_aruser[SD_ARUSER_SECURE];
    assign m3_qos_aw = m3_sd_awuser[SD_AWUSER_QOS_START +: SD_AWUSER_QOS_WIDTH];
    assign m3_qos_ar = m3_sd_aruser[SD_ARUSER_QOS_START +: SD_ARUSER_QOS_WIDTH];

    // Coherency attribute validation
    reg [NUM_MASTER-1:0] sd_user_error;
    always @(*) begin
        // Master 0 SD_USER validation
        sd_user_error[0] = 1'b0;
        
        // Check cache allocation hint consistency
        if (m0_awvalid && m0_cache_alloc_aw && (m0_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
            // Error: Cache allocation requested but no snoop
            sd_user_error[0] = 1'b1;
        end
        
        if (m0_arvalid && m0_cache_alloc_ar && (m0_arsnoop == ARSNOOP_READ_NO_SNOOP)) begin
            // Error: Cache allocation requested but no snoop
            sd_user_error[0] = 1'b1;
        end
        
        // Check secure transaction domain consistency
        if (m0_awvalid && m0_secure_aw && (m0_awdomain == DOMAIN_NON_SHAREABLE)) begin
            // Warning: Secure transaction in non-shareable domain
            // This might be intentional but worth monitoring
        end
        // Master 1 SD_USER validation
        sd_user_error[1] = 1'b0;
        
        // Check cache allocation hint consistency
        if (m1_awvalid && m1_cache_alloc_aw && (m1_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
            // Error: Cache allocation requested but no snoop
            sd_user_error[1] = 1'b1;
        end
        
        if (m1_arvalid && m1_cache_alloc_ar && (m1_arsnoop == ARSNOOP_READ_NO_SNOOP)) begin
            // Error: Cache allocation requested but no snoop
            sd_user_error[1] = 1'b1;
        end
        
        // Check secure transaction domain consistency
        if (m1_awvalid && m1_secure_aw && (m1_awdomain == DOMAIN_NON_SHAREABLE)) begin
            // Warning: Secure transaction in non-shareable domain
            // This might be intentional but worth monitoring
        end
        // Master 2 SD_USER validation
        sd_user_error[2] = 1'b0;
        
        // Check cache allocation hint consistency
        if (m2_awvalid && m2_cache_alloc_aw && (m2_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
            // Error: Cache allocation requested but no snoop
            sd_user_error[2] = 1'b1;
        end
        
        if (m2_arvalid && m2_cache_alloc_ar && (m2_arsnoop == ARSNOOP_READ_NO_SNOOP)) begin
            // Error: Cache allocation requested but no snoop
            sd_user_error[2] = 1'b1;
        end
        
        // Check secure transaction domain consistency
        if (m2_awvalid && m2_secure_aw && (m2_awdomain == DOMAIN_NON_SHAREABLE)) begin
            // Warning: Secure transaction in non-shareable domain
            // This might be intentional but worth monitoring
        end
        // Master 3 SD_USER validation
        sd_user_error[3] = 1'b0;
        
        // Check cache allocation hint consistency
        if (m3_awvalid && m3_cache_alloc_aw && (m3_awsnoop == AWSNOOP_WRITE_NO_SNOOP)) begin
            // Error: Cache allocation requested but no snoop
            sd_user_error[3] = 1'b1;
        end
        
        if (m3_arvalid && m3_cache_alloc_ar && (m3_arsnoop == ARSNOOP_READ_NO_SNOOP)) begin
            // Error: Cache allocation requested but no snoop
            sd_user_error[3] = 1'b1;
        end
        
        // Check secure transaction domain consistency
        if (m3_awvalid && m3_secure_aw && (m3_awdomain == DOMAIN_NON_SHAREABLE)) begin
            // Warning: Secure transaction in non-shareable domain
            // This might be intentional but worth monitoring
        end
    end

    // Cache maintenance operation detection
    reg [NUM_MASTER-1:0] cache_maint_wr;
    reg [NUM_MASTER-1:0] cache_maint_rd;
    always @(*) begin
        cache_maint_wr[0] = (m0_awsnoop == AWSNOOP_WRITE_CLEAN) ||
                              (m0_awsnoop == AWSNOOP_WRITE_LINE_UNIQUE) ||
                              (m0_awsnoop == AWSNOOP_EVICT);
        cache_maint_rd[0] = (m0_arsnoop == ARSNOOP_READ_CLEAN) ||
                              (m0_arsnoop == ARSNOOP_CLEAN_UNIQUE);
        cache_maint_wr[1] = (m1_awsnoop == AWSNOOP_WRITE_CLEAN) ||
                              (m1_awsnoop == AWSNOOP_WRITE_LINE_UNIQUE) ||
                              (m1_awsnoop == AWSNOOP_EVICT);
        cache_maint_rd[1] = (m1_arsnoop == ARSNOOP_READ_CLEAN) ||
                              (m1_arsnoop == ARSNOOP_CLEAN_UNIQUE);
        cache_maint_wr[2] = (m2_awsnoop == AWSNOOP_WRITE_CLEAN) ||
                              (m2_awsnoop == AWSNOOP_WRITE_LINE_UNIQUE) ||
                              (m2_awsnoop == AWSNOOP_EVICT);
        cache_maint_rd[2] = (m2_arsnoop == ARSNOOP_READ_CLEAN) ||
                              (m2_arsnoop == ARSNOOP_CLEAN_UNIQUE);
        cache_maint_wr[3] = (m3_awsnoop == AWSNOOP_WRITE_CLEAN) ||
                              (m3_awsnoop == AWSNOOP_WRITE_LINE_UNIQUE) ||
                              (m3_awsnoop == AWSNOOP_EVICT);
        cache_maint_rd[3] = (m3_arsnoop == ARSNOOP_READ_CLEAN) ||
                              (m3_arsnoop == ARSNOOP_CLEAN_UNIQUE);
    end

    // Barrier transaction handling
    reg [NUM_MASTER-1:0] barrier_pending;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            barrier_pending <= {NUM_MASTER{1'b0}};
        end else begin
            if (m0_awvalid && (m0_awbar != BAR_NORMAL_ACCESS)) begin
                barrier_pending[0] <= 1'b1;
            end else if (m0_bvalid && m0_bready) begin
                barrier_pending[0] <= 1'b0;
            end
            if (m1_awvalid && (m1_awbar != BAR_NORMAL_ACCESS)) begin
                barrier_pending[1] <= 1'b1;
            end else if (m1_bvalid && m1_bready) begin
                barrier_pending[1] <= 1'b0;
            end
            if (m2_awvalid && (m2_awbar != BAR_NORMAL_ACCESS)) begin
                barrier_pending[2] <= 1'b1;
            end else if (m2_bvalid && m2_bready) begin
                barrier_pending[2] <= 1'b0;
            end
            if (m3_awvalid && (m3_awbar != BAR_NORMAL_ACCESS)) begin
                barrier_pending[3] <= 1'b1;
            end else if (m3_bvalid && m3_bready) begin
                barrier_pending[3] <= 1'b0;
            end
        end
    end

    // Output assignments for transaction validation errors
    assign transaction_error = coherency_error || ace_lite_txn_error;
    
    // Continuous assignment outputs are handled by the validation logic above
    // ace_lite_txn_error, invalid_write_txn, invalid_read_txn are driven by always block

endmodule

//--------------------------------------------------------
// Enhanced Validation Framework - Auto-generated Checks
//--------------------------------------------------------

    //--------------------------------------------------------
    // Auto-generated Parameter Validation Checks
    //--------------------------------------------------------
    initial begin : parameter_validation
        // Master/Slave count validation
        if (NUM_MASTER < 2) begin
            $error("[PARAM_CHECK] NUM_MASTER (34) must be >= 2", NUM_MASTER);
        end
        if (NUM_SLAVE < 1) begin
            $error("[PARAM_CHECK] NUM_SLAVE (33) must be >= 1", NUM_SLAVE);
        end

        // Address/Data width validation
        if (WIDTH_AD < 8 || WIDTH_AD > 64) begin
            $error("[PARAM_CHECK] WIDTH_AD (49) must be 8-64 bits", WIDTH_AD);
        end
        if (WIDTH_DA < 32 || WIDTH_DA > 1024) begin
            $error("[PARAM_CHECK] WIDTH_DA (52) must be 32-1024 bits", WIDTH_DA);
        end
        if ((WIDTH_DA & (WIDTH_DA-1)) != 0) begin
            $error("[PARAM_CHECK] WIDTH_DA (50) must be power of 2", WIDTH_DA);
        end

        // ACE-Lite specific validation
        `ifdef AMBA_ACE_LITE
        if (CONFLICT_COUNT_WIDTH < $clog2(NUM_MASTER)) begin
            $warning("[ACE_LITE_CHECK] CONFLICT_COUNT_WIDTH (61) may be insufficient for NUM_MASTER (2880)", CONFLICT_COUNT_WIDTH, NUM_MASTER);
        end
        if (MAINT_PRIORITY_WIDTH < 2) begin
            $error("[ACE_LITE_CHECK] MAINT_PRIORITY_WIDTH (44) must be >= 2", MAINT_PRIORITY_WIDTH);
        end
        `endif

        $display("[PARAM_CHECK] Parameter validation completed successfully");
    end

    //--------------------------------------------------------
    // Auto-generated Protocol Compliance Checks
    //--------------------------------------------------------
    `ifdef ENABLE_PROTOCOL_CHECKS
    // ACE-Lite 4KB boundary check
    always @(posedge ACLK) begin
        if (ARESETn) begin
            if (M0_AWVALID && M0_AWREADY) begin
                if ((M0_AWADDR & 12'hFFF) + (M0_AWLEN + 1) * (1 << M0_AWSIZE) > 4096) begin
                    $error("[PROTOCOL_CHECK] Master 0 transaction crosses 4KB boundary at address 0x%h", M0_AWADDR);
                end
            end
            if (M1_AWVALID && M1_AWREADY) begin
                if ((M1_AWADDR & 12'hFFF) + (M1_AWLEN + 1) * (1 << M1_AWSIZE) > 4096) begin
                    $error("[PROTOCOL_CHECK] Master 1 transaction crosses 4KB boundary at address 0x%h", M1_AWADDR);
                end
            end
            if (M2_AWVALID && M2_AWREADY) begin
                if ((M2_AWADDR & 12'hFFF) + (M2_AWLEN + 1) * (1 << M2_AWSIZE) > 4096) begin
                    $error("[PROTOCOL_CHECK] Master 2 transaction crosses 4KB boundary at address 0x%h", M2_AWADDR);
                end
            end
            if (M3_AWVALID && M3_AWREADY) begin
                if ((M3_AWADDR & 12'hFFF) + (M3_AWLEN + 1) * (1 << M3_AWSIZE) > 4096) begin
                    $error("[PROTOCOL_CHECK] Master 3 transaction crosses 4KB boundary at address 0x%h", M3_AWADDR);
                end
            end
        end
    end

    `endif // ENABLE_PROTOCOL_CHECKS

